  CollectionHall_100442_Desc = {
    Text = "<Title:পরিচিতি>\nএক ধনী মানব বণিক পরিবারে জন্মগ্রহণ করলেও, তার শিরায় বহমান ছিল ঘুলের রক্ত। অর্ধ-মানব অর্ধ-ঘুল এই রক্তধারা তাকে দিয়েছিল এক অনন্য প্রতিভা, যা তাকে সাধারণ মানুষের অদৃশ্য এক জগৎ দেখার ক্ষমতা দিয়েছিল। সেই জগৎ ছিল উন্মাদ, উদ্ভট, আর এর চোখ-ধাঁধানো রঙের বৈচিত্র্য তাকে মোহাবিষ্ট করে রেখেছিল।\nপ্রায় কোনো দ্বিধা ছাড়াই, পিকম্যান তার তুলি দিয়ে যা কিছু দেখেছিল তা লিপিবদ্ধ করার সিদ্ধান্ত নিয়েছিল। সে এতে নিমগ্ন হয়ে পড়েছিল, এবং দিনের পর দিন আঁকতে আঁকতে অসাধারণ চিত্রকলার দক্ষতা অর্জন করেছিল।\nমূলধারার রুচিবোধ পিকম্যানকে সম্পূর্ণরূপে প্রত্যাখ্যান করেছিল, কেউই তার সেই উন্মাদ তত্ত্ব মেনে নিতে পারেনি। পিকম্যান প্রায়ই এতে দুঃখ পেত, কিন্তু সে কখনো হাল ছাড়েনি।\nঅবশেষে, পিকম্যান ক্ষয়কে আলিঙ্গন করে তার ঘুল রক্তধারাকে সম্পূর্ণরূপে জাগ্রত করেছিল। সে মানব জগৎ ত্যাগ করে ঘুলদের রাজধানীতে এসেছিল। একদিন, সে বাস্তব জগতের সেই সমস্ত অলৌকিক ও উন্মাদ দৃশ্যাবলী একে একে বিশ্ববাসীর সামনে উপস্থাপন করবে।"
