  CollectionHall_117987_Desc = {
    Text = "আমরা তোমার জন্য এক নিখুঁত ছুটি প্রস্তুতি করেছি! আছে সমুদ্রতট, রোদ, ভলিবল ম্যাচ, পুরোনো আর নতুন বন্ধু...\nসানস্ক্রিন নিতে ভুলো না, আর যদি দেখো সূর্য পড়ে যাচ্ছে, দয়া করে আতঙ্কিত হয়ো না—ওটা আসলে বেশ স্বাভাবিক।"
