  CollectionHall_117989_Desc = {
    Text = "দরিদ্র, আত্মগর্বী, বেপরোয়া নেকড়ে।\nএক মুহূর্তের শান্ত জুয়ার জন্য সে অন্য অতিথিদের সঙ্গে লাউঞ্জে আটকা পড়েছিল।\nতার স্বাভাবিক সৌভাগ্য যেন কোথায় হারিয়ে গিয়েছিল, আর সেই খেলায় সে হারাল দশ হাজারেরও বেশি লিওনীয় ফ্লোরিন।"
