  CollectionHall_117990_Desc = {
    Text = "একই টুপি, একই গোলাপ, একই হাসি।\nপর্দা উঠেছে, দর্শকরা আসন নিয়েছে। এসো, খুঁজে বের করো—ম্লান হয়ে যাওয়া কালো কুয়াশা ভেদ করে যে বেরিয়ে আসবে, তাদের মধ্যে খুনি কে?"
