  CollectionHall_121341_Desc = {
    Text = "<Title:পরিচিতি>\nযে 「রাজকুমারী」 「পবিত্র শিশু」 ধারণের দায়িত্ব গ্রহণ করেছিলেন, তিনি এখন সমুদ্রযাত্রী ধর্মসম্প্রদায়ের এক অত্যন্ত গুরুত্বপূর্ণ 「দেবমাতা」।\nতিনিও একসময় স্বাধীনতার দিকে ছুটে চলা এক ভদ্রমহিলা ছিলেন, মিসাগের নথিভুক্ত মার্ফির মতোই সোনানিয়েল জাহাজে পলায়নের যাত্রায় পা রেখেছিলেন।\nকিন্তু রহস্যরক্ষকবিহীন এক পৃথিবীতে, নিয়তি সেই কিশোরী রাজহংসীর মহিমান্বিত গ্রীবা ভেঙে দিয়েছিল।\nবিকৃত রক্তধারা কোনো যুক্তি না মেনে, কোনো প্রতিরোধ না শুনে তাকে জড়িয়ে ধরেছিল — এমনকি দেহকে মৃত্যুর হাতে ছেড়ে দিলেও রেহাই ছিল না। সে কষ্টে মুখ রক্ষা করে বলে যাওয়া প্রতিটি 「আমি মহিমান্বিত দেবমাতা」 — সবই ছিল কেবল নিজেকে দেওয়া ইঙ্গিত ও আত্মপ্রবোধন।\nকেবল মান্য করা, শুধুই মান্য করা। মিথ্যা দৈববাণী মান্য করা, উদ্ভট নিয়তি মান্য করা, আর তারপর অন্তহীন তিক্ততার মধ্য থেকে কোনোমতে সেই এক ফোঁটা কল্পনার মিষ্টতা আস্বাদন করা।"
  },
  CollectionHall_121341_LockTip = {
    Text = "「মার্ফি: ফক্সবর্ন」 জাগিয়ে তোলো"
