  CollectionHall_121381_Desc = {
    Text = "তুমি 1000টি একর বদলে অন্য এক জগতের গল্প পেয়েছ।\nনায়ক আর দানব-দেবতার গল্প, নজরদারি আর অধ্যবসায়ের গল্প।\nঅসহায়তা আর অনিচ্ছার গল্প, পুরাতন বন্ধু আর নতুনের গল্প।\nএক গল্প, যা একসময় ছিল।"
