  },
  CollectionHall_121407_Desc = {
    Text = "যোদ্ধা। প্রতিশোধকারী। দাস। প্রভু। বণিক।\nএকই ভঙ্গি? ভিন্ন ভঙ্গি? একই ভঙ্গি।"
