  CollectionHall_121407_Title = {
    Text = "বহুবিশ্বের যুদ্ধগান"
  },
  CollectionHall_121408_Desc = {
    Text = "তুমি জানো, তুমি কোনো মহৎ কিছুর জন্য লড়ছ না।\nএটা ক্লাস ফাঁকি দেওয়ার জন্য, বাড়ির কাজের জন্য, মিষ্টান্নের জন্য, বন্ধুদের জন্য, অগ্নিকুণ্ডের উষ্ণতার জন্য, অকাজে সময় নষ্ট করার জন্য।\nতুমি কেবল এক সাধারণ মানুষ, যে প্রাণ দেয় এক সাধারণ দিনের জন্য।"
  },
  CollectionHall_121408_LockTip = {
    Text = "কঠিন স্টেজ 9-11 সম্পন্ন করুন"
  },
  CollectionHall_121408_Title = {
    Text = "একটি সাধারণ দিনের শহিদ"
  },
  CollectionHall_121409_Desc = {
    Text = "প্রাণী, সব উচ্চতর প্রাণীই, অবধারিতভাবে সামাজিক আচরণের নিয়মে শাসিত হয়।\nতবু সে নিজেই মৃত্যুর দিকে অগ্রসর হয়, এবং কাম্য সেই পথেই সত্যকে ভেঙে টুকরো টুকরো করে।\nউন্মাদ, অতুলনীয় এক প্রতিভা, সে বরং নিজ হাতেই ধ্বংস ডেকে আনতে চায়, যেন সংবেদনশীল সত্তাদের মুক্তি দিতে পারে সেই আর্সেনিক-নামা আশার গ্রাস থেকে।"
  },
  CollectionHall_121409_LockTip = {
    Text = "স্টেজ 9-13 সম্পন্ন করুন"
  },
  CollectionHall_121409_Title = {
    Text = "সমাজের আচরণের অবনির্মাণ"
  },
  CollectionHall_121410_Desc = {
    Text = "অন্তহীন তিক্ত জলের স্রোত তিনি উচ্চ স্বর্গ থেকে পাঠিয়েছিলেন, যা জমা হতে হতে, মিলতে মিলতে\nএক নদীতে রূপ নিল—যে নদী আমাদের অতিক্রম করতেই হবে, আমাদের মাংস আর রক্ত জড়িয়ে যাওয়ার আগে।"
  },
  CollectionHall_121410_LockTip = {
    Text = "স্বপ্নদৃশ্য 「আকাশের ওপারে·পর্ব II」 সম্পন্ন"
