  CollectionHall_121410_Title = {
    Text = "তিক্ত নদী"
  },
  CollectionHall_121411_Desc = {
    Text = "তারা বিদায় জানায় পুনর্মিলনের প্রত্যাশা নিয়ে।\nকারণ এ যে প্রিয়তম, আর প্রিয়তমের মৃত্যু কখনোই নিয়তির বিধান নয়।"
