  },
  CollectionHall_121412_Desc = {
    Text = "একটু বিরতি নাও, শ্বাসটা গুছিয়ে নাও।\nবিষয় যদি প্রলয়ও হয়, তবু সকলে তো আর একসঙ্গে এমন তিনজন মহাপরাক্রমশালী গুরুর মুখোমুখি হওয়ার সুযোগ পায় না।"
