  CollectionHall_121414_Desc = {
    Text = "উন্মাদনা, যা ধ্বংসের প্রস্তাবনা, সেটাই শৃঙ্খলাবদ্ধ জগতের অন্তর্নিহিত যুক্তি।\nওটি কি বিলীন হবে? জগত কি ধ্বংস হবে?\nকেউ জানে না।\nকিন্তু স্রষ্টার সম্মুখে, উন্মাদনাই তাদের এবং এই জগতের মৃত্তিকা বিদীর্ণ পুনর্জন্মকে লালন করছে।"
