  CollectionHall_121414_Title = {
    Text = "উন্মাদনা ফিউগ"
  },
  CollectionHall_121415_Desc = {
    Text = "বিশ্বের সবচেয়ে অযৌক্তিক বস্তুটি কী?\nওটা। তার কোনো উদ্দেশ্য নেই, কোনো ক্ষোভ নেই, সে ভালো-মন্দের ভেদরেখা টানে না।\nসে কেবল চায়, জেগে উঠে, স্বপ্নে জন্ম নেওয়া সবকিছুকে পরিণত করতে ধুলো আর ছাইয়ে।"
