  CollectionHall_121417_Desc = {
    Text = "মানব সভ্যতার দীর্ঘ বিস্তারে আমরা নির্মাণ করেছি অগণিত বস্তু।\nআছে পদার্থ, আছে আত্মা; আছে বেঁচে থাকা, প্রেম, দ্বন্দ্ব, আর যুদ্ধ।\nতবু, স্রষ্টার স্বপ্নে এ সবই কেবল তুচ্ছ কোলাহল, আর এক কাল্পনিক সংকলন, যার ব্যাখ্যায় আমরা দীর্ঘকাল উদাসীন।"
