  },
  CollectionHall_124125_Title = {
    Text = "তার, তার, এবং তার মৃত্যু"
  },
  CollectionHall_124126_Desc = {
    Text = "তুমি কীভাবে বর্ণনা করবে সেই সঙ্গীকে, যে তার দীপ্তির চূড়ায় পৌঁছে চলে গেছে?\nতার জ্যোতির কথা বলো না। বলো তার বাহুর ঠান্ডা ধাতুর কথা; বলো তার চলে যাওয়ার পরও যে দেবদারুর গন্ধ ভেসে থাকত, তার কথা।"
