  CollectionHall_124224_Title = {
    Text = "মুশেটের পরজগত তদন্তের নথি"
  },
  CollectionHall_124395_Desc = {
    Text = "লোটানের জীবনের সবচেয়ে যন্ত্রণাদায়ক ও পরিতৃপ্তিময় সেই দিনে, তার হাতের ব্লেড ঝড়ের মতো সামনের দেবতার দিকে ধেয়ে গেল। বিশাল তলোয়ার এবং লেভিয়াথানের গ্রহের মতো বিশাল দেহ একসাথে, সেই ঝড়ে টুকরো টুকরো হয়ে গেল।\nরক্তের মুকুট সেই অশ্বারোহী দলের দাসকে উপহার দেওয়ার পরে, বিনিময়ে লোটান শুধু একটি দাবি করল: তার একটি নতুন অস্ত্র দরকার।\nলোটানের প্রতি ভয় ও শ্রদ্ধা নিয়ে, নতুন রাজা লেভিয়াথানের হাড় নামিয়ে আনার আদেশ দিলেন, তার জন্য এক অতুলনীয় জোড়া বিশাল তলোয়ার তৈরি করতে। ছয় রাজ্যের সেরা কামারদের দিনরাত ঢালাই ও পরিশোধনের মধ্যে, একটি মৃত দেবতার হাড়, দেবতাঘাতকের হাতে নবজন্ম পেল।\nএক স্মরণযোগ্য প্রতিদ্বন্দ্বী এই অবিনাশী দুটি ব্লেডের সাক্ষ্য দিয়েছিলেন। তার বিশাল হাতুড়ি লোটানের বর্ম ও বিশাল তলোয়ার চূর্ণ করেছিল, ফাটল মাকড়সার জালের মতো তলোয়ারের গায়ে বিস্তার লাভ করেছিল, দুধসাদা টুকরোগুলো রক্তাক্ত বাতাসে ছিটকে পড়েছিল, ঠিক যেদিন সে লেভিয়াথানকে বিদ্ধ করেছিল সেদিনের মতো। সে ভেবেছিল দুর্বলতা খুঁজে পেয়েছে। তারপর, সে দেখল লোটান তার সামনে আবার উঠে দাঁড়াল, সেই ভেঙে পড়ার কথা ছিল এমন বিশাল তলোয়ার তার বুক ভেদ করল, তার কারো শোষণ করতে লাগল। নতুন অস্থি ভাঙা স্থান থেকে উৎসারিত হলো, আগের চেয়ে আরও তীক্ষ্ণ, আরও ঘন। ভাঙা প্রান্ত গিঁট থেকে বেড়ে উঠল, যেন বন্য প্রান্তরে পাগলের মতো বেড়ে ওঠা কণ্টক। সে স্পষ্ট অনুভব করল, তার জীবন সেই শ্বেত অস্থি নির্মিত ব্লেড দ্বারা চিবানো ও গেলা হচ্ছে।\nআসলে, সেই একসময় নক্ষত্রাকাশ গ্রাস করা বিশাল দানব কখনো মরেনি। চুক্তি স্বাক্ষরের মুহূর্ত থেকেই, সে তার সাথে একীভূত হয়ে গিয়েছিল। যতবার লোটান বিশাল তলোয়ার তুলত, তলোয়ারের গায়ের অস্থি-স্পাইক প্রস্ফুটিত হতো, তার তীক্ষ্ণ স্পাইক দিয়ে প্রতিদ্বন্দ্বীকে নিষ্ঠুর উল্লাসে অভিবাদন জানাত।\nএটি তার অস্ত্র। সে তার দুই পা। সে ও এটি, শুরু থেকে শেষ পর্যন্ত একই আকাঙ্ক্ষায় আবদ্ধ। তারা অমর, অবিনাশী, চিরতৃপ্তিহীন।\nকখনো না থামা যুদ্ধক্ষেত্রই তাদের একমাত্র গন্তব্য।"
  },
