  CollectionHall_124407_Desc = {
    Text = "সাত বছরের জন্মদিনে, বাবা তার কোলে 「মোইরাই」 নামের একটি চরকা রেখে দিলেন। সেই নামটি ছিল তিন ভাগ্যদেবীর, যাদের আর কেউ পূজা করে না, কিন্তু চরকাটি ছিল মসৃণ ও নতুন, তামার অক্ষে ধাতব দীপ্তি, শীতল ও ভারী।\nসেই দিন থেকে, আরাকনে ভাগ্যের চাকা তুলে নিল, নিজের ইচ্ছায় নয়, বরং কারণ তার অনিচ্ছাকৃত কথাগুলো পরবর্তীতে সত্য হয়ে যেত, এবং সে এই নিয়তি-নির্ধারিত দায়িত্ব এড়াতে পারেনি।\nসেই দিন থেকে, সে বুনে চলেছে, দিনের পর দিন, ভাগ্যের সুতো নিখুঁত চরকায় নীরবে ঘুরতে দেখেছে, মানুষের জন্য বুনেছে প্রথম চুম্বনের কম্পন, যুদ্ধাশ্বের হ্রেষা, শিশুর প্রথম কান্না, আর সমাধিপাথরে খোদাই করা রুক্ষ দাগ।\nসেই দিন থেকে, সে অসংখ্য জড়ানো সুতোর মধ্য থেকে 「আরও ভালো」 পথগুলো বেছে নিয়েছে, ঘোর মহামারীকে সময়ের আগেই ভাটায় পাঠিয়েছে, ইতিহাসকে যুদ্ধের আগুন থেকে বাঁচিয়েছে, ধ্বংসস্তূপের মধ্যে সভ্যতাকে পুনর্নির্মাণ করেছে... আর একই সাথে, সে সেই সুতোগুলোও বুনেছে যা উন্মাদনা, বিশ্বাসঘাতকতা বা চিরন্তন অন্ধকারের দিকে নিয়ে যায়, শুধু কাল-পরিসর জুড়ে বিস্তৃত সেই ভাগ্যের জালকে টিকিয়ে রাখতে।\n「কোনটা আরও ভালো?」\nনীরব চরকা উত্তর দেয় না, শুধু ঘুরতে থাকে। ভালো, মন্দ, জন্ম কিংবা মৃত্যুসংবাদ, একই সুতোয় পালাক্রমে ভেসে ওঠে। তখনকার তরুণী সে জানত না তার নিয়তি কী, তবু অগণিত সুতোর প্রান্তে, সে পৃথিবীর পরিণতি দেখতে পেয়েছিল।\n「যদি পৃথিবী ধ্বংসের নিয়তি এড়াতে না পারে...」\n「না, আমি এই পৃথিবীকে ভালোবাসি।」\nআরাকনে চরকার দিকে তাকিয়ে, অব্যক্ত ভাবনাগুলো ত্যাগ করল।\n「তাহলে... আমার নিয়তি কী?」\nসে বিড়বিড় করল, শুধু শূন্য প্রতিধ্বনি চার দেয়ালে ঘুরে বেড়াল।\n...\nকত সভ্যতা যে ভাগ্যের জালে উত্থিত হয়ে আবার ভেঙে পড়েছে তার হিসাব নেই, পিরামিড বালিতে ঘুমিয়ে পড়েছে, মহাকাশযান নক্ষত্রসাগর পেরিয়ে গেছে, ভাষা ঋতুর মতো বদলে গেছে, দেবতাদের নাম ধুলোমাখা অভিধানে লেখা হয়েছে... আর সে সবসময় সেখানে বসে থেকেছে, হাতের চরকা ঘুরিয়েছে, মানবজাতিকে বারবার আশা ও ধ্বংসের চক্র পুনরাভিনয় করতে দেখেছে।\nযতক্ষণ না একদিন, একটি মৃদু ডাক চিরন্তন কারাগার ও যুগ-যুগান্তরের নীরবতা অতিক্রম করল।\n「দিদি...」\nসে অবশেষে প্রলয়ের দিকে নিবদ্ধ দৃষ্টি ফিরিয়ে আনল, চোখ বন্ধ করে নেফরিয়ার দিকে তাকাল, তার শরীরের ভেতরের আরেকটি নিজ—সেই নবজাতকের মতো নির্মল চোখে কোনো বিচার নেই, কোনো ভয় নেই, শুধু সম্পূর্ণ বিশ্বাস, যেন একটি ফাঁকা সাদা কাগজ যেখানে এখনো কলম পড়েনি।\nসেই মুহূর্তে, আরাকনে অবশেষে জানতে পারল, ভালোবাসা ও দায়িত্ব, ঘৃণা ও ধ্বংস, সবকিছু নিয়তির সামনে সমান। তাই, সে নিজের হাতে কেটে ফেলা, পরিত্যক্ত স্মৃতিগুলো—যে যন্ত্রণা, আক্ষেপ ও হারানোর বেদনা ঘটার কথা ছিল কিন্তু কখনো আসেনি—সেগুলো একটি সুতোয় বুনে, সবচেয়ে ভারী অথচ সবচেয়ে কোমল উপহার হিসেবে, নেফরিয়ার কব্জিতে বেঁধে দিল।\n「এখান থেকে চলে যাও, নেফরিয়া।」 আরাকনে মৃদু হাসল, 「তুমি মুক্ত।」\nআরাকনের আর নিজের নিয়তি জানার প্রয়োজন নেই। কারণ সাত বছর বয়সে চরকা তুলে নেওয়ার সেই মুহূর্তেই, সে ভবিষ্যতের পথ বেছে নিয়েছিল। আর নিয়তির চরকা নীরবে ঘুরতে থাকবে, সাক্ষী হবে সেই যুদ্ধের যেখানে সে ঝাঁপিয়ে পড়তে চলেছে, যে যুদ্ধের কোনো সমাপ্তি নেই।"
  },
  CollectionHall_124407_Title = {
