  CollectionHall_124413_Desc = {
    Text = "বইয়ের তাকে নীরস গবেষণা সাহিত্যের পাশাপাশি কয়েকটি চমৎকার শিশুতোষ বইও রয়েছে।\n《সিন্ডারেলা》, 《স্নো হোয়াইট》, 《মৎস্যকন্যা》, 《র‍্যাপানজেল》…… এগুলোর মালিক কেন এই বইগুলো তাকে রেখেছিলেন——তা এখন আর জানার উপায় নেই।\nসেই গল্পগুলো বাস্তব থেকে সম্পূর্ণ ভিন্ন কাহিনি বুনে যায়। 「রাজকুমার」, 「রাজকুমারী」, 「ভালোবাসা」…… এই শব্দগুলো কিশোরীর হৃদয়ে দুরন্ত স্পন্দন জাগায়।\nরাতের আকাশে অগণিত আলোর ঝিলিক মাটিতে ঝরে পড়ে, যেন এক প্রবাহিত আলোর নদী হয়ে উঠতে চলেছে।\nচাঁদের আলোয় স্নাত হয়ে, কিশোরী চুপিচুপি পায়ের আঙুলে ভর দিয়ে দাঁড়ায়, যেন এক জোড়া স্বচ্ছ কাচের জুতো পরেছে। মনে হয় সে চিরকাল অপেক্ষা করে আসছে——এই গভীর, নিঃসঙ্গ দীর্ঘ রাত অবশেষে ভোরের আলোয় ভেঙে যাবে……"
