  CollectionHall_124414_Desc = {
    Text = "বাণিজ্যিক জাহাজ থেকে জাহাজে ঘুরে বেড়ানো, সবসময় নিজের অবয়ব পুরনো ছেঁড়া কোটের ছায়ায় লুকিয়ে রাখা বৃদ্ধ জাদুকরী বলেছিলেন, কম্পাস মানুষকে সেই জায়গায় নিয়ে যাবে যেখানে তার যাওয়া উচিত, নাবিকরা হাসতে হাসতে তার ভেষজ গন্ধমাখা কথাকে উপহাস করল, পাঁচটি লিও পাড়ার মুদ্রা ছুঁড়ে দিয়ে এই সুন্দর পিতলের অলংকারটি নিয়ে গেল।\nতারপর তারা পরে নাম হারিয়ে ফেলা এক ছোট্ট শহরের বন্দরে নোঙর করল, পন্টোস এই গল্পটা পছন্দ করত, কম্পাসের মালিক পন্টোসকে পছন্দ করত।\nঅবশ্যই, রসিক, প্রাণবন্ত, বায়ুর মতো অবাধে আসা-যাওয়া করা পন্টোসকে কেউ অপছন্দ করত না।\nএটি আসলে একটি সুন্দর স্মারক হওয়ার কথা ছিল, পন্টোস তার প্রিয় ভাগ্নেকে দেওয়ার পরে, দূর দিগন্তের কল্পনার দরজা খোলার চাবি হওয়ার কথা ছিল—কিন্তু এটি পন্টোসকে তাকে খুঁজে পেতে দিচ্ছিল না, পন্টোস অনুমতি দেয়নি, এবং কখনোই তার জীবনে অন্য কোনো সম্ভাবনা থাকতে দেবে না।\nযখন অনেক বছর কেটে গেল, পন্টোস চাঁদের আলোয় অসংখ্য কালো রাত পার করে, এপোয়ান্সে ফিরে আসার কথা সেই অবয়বটিকে খুঁজতে খুঁজতে, সে এভাবেই ভাবছিল।\nওহ, সেই নিষ্ফল, সুরক্ষামূলক মন্ত্র তাকে ছেড়ে চলে গেছে, পন্টোস এখন তাকে ফিরিয়ে আনতে পারবে।\nশুধু পন্টোস তখনও জানত না, 「কম্পাস মানুষকে সেই জায়গায় নিয়ে যাবে যেখানে তার যাওয়া উচিত」, যেমন প্রতিটি জাহাজের নিজস্ব পথ আছে, ভিন্ন মানুষ সবসময় ভিন্ন দিক বেছে নেয়।"
