  CollectionHall_124844_Desc = {
    Text = "<Title:পরিচিতি>\nতাইমুলান থেকে আগত এক রহস্যময় তরুণী। তার বর্ণনা অনুযায়ী, সে মূলত স্থানীয় বিশ্ববিদ্যালয়ের একজন হবু শিক্ষার্থী ছিল, কিন্তু এক 「নিয়তি-নির্ধারিত রোমান্টিক সাক্ষাৎ」-এর ফলে কুয়াশা অঞ্চল অনুসন্ধান দলের অগ্রগামী সদস্য হয়ে ওঠে।\nতারকাময় প্রভাত সভার 「কুয়াশা বিপর্যয় ঘটনা」-য়, মোশিয়া আকস্মিকভাবে এই জগতে আহ্বানিত হয়, এবং পরবর্তীতে রৌপ্য ও রক্তের আচারে সে দীক্ষা লাভ করে, মানব থেকে জাগ্রত সত্তায় রূপান্তরিত হয় এবং 「কুয়াশা বিপর্যয় ঘটনা」-র অবসান ঘটায়।\nনিজের নয় এমন এক জগতে অবস্থান করেও, সে এখনও ফিরে যাওয়ার উপায় খুঁজে চলেছে, কিন্তু একই সাথে, এই জগতের ভবিষ্যৎ নিয়েও তার মনে গভীর আগ্রহ রয়েছে এবং সে 「বিশ্বের পরিণতি」 প্রত্যক্ষ করতে আকুল।"
