  CollectionHall_126472_Desc = {
    Text = "প্রতিটি কুয়াশা একদিন না একদিন কেটে যেতেই হবে।\nযখন তা সরে যাবে, যে আর্তনাদ একদা কুয়াশা ভেদ করে উঠত, তা স্তব্ধ হয়ে যাবে, আর বেদির ওপরের রক্ত ধুয়ে যাবে।\nদীর্ঘকাল হারিয়ে থাকা আত্মাগুলো অবশেষে বিশ্রাম পাবে, শেষমেশ তাদের সত্য পথের দিকে পরিচালিত হয়ে—\nসে পথ যদি ঝলমলে নক্ষত্রপুঞ্জের দিকে হয়, কিংবা নিচের কঠিন পৃথিবীর দিকে।"
