  CollectionHall_126474_Desc = {
    Text = "মিশন শেষ হলে, আমি আমার পুরোনো সত্তার সঙ্গে বিদায় নেব।\nবিদায় সেই অতীতকে, যেখানে আমি আর কখনো ফিরতে পারব না। বিদায় তেমুরাহনকে, বিদায় সেই মানুষটিকে, যে একসময় আমি ছিলাম।\nআমি সেই কুয়াশা-ঢাকা স্থানটিকে কুয়াশার মতোই হারিয়ে যেতে দেব।\nআমি আবার শুরু করব এখানে, যেখানে কুয়াশা সরে গেছে—এই অদ্ভুত, ভীতিকর নতুন আশ্রয়ে।"
