  CollectionHall_126477_Desc = {
    Text = "জগৎকে রক্ষা করা কখনোই তার পথ ছিল না, আর এই জগৎও তার নয় যে সে বাঁচাবে।\nকিন্তু সে রক্ষকের কণ্ঠস্বর শুনেছে, আর দেখেছে এই স্থানকে রক্ষা করতে কী উৎসর্গ করা হয়েছে।\nযে জগতের জন্য কেউ নিজের জীবন দিয়ে দিয়েছে, তা ধ্বংস হওয়া উচিত নয়।\nঅন্তত এখনই নয়। আর অবশ্যই তার নিজের হাতে নয়।"
