  CollectionHall_126989_Desc = {
    Text = "<Title:পরিচিতি>\nতার প্রকৃত উৎস আজ আর জানার উপায় নেই। এই প্রাচীন 「দেবসত্তা」 সম্পর্কে প্রাচীনতম যে অস্পষ্ট নথি পাওয়া যায়, তা কয়েক হাজার বছর আগের।\nযে কেউ তার দিকে তাকালে ভিন্ন ভিন্ন রূপ দেখতে পায়। প্রকৃতপক্ষে তার এমন ক্ষমতা রয়েছে যা অলক্ষ্যে অন্যের স্মৃতিকে কলুষিত করে, নিজের প্রতিচ্ছবিকে ধীরে ধীরে অন্যের স্মৃতিতে মিশিয়ে দেয়, এবং শেষ পর্যন্ত অন্যকে তাকে জীবনের একমাত্র গুরুত্বপূর্ণ ব্যক্তি হিসেবে মেনে নিতে বাধ্য করে।\nঅন্যান্য বেশিরভাগ জাগ্রত সত্তার থেকে ভিন্ন, তার মধ্যে মানবীয় আবেগ বা দৃষ্টিভঙ্গি প্রায় নেই বললেই চলে।\nসে একটি চিন্তা, একটি উন্মত্ত কল্পনা, একটি কুয়াশার রেখা — তাকে সু বলে অনুভব করা হয়, লিউ, লি, ছিয়ান, ঝাং বলে অনুভব করা হয়। সে আনন্দ থেকে জন্ম নেয়, এবং অবিরাম বিশৃঙ্খলা থেকে উৎসারিত আনন্দেরও পিছু ধাওয়া করে।\nতবে সে সম্পূর্ণ অবোধ্য, অবর্ণনীয় অস্তিত্ব নয়। তার দ্বারা নির্বাচিত ব্যক্তিরা, যারা তাকে চরম আনন্দ এনে দেয়, তারা সেই নামটি আভাস পাওয়ার সুযোগ পায় যা তাকে সত্যিকার অর্থে সংজ্ঞায়িত করতে পারে, যা অন্যান্য উপাধির মতো পরিবর্তনশীল নয়।\n「ছিয়ানশান সুয়াননুই」(সহস্র পাখার রহস্যময়ী)।"
  },
  CollectionHall_126989_LockTip = {
