  CollectionHall_127112_Desc = {
    Text = "「স্মৃতি কী?」\n「যা তুমি ভুলে গেছ, সেটাই।」\n\nলিলির আছে এক ভুলোমনা মাতৃদর্শন।\nতিনি লিলিকে খেতে ডাকতে ভুলে যান, লিলিকে ওষুধ দিতে ভুলে যান, এমনকি লিলির নামটাও ভুলে যান।\n「আমার কী করা উচিত?」\nহাসপাতালের বিছানায় বসে লিলি গভীর চিন্তায় মগ্ন থাকার ভান করে দীর্ঘশ্বাস ফেলল।\nএমন এক মাতৃদর্শন সত্যিই দুশ্চিন্তার কারণ।\n\nপরে, লিলি কাঠের এক ফলকে নিজের নাম লিখে প্রতিদিন গলায় ঝুলিয়ে রাখল।\nএতে তো মনে থাকার কথা, তাই না?\nশুরুর দিকে, তার মাতৃদর্শন এখনো হেসে বলতেন, সে বাড়াবাড়ি করছে, এটা কেবল দীর্ঘমেয়াদি ক্লান্তির একটি জটিলতা মাত্র।\n\nক্রমে, তিনি বিভ্রান্তি আর অস্থিরতার লক্ষণ দেখাতে শুরু করলেন:\n「লিলি… লিলি আবার কী?」\nঅ্যাম্বার রঙের চোখদুটি লিলির দিকে তাকিয়ে রইল, তাতে লুকোনো সতর্কতার এক আভাস।\nপ্রকাশ পেল, যখন শব্দের অর্থ ভুলে যায়, ভাষার মাধ্যমে সাময়িকভাবে টিকে থাকা সুরও শেষ পর্যন্ত বিলীন হয়ে যায়।\n\nলিলি তার মাতৃদর্শনকে জড়িয়ে ধরল।\nমা-মেয়ের হৃদস্পন্দন ছিল মাত্র কয়েক ইঞ্চি দূরে, তবু সে নিজেকে ভীষণ একা অনুভব করল।\n\nসেদিনের পর, লিলি কাঠের ফলকটি গুছিয়ে রেখে দিল, আর মাতৃদর্শনের স্নেহে ডুবে থাকল না, আর মনে করিয়ে দিল না যে সে বহুদিন ধরে না খেয়ে আছে।\nসে ছিল জীবন-মৃত্যুর প্রান্তে দাঁড়ানো এক অসাড় রোগী, মৃত্যুর রায়ের প্রতীক্ষায় নিথর।\nসে ছিল এক দূরবর্তী দর্শক, দেখছিল নিজেকে কীভাবে ইনজেকশন দেওয়া হচ্ছে, অবশ করা হচ্ছে, আর মাতৃদর্শনের ইচ্ছেমতো যেকোনো রূপে গড়ে তোলা হচ্ছে।\nমা-মেয়ের বিনিময় হওয়া সুখের কথা, নরম আলিঙ্গনগুলো…\nস্বপ্নলোকের বুদবুদের মতো ঝলসে ওঠা সেই আনন্দময় স্মৃতিচারণ লিলি যত্ন করে নিজের হৃদয়ে লক করে রাখল।\nশুধু কিছু ক্লান্ত রাতেই সে অনিচ্ছায় সেগুলো বের করে আনত, আর আস্তে আস্তে সেগুলোর স্বাদ নিত।"
  },
  CollectionHall_127112_Title = {
    Text = "যন্ত্রণা অতিক্রমের কৃপা"
