  CollectionHall_127116_Desc = {
    Text = "“মানুষ জোয়ারের সঙ্গে জন্মায়, ভাটার সঙ্গে মরে।”\nএটি নিম্ফিয়ার জন্মভূমিতে প্রজন্ম থেকে প্রজন্মে চলে আসা এক কিংবদন্তি।\n\nসেভাডা গ্রামের শহরবাসীরা মৃত্যুকে ভয় পায় না; তাদের কাছে জীবনের অঙ্কুরোদ্গম আর ম্লান হয়ে যাওয়া জোয়ার-ভাটার ওঠানামার মতোই, প্রকৃতিরই অংশ।\nতারা ভালোবাসে নীল আকাশ, সমুদ্র, সাদা গাঙচিলের ঝাঁক, আর সকালের রোদে ফোটা কলা লিলি ফুল।\nতারা ঘৃণা করে বাষ্প, লোহার রেলপথ, আর মানুষের হস্তক্ষেপের অতিরিক্ত ছাপ লেগে থাকা সবকিছু—জীবনে সম্মুখ হস্তক্ষেপও সেই ঘৃণার মধ্যেই পড়ে।\nকারও জীবন মাঝপথে কেটে দেওয়া সেভাডিয়ানদের চোখে একেবারেই অগ্রহণযোগ্য।\n\nনিম্ফিয়া আদর্শ সেভাডিয়ান নয়।\nযেমন, সে সবসময় জাহাজডুবির পরিবেশের প্রতি অদ্ভুতভাবে আকৃষ্ট।\nএক মৃত জাহাজডুবি অসংখ্য জীবনের আশ্রয়: মাছ, জলজ উদ্ভিদ, নানান ঝিনুকজাত প্রাণী...\nএখানে জীবন আর মৃত্যু এক রহস্যময় ও পবিত্র ভঙ্গিতে জড়িয়ে থাকে।\nনিম্ফিয়া শান্তভাবে ধ্বংসস্তূপের দিকে এগিয়ে যায়, যেন প্রবেশ করছে এক অপরিসীম গাম্ভীর্যে ভরা গির্জায়।\n\nবাবা যখন তাকে নিয়ে বেড়াতে যেতেন, সেই সব বছরগুলোর একটিতে নিম্ফিয়া দেখেছিল পাঁচ অঙ্কের একটি নাটক।\nনাটকের বিষয়বস্তু অনেক আগেই তার স্মৃতি থেকে মুছে গেছে; মনে হয়েছিল যেন কোনো প্রাচীন সম্রাটের জীবনকথা।\nউত্তর-দক্ষিণে যুদ্ধের উন্মত্ততায় ভরা ছিল তার জীবন, অথচ শেষমেশ সে মারা গেল এক লজ্জাজনক ষড়যন্ত্রের ফাঁদে পড়ে।\nসে শুধু একটি পঙ্‌ক্তি মনে রেখেছে:\n<Italic:কাপুরুষেরা মৃত্যুর আগে বহুবার মরে; সাহসীরা মৃত্যুর স্বাদ পায় মাত্র একবার।>\n\nবহু বছর পরে, যখন নিম্ফিয়া ঠান্ডা সমুদ্রজলে পা বাড়ায়, জীবনের জন্য তার আকুলতা তাকে ব্যথিত করে, তখন সেই পঙ্‌ক্তিটি তার মনে ভেসে ওঠে:\n“সাহসীরা মৃত্যুর স্বাদ পায় মাত্র একবার...”\nতাই সে চোখের জল মুছে, শেষবারের মতো বাবা-মাকে বিদায় জানায়, আর এগিয়ে চলে নিজের হৃদয়ের জাহাজডুবির দিকে।\nসে নিজেই নিজের যোদ্ধা হয়ে উঠবে।"
  },
  CollectionHall_127116_Title = {
    Text = "ক্ষয়ের উপহার"
