  CollectionHall_127117_Desc = {
    Text = "A. F.@1/06/05\nঅ্যালবিনর ডি-রিফ্ট থেকে কিছু বিরল সিলভার এনে দিয়েছে। সত্যিই চমকপ্রদ।\nআমি শুদ্ধিকরণ পদ্ধতিতে কিছু উন্নতি করেছি।\nএইবার, আমি যথেষ্ট পরিমাণ কার্বন ডাই-অক্সাইড আর ক্লোরিন গ্যাস প্রবেশ করালাম, তারপর নিম্ন-তাপমাত্রায় বাষ্পীভবন আর স্ফটিকায়ন...\nএই যান্ত্রিক ধাপগুলো বিস্তারিতভাবে লিপিবদ্ধ করার মতো মূল্যবান নয়।\n\nA. F.@1/06/06\nআমি নমুনা 024-এর অভ্যন্তরীণ অঙ্গপ্রত্যঙ্গ আর অঙ্গ-লক্ষণগুলো বিচ্ছেদ করলাম।\nএই উপাদানটা অ্যালবিনর ক্লিনিক থেকে এনে দিয়েছে, আর এতে 13টি ডিজলিউশন গহ্বর তৈরি হয়েছে, যার সর্বোচ্চ ব্যাস 8 মিমি।\nOS-106 ডি-রিফ্ট দানবের পরজীবী জীবগুলো কেটে আলাদা করা।\nবিভিন্ন পরীক্ষামূলক ডেটার তুলনায় দেখা যাচ্ছে, 024-এর সঙ্গে এর অনুরণন সামঞ্জস্য সর্বোচ্চ।\nএকটাই সমস্যা... ওই শুঁড়গুলো একটু বেশিই 「চঞ্চল」।\nআমার মনে হয়, অনেক দিন আর অক্টোপাস খেতে ইচ্ছে করবে না।\nআশা করি চূড়ান্ত ফলাফল আমাকে নিরাশ করবে না।\n\n@1 বছর 6 মাস 6 দিন\nগ্রাফটিং পরীক্ষা সফল হয়েছে, কিন্তু নমুনার জীবনচিহ্ন হারিয়ে গেছে।\nএটা খুবই সাধারণ ঘটনা; কেবল নিশ্চিত করতে হবে যে গ্রাফটিং স্থানে সংক্রমণ ছড়ায়নি।\nএক সপ্তাহের পর্যবেক্ষণের জন্য পাঠিয়ে দিলাম—এর পরের অংশ আর আমার দায়িত্ব নয়।\nআজ 「ইন্টারনাল জার্নাল」-এ জীবিত অ্যাওয়েকনারদের ওপর পরীক্ষা নিয়ে সমালোচনামূলক দুইটি প্রবন্ধ পড়লাম।\nবলা বাহুল্য, স্বাক্ষর দেখলেই বোঝা যায়, ওরা আমার মিথাগ-এর পুরাতন বন্ধু।\nহাস্যকর—এই বুড়োরা যদি তাদের ভারী পাছা একটু নাড়িয়ে ল্যাবে এসে দেখত, তবে বুঝত আমার উপসংহারগুলো অটল।\n024-কে নিয়ে করা পরীক্ষা হবে এক দুর্দান্ত পাল্টা আঘাত।\n\nA. F.@1/06/22\nদুই সপ্তাহ কেটে গেছে, আর 024-এর জীবনচিহ্ন এখনো অস্থির—বরং বলা ভালো, তার ভেতরের ব্যক্তিত্ব কোষ বিভাজনের মতো দ্রুতগতিতে ভাগ হয়ে বাড়ছে।\nপরীক্ষাটা এক বিস্ময়কর ভঙ্গিতে ব্যর্থ হয়েছে।\n024-কে মোম জাদুঘরে পাঠিয়ে দাও; সে যেন আর প্রতিদিন আমার পিছু পিছু না ঘোরে, আমার বোকামি আর হঠকারিতার কথা মনে করিয়ে দিতে।"
  },
  CollectionHall_127117_Title = {
    Text = "বিকৃত দেহের প্রতিগ্রাস"
  },
  CollectionHall_127118_Desc = {
    Text = "ওটা ছিল রূপালি-সাদা, স্বচ্ছ, কলঙ্কহীন এক হৃদয়।\n\nনির্মল রৌপ্য দিয়ে গড়া, তা তার যান্ত্রিক খাঁচার ভেতর স্থির ছন্দে স্পন্দিত হতো।\n\nএকসময় তা রক্তে রঞ্জিত হয়েছিল, কাদায় লেপটে গিয়েছিল।\n\nকিন্তু মৃত্যুর ছায়া নেমে এলে, শেষ পর্যন্ত তা ফিরে পেল তার আদিম রূপ।"
  },
  CollectionHall_127118_Title = {
    Text = "বিশুদ্ধ রৌপ্যের প্রারম্ভিক হৃদয়"
  },
  CollectionHall_127119_Desc = {
    Text = "সময় বয়ে গেল, আর লোটান আর স্পষ্টভাবে স্মরণ করতে পারল না গ্রহের আবির্ভাবের স্মৃতিচারণ।\n\nসে শুধু এটুকুই মনে রাখল যে, সে ছিল নির্বাচিত এক সত্তা।\n\n\nএটি এমন এক গল্প, যা সব ধারণার জন্মেরও পূর্বে সংঘটিত।\n\n「জীবন」 তখনও শিকড় গজায়নি, আর 「দেবতারা」 তখনও আকাশের বহু দূরে অবস্থান করছিল।\n\nএই বিশৃঙ্খল নীহারিকায়, কেওস কেওসের সঙ্গে সংঘর্ষে লিপ্ত, আর আঘাত ও অস্থিরতার ভেতর দিয়ে ধীরে ধীরে রূপ নিচ্ছিল পদার্থ।\n\nনক্ষত্রপুঞ্জ ধূলিকণা জড়ো করল, শিলাখণ্ড উঠে দাঁড়াল পর্বতমালার আকারে, আর বায়ুমণ্ডল ঘনীভূত হয়ে গড়ে তুলল বিস্তৃত জলরাশি।\n\nতারপর, এই স্থানকে ঘোষণা করা হলো একটি 「গ্রহ」 হিসেবে।\n\n\nসময়ের খাঁচায় বন্দী কেওসের আত্মা আছড়ে পড়ল সদ্যোজাত মাটির বুকে।\n\nতার উন্মত্ত স্বভাবকে নিয়ন্ত্রণে অক্ষম, ধ্বংসের তাড়নায় চালিত হয়ে, সে অসংখ্য পর্বতমালা ভেঙে ফেলল, আর অসংখ্য নদী ও হ্রদ পূর্ণ করে তুলল।\n\nতারপর—দূর নক্ষত্রপুঞ্জ পেরিয়ে 「দেবতারা」 অবতীর্ণ হল অনুর্বর পৃথিবীতে।\n\n\n「দেবতারা」 নিয়ে এল সভ্যতার বীজ, আর একই সঙ্গে কেওসের আত্মাকে বন্দী করল এক 「গঠিত」 দেহের ভেতরে।\n\n「আমার সঙ্গে চুক্তি করো...」 \n\nগর্জনরত কেওসের আত্মার মুখোমুখি দাঁড়িয়ে, শুভ্রবস্ত্রধারী সেই 「দেবতা」 হুইসপার করল।\n\n「এখানে এক মহান সভ্যতার আবির্ভাব ঘটবে।」\n\n「তুমি সাক্ষাৎ পাবে জ্ঞানী কিন্তু নিষ্ক্রিয় দার্শনিকদের, আর সংঘর্ষে জড়াবে অনিশ্চিত ব্লেডের সঙ্গে... ভবিষ্যতে, তুমি আর ধ্বংস আর বিপর্যয়ের শাসনে আবদ্ধ থাকবে না।」\n\n「যতদিন না সেই দিন আসে... যতদিন না আমাদের পুনর্মিলন ঘটে, ততদিন এই স্থানকে আমার জন্য রক্ষা করে যেয়ো।」"
  },
  CollectionHall_127119_Title = {
    Text = "নক্ষত্রীয় পশু"
  },
  CollectionHall_127120_Desc = {
    Text = "ডিউক যখন তাকে নাইট হিসেবে নিয়োগ দিলেন, তখন ছেলেটি মাত্র সাতবার ঋতুচক্রের পরিবর্তন দেখেছে।\n\nডিউকের এই আচরণ ছিল খেয়ালি ঠাট্টা থেকে জন্ম নেওয়া, কিন্তু রাজদরবার শপথটিকে খুবই গুরুত্বের সঙ্গে নিল। ফেজ অভিজ্ঞ নাইটরা তাকে ঘোড়সওয়ার তীরন্দাজিতে শাণিত করল, পরিচারকেরা তাকে শিষ্টাচারের সূক্ষ্ম নিয়মে প্রশিক্ষিত করল, আর রাজকুমারী—সবাইয়ের ঊর্ধ্বে—তার এই কিশোর রক্ষকের ওপর অটল আস্থা রাখলেন।\n\nএইকুইডানের বুনো উচ্চভূমি পেরিয়ে গভীর গিরিখাতে নামার পথে, তরুণ নাইটটি লাগাম ধরে রাজকুমারীর ঘোড়াটিকে এগিয়ে নিয়ে যাচ্ছিল। রাজকুমারী শুয়ে ছিলেন ক্লান্ত দেহ নিয়ে, এক অদৃশ্য অন্ধকার ধীরে ধীরে ভেতর থেকে তার শরীরকে গ্রাস করছিল।\n\n「রাজকুমারী, আমরা আর এগোতে পারব না, 」 সে ফিসফিস করে বলল।\n\nগিরিখাত আর তার ওপারের নদী পেরিয়ে যাওয়া মানে ছিল সেই মাটি ত্যাগ করা, যে মাটি তাদের লালন করেছে। সীমানার বাইরে যুদ্ধ জ্বলছিল; শত্রুরা লোভী, শিকারির দৃষ্টিতে তাদের উর্বর ভূমির দিকে তাকিয়ে ছিল। কেবল এই বিশাল খাদই তাদের শান্তি রক্ষা করেছিল, এই ক্ষুদ্র খণ্ডাংশকে 「রাষ্ট্র」 নামের মর্যাদা ধরে রাখতে দিয়েছিল।\n\nনিরাপদ পাহাড়চূড়া থেকে তারা দেখেছে ওপারের মানুষের পতন। নির্দোষদের আর্তনাদ নদীর জলে ডুবে গেছে, বিজয়ীদের কবিতার কাব্যিক ছন্দ ছাড়া আর কোনো নিয়তি তাদের জন্য লেখা ছিল না।\n\nকিন্তু যতই মহৎ হোক কোনো রাষ্ট্র, ইতিহাসের স্রোত থেকে কেউ সত্যিই পালাতে পারে না।\n\nঅবশেষে শত্রুরা এলো। তারা ছেলেটির কোমল হাত কেটে ফেলল, যেন সে আর কখনো বর্শা বা চরিত্রের ঢাল তুলতে না পারে। তারা তার ভঙ্গুর হাঁটু গুঁড়িয়ে দিল, তাকে বাধ্য করল অসহায় যন্ত্রণায় দেখতে, কীভাবে অশ্বারোহী বাহিনী প্রাসাদের দরজা ভেঙে ঢুকে পড়ছে। তবু নাইটটি লড়াই চালিয়ে গেল—শত্রুর যুদ্ধঘোড়ার পায়ে দাঁত বসিয়ে, তাদের নৃশংসতা থামানোর এক মরিয়া, অথচ নিষ্ফল চেষ্টা।\n\nতারপর, প্রথমবারের মতো, সে দেখল সেই 「কালো প্লেগ」—যার কথা রাজকুমারী তাকে সতর্ক করে দিয়েছিলেন।\n\nপ্রাসাদের দরজা ভেঙে বেরিয়ে এলো কালো তরলের বন্যা। তা অশ্বারোহীদের পায়ের বর্ম ভিজিয়ে দিল, তবু আক্রমণকারীরা দুর্বলতা দেখাল না। 「কালো প্লেগ」 ক্রমে উঠে এসে নাইটের মুখ আর নাক ভরিয়ে দিল, তার ফুসফুস শ্বাসরোধে ভরে উঠল, তবু সে আত্মসমর্পণের তাগিদকে প্রতিরোধ করল।\n\nতারপর, এক পরিচিত কণ্ঠস্বর—নরম, আপন—তার মনের প্রাঙ্গণে প্রতিধ্বনিত হলো। 「তুমি যথেষ্ট করেছ... আমার সবচেয়ে বিশ্বস্ত নাইট।」\n\nশেষে, যা রইল, তা কেবল এক বিশাল, নীরব শূন্যতা।"
  },
  CollectionHall_127120_Title = {
    Text = "এক নাইটের শপথ"
  },
  CollectionHall_127121_Desc = {
    Text = "তারা জন্ম নিয়েছে অজানা জীব সম্পর্কে মানবতার দীপ্তি-র কল্পনা থেকে, তবু তাদের মধ্যে নেই সেই হিস্টিরিয়া আর নখরাঘাতের উন্মত্ততা, যা মানুষ প্রায়ই কল্পনা করে।\n\nতারা যুক্তিবাদী; তারা শান্ত।\n\nতারা এসেছে ভবিষ্যতের জন্য, তারা এসেছে অস্তিত্বের জন্য।\n\nতারা সবচেয়ে অস্বাভাবিক, সবচেয়ে অবিশ্বাস্য অলৌকিক ঘটনা।\n\nপ্রথমে, তাদের কণ্ঠস্বর ছিল পোকামাকড়ের ডানার ঝিঁঝিঁ শব্দের মতো। কিন্তু তাদের চিন্তাকে সম্পূর্ণভাবে অনুধাবন করার পর, সেই কণ্ঠস্বর নীরব হয়ে গেল।\n\nতবু তার পর, সেই কণ্ঠের প্রভুরা চেষ্টা করল তার নেওয়া প্রতিটি সিদ্ধান্তে প্রভাব ফেলতে।\n\nতার প্রথম বছরে, একজন <Awakener> হিসেবে, সে শিখল মাথার ভেতরের কণ্ঠগুলোর সঙ্গে সহাবস্থান করতে।\n\nসে চেতনার গভীরে ডুব দিল, সমষ্টিগত সত্তার অংশ হয়ে, প্রয়োজনীয় তথ্য ও জ্ঞান ছিনিয়ে নিল, আর শেষে নিরাপদে বিচ্ছিন্ন হয়ে বাস্তবে ফিরে এল।\n\n“ব্ল্যাক প্লেগ” যখন এই দেহের জন্য এসে দাঁড়াল, তখনও সে একই কাজ করল।\n\nসে চেয়েছিল দেহকে জ্ঞান, স্মৃতি ও আত্মা থেকে আলাদা করতে, মস্তিষ্ককে এক অমর সত্তায় পরিণত করতে।\n\nঅস্ত্রোপচারের পর, সে প্রায় এক জীবন্ত ও বিস্ময়কর নিদ্রায় তলিয়ে যাচ্ছিল—কিন্তু কয়েক সেকেন্ডের মধ্যেই তার চিন্তা আবার সচল হয়ে উঠল।\n\nসে স্পষ্ট জানত, সে এগিয়ে যাচ্ছে সেই পরম ধ্বংসের দিকে, যা রূপ, শক্তি, আর সমমিতির বিশৃঙ্খলাকেও অতিক্রম করে।"
  },
  CollectionHall_127121_Title = {
    Text = "মৃত্যুহীন আরোহণ"
