  CollectionHall_127122_Desc = {
    Text = "মানুষ সবসময় নিজের মানদণ্ড মেনে সীমানা আর প্রতীক আঁকতে ভালোবাসে।\nকত সংকীর্ণ, অজ্ঞ, আর করুণ সেই চেষ্টা—মানবদেহের ভেতরেই সমগ্র বিশ্বকে আটকে রাখতে চাওয়া।\nসে বহু আগেই দেহ ত্যাগ করেছে, তবু সত্যিকারের সীমানায় পৌঁছতে পারেনি।\nজ্ঞান-নদী কেওসে ভরা, অন্তহীন; আর কালো শূন্যতা আবারও তাকে ধরে ফেলেছে।\nনিঃশব্দে, সে তার মুখোমুখি হলো। যদি দৃশ্যমান সবকিছুই বিশ্বের পূর্ণতা প্রকাশে ব্যর্থ হয়, তবে তার অন্তরালে থাকা শূন্যতায় কি তবে সত্যিকারের উত্তর লুকিয়ে আছে?\nসে নিজের জীবনকে বাজি রাখল, সবচেয়ে উন্মত্ত জুয়াখেলায়।\nঅবশেষে সে শেষ প্রান্তটি দেখল।\nসত্যের দ্বার হাট করে খুলে গেল, আর এক মুহূর্তে উলটে গেল বিশ্বের মুখচ্ছবি।\nএমনই তো, এমনই তো।\nসে প্রাণপণে চাইল, সকলে যেন শূন্যতার ভেতরের সত্যটি দেখে, নিষ্ফল ছটফটানি থেকে মুক্তি পায়।\nএকদিন, সে তরঙ্গের চূড়ায় দাঁড়িয়ে, বিশ্বকে সামনে এগিয়ে নিয়ে গিয়েছিল।\nএখনও, সে রাখালের চাবুক হাতে, উল্লাসে তাকে অতলে নামিয়ে নিয়ে যায়।\nভীত মানুষ তাকে তাড়িয়ে দিল, পাগলি বলে অভিহিত করে।\nকী অদ্ভুত, ভাবল সে।\nকিন্তু আমার চোখে, তোমরা কোনো অংশে আলাদা নও।\n"
