  CollectionHall_127126_Desc = {
    Text = "ঝড়ো হাওয়া আর বৃষ্টিধৌত রাতের মধ্যে, দেবতার কন্যা একা বসে ছিল গোল জানালার নিচে।\n\nবরফশীতল চাঁদের আলো পড়ছিল কাপড়ে মোড়া দেহের ওপর, যেখানে দিব্য ভ্রূণ, কালো আঠালো তরলে ভিজে, শান্তিতে ঘুমিয়ে ছিল।\n\nসে ঘুমপাড়ানি গান গাইতে শুরু করল।\n\n<Italic:\"চুপ এখন, চুপ, আমার সাগর-জন্মা সোনা।\">\n\n<Italic:\"কালো চাঁদ ধরে রেখেছে তোমার দোলনা।\">\n\n<Italic:\"গিলে নাও তারাগুলো, তোমার স্বপ্নের জলে সোনা।\">\n\nএই গানটিই ছিল এক প্রার্থনা, আর তার ডাকে গভীর সমুদ্রের মাছেরা জড়ো হতে লাগল।\n\nসমগ্র জাহাজটি পরিণত হল এক বিশাল বেদিতে, ঠিক যেমন সেদিন, যেদিন সে জন্ম দিয়েছিল দিব্য ভ্রূণকে।\n\nসে নিজের বুক চিরে খুলে ফেলল, টেনে বের করল ভেজা মাংস আর হাড়; নিজের লালন-পালনের ঋণ আর জাতির নিয়তির প্রতি কৃতজ্ঞতা শোধ করল নিজের প্রাণ দিয়ে।\n\nতার উৎসর্গ তাকে এনে দিল না সেই মুক্তি, যার জন্য সে আকুল ছিল; মৃত্যু কোনো চিরনিদ্রা নয়, বরং কেবলমাত্র এক ট্র্যাজেডির সূচনা।\n\nতার পর থেকে, তার একমাত্র শান্তি নেমে আসে শুধু রাতেই।\n\n<Italic:\"চুপ এখন, চুপ, আমার সাগর-জন্মা সোনা...\">\n\nযখন এই ঘুমপাড়ানি গান শেষ হবে, মহান চিরন্তন রাজ্য তরঙ্গ ভেদ করে উঠবে, আর উত্তাল মহাসাগর থেকে মাথা তুলবে।\n\nএই ব্যর্থ মায়াস্বপ্নকে বুকে জড়িয়ে, মার্ফি ধীরে ধীরে চোখ বুজল।"
  },
  CollectionHall_127126_Title = {
    Text = "অন্ধকারে নিদ্রা"
