  CollectionHall_127127_Desc = {
    Text = "সে সবসময় নিজেকে চরমে ঠেলে দিয়েছে, কঠোরতার কারণে সব সঙ্গীকে দূরে সরিয়ে, ভেবেছিল সঙ্গীতের পরম পূর্ণতার অনুসন্ধানে এই পথ সে চিরকাল একাই হেঁটে যাবে।\nশিখর শীতল, আর সে সেই নিয়তিকে মেনে নিয়েছিল।\nযতক্ষণ না সে সেই মানুষের পরিবেশনা শোনে।\nতার সঙ্গে পূর্ণতার কোনো সম্পর্কই নেই। সুর ছিল অতিমাত্রায় উচ্ছৃঙ্খল, ঠিক তার মতই—কখনও সুরলিপি থেকে সরে যায়, হঠাৎ কিছু অংশ ভুলেও যায়। তারপর তার হাত নিজে থেকেই বুনে ফেলে চতুর, চঞ্চল সুর, আর চারদিক থেকে ওঠে বিস্ময় আর প্রশংসা।\nসে তাকিয়ে থাকে তার দিকে, যেন স্বরলিপির ফাঁকে ফাঁকে খেলা করা কোনো সুর-পরীকে দেখছে।\nএটাই বোধহয় তার পিতার ভাষায় প্রকৃত প্রতিভা। সে গভীরভাবে আকৃষ্ট হয়, অন্য সকলে যেমন, তবু নিজের পদক্ষেপ বদলাতে পারে না।\nসে ছিল অতিরিক্ত সাধারণ আর বোকা, কেবল এই কষ্টে পাতা সলতের পথটুকুই হেঁটে যেতে সক্ষম।\nসকলে সেই মানুষের পিছু নিল, আর সে ক্রমে ক্রমে দূরে সরে গেল।\nসে তার কাছে যেতে চাইল, কিন্তু বাজানো ছাড়া আর কিছুই জানত না।\nকীভাবে তার সঙ্গে কথা বলবে? কেমন সুরলিপি তার দৃষ্টি কেড়ে নিতে পারে?\nসে সুরলিপি লিখতে লাগল, যেন প্রারম্ভিক কথার খসড়া সাজাচ্ছে। যতক্ষণ না আর কথা বলার কোনো সুযোগই অবশিষ্ট রইল না।\nগভীর অনুতাপ তাকে গ্রাস করল, অন্য সবকিছুকে অর্থহীন করে দিল।\nশুধু সেই অপূর্ণ চিঠিটাই রইল, প্রয়াত আত্মার উদ্দেশে লেখা।\nসে নিজেকে সম্পূর্ণ ক্ষয় করে ফেলল, শেষমেশ সুরলিপির সামনে লুটিয়ে পড়ল, পথের শেষ প্রান্তে পৌঁছনোর আগেই স্বপ্নলোকের ভেতর তলিয়ে গেল।\nযদি আমি কোনোদিনই শেষ প্রান্তে পৌঁছতে না পারি, তবে আমার সারাজীবনের এই একগুঁয়ে লড়াই কিসের জন্য?\nআলো থেকে ভেসে আসা দূরবর্তী বাঁশির সুর তার জিজ্ঞাসু আত্মাকে শান্ত করল।\nঅচেতন ঘোরে সে বাঁশি তুলে নিল, বুঝল নিজের সত্যিকারের দায়িত্ব।\nতার অবিরাম সুরধারায়, আনতে হবে চিরস্থায়ী শান্তি।\n"
  },
