  CollectionHall_127136_Desc = {
    Text = "মা। মাতৃদর্শন।\nমার্ফি তার সঙ্গে জড়িত অধিকাংশ স্মৃতিচারণ হারিয়ে ফেলেছে।\nশোনা যায়, মৃত্যুযন্ত্রণায় কাতর তার মাতৃদর্শন রক্তে ভরা গলায় শ্বাসরোধ হতে হতে তাকে রক্ষা করেছিলেন।\nতারপর লোকজন ছুটে এসে, নিষ্ঠুরভাবে দু’জনকে আলাদা করে দেয়।\nসেই মুহূর্তে, মার্ফি তার মাতৃদর্শনের মুখ দেখেছিল। সেই মুখ ছিল উন্মত্ত, অথচ ভীষণ সুন্দর।\nপরে যখন সে আবার মনে করতে শুরু করল, তখন তার একটি নতুন “মাতৃদর্শন” হল।\nনরম ও সতর্ক, তিনি মার্ফির সব অযৌক্তিক দাবিই পূরণ করতেন, আবার এমন এক দূরত্ব বজায় রাখতেন যা না খুব দূর, না খুব কাছে।\nঠিক যখন মার্ফি ভেবেছিল, তাদের সম্পর্ক এভাবেই চিরকাল চলবে—মিরিয়ামের অপরিবর্তিত অভিব্যক্তির মতো—তখনই তাকে অন্ধকার সিংহাসনের অনেক ওপরে তুলে ধরা হল, আর সে স্বপ্নে দেখল জ্বলজ্বলে “ডিম”।\nঅন্ধকার রাতে তা ঝিকমিক করছিল, যেন কোনো চোখ, কিংবা কোনো তারা। পবিত্রস্থান ঘিরে ভেসে বেড়াচ্ছিল অতীন্দ্রিয় গানের সুর:\n<Italic:তার কন্যার @1 থেকে, ঈশ্বর অবতীর্ণ হন @1...>\nতাকে অর্পণ করা হল এক মহান দায়িত্ব, যা তার সঙ্গে জড়িতও, আবার নয়ও: সেই মাতৃদর্শন হয়ে ওঠা, যে ঈশ্বরকে পুনর্জীবন দেবে।\nকী অদ্ভুত। সে এখনো বোঝে না মাতৃদর্শন কী, কন্যা কী, অথচ তাকে “মাতৃদর্শন” হওয়ার পাঠ শুরু করতে হবে।\nমার্ফি স্মরণ করল সেই উন্মত্ত, সুন্দর মুখটিকে, আর জিভে লেগে থাকা মিষ্টি অথচ তিক্ত স্বাদটিকে।\nওই সুন্দর মানুষটি নিশ্চয়ই চায় না আমি এভাবে কবরের অন্ধকারে গড়িয়ে পড়ি, তাই তো?"
