  CollectionHall_127142_Desc = {
    Text = "যখন সে গ্রীনহাউসে চোখ মেলল, আগুন ইতিমধ্যেই পুরো বাগানটাকে গ্রাস করে নিয়েছে, ঠিক তার সামনে এসে দাঁড়িয়েছে।\nগ্রীনহাউসের দরজাটা বাইরে থেকে লক করা, আর বাতাস ভরে আছে তীব্র অ্যালকোহল আর চর্বির গন্ধে। সে গলা ফাটিয়ে কোলেটের নাম ধরে ডাকতে লাগল, ধোঁয়ায় গলা ভেঙে কর্কশ হয়ে গেল, আর তার জবাবে কেবল গর্জে উঠল দাউদাউ আগুন।\nসে একরকম স্বস্তি অনুভব করল। ভাগ্যিস, কোলেট বাইরে গেছে; নইলে এত বড় আগুনে সেও বিপদে পড়ত।\nসে দুঃখ অনুভব করল। জীবনের শেষ মুহূর্তে, সে তার সেরা বন্ধুটিকে আর একবারও দেখতে পারল না। কোলেট যখন ফিরে এসে পুড়ে যাওয়া বাগান আর তাকে দেখবে, নিশ্চয়ই খুব কষ্ট পাবে, তাই না?\nসে অনুশোচনা অনুভব করল। তাদের জীবন তো মাত্রই একটু একটু করে ভালো হতে শুরু করেছিল, আর এই আগুন সবকিছুর ইতি টেনে দেবে।\nজ্বলছে। বাড়ি জ্বলছে। আকাশ জ্বলছে। পাতারা জ্বলছে। পাপড়িগুলো জ্বলছে। বাগানে কাটানো সব দৃশ্য যেন আবারও তার সামনে ভেসে উঠল, গলে গলে বয়ে গেল: সে তাকে বাগানে এনেছিল, সে তার হাতে তুলে দিয়েছিল এক গোলাপ, দিনের পরিশ্রম শেষে সে তার জন্য এনেছিল নরম রুটি। তারা দৌড়ঝাঁপ করেছে, লুকোচুরি খেলেছে, শান্ত রোদে পাশাপাশি শুয়ে থেকেছে, স্বপ্ন দেখেছে একদিন কাউন্টেসের ঘরে উঠে যাওয়ার।\nজ্বলছে। অতীত জ্বলছে। ভবিষ্যৎ জ্বলছে। বাগান, তার সব গল্প আর অনুভূতি নিয়ে, উন্মত্ত আগুনে পুড়ে ছাই হয়ে যাচ্ছে।\nতার গাল বেয়ে নেমে এল অশ্রু, তপ্ত শিখার তাপে মুহূর্তেই মিলিয়ে গেল।\nসে সৌন্দর্য অনুভব করল। কবিতায়, যন্ত্রণা আর অনুশোচনা সুন্দর। সে চারদিকে খুঁজে পেল আগুনে প্রায় সম্পূর্ণ পুড়ে যাওয়া কাগজ আর কলম।\nকৃতজ্ঞতা, স্নেহ, না-পারা, আশীর্বাদ, সৌন্দর্য। সে চেয়েছিল এই সবচেয়ে সুন্দর সবকিছুই কোলেটের জন্য রেখে যেতে।\n\"...কোলেটের উদ্দেশে। আগুনের ভেতর থেকে, হর্লা।\"\nকবিতার শেষে সে রেখে গেল তার চূড়ান্ত স্বাক্ষর।\nশত মিটার দূরে, বাগানের বিপরীত দিকের রাস্তায়, কোলেট যেন কিছু টের পেল। সে মুখ তুলে তাকাল, দাউদাউ আগুনের প্রতিফলন পড়ল তার মুখে।\nতার গাল বেয়ে নেমে এল অশ্রু, তপ্ত শিখার তাপে মুহূর্তেই মিলিয়ে গেল।"
  },
  CollectionHall_127142_Title = {
    Text = "কবিতাপত্রের শেষ পঙ্‌ক্তি"
