  CollectionHall_127145_Desc = {
    Text = "এক বিশাল স্টেজের উপর, এক কিশোরী নাচছে。\nতার চুল শক্ত করে খোঁপায় পেঁচানো, সাদা পালক আর সূক্ষ্ম মুকুটে সজ্জিত। তার নির্মল সাদা পোশাক নড়াচড়ার সঙ্গে সঙ্গে ফুলে ওঠে, বেহালার শোকাতুর সুরে ঘূর্ণায়মান হয়ে ঘুরে চলে。\nহাত দুটো প্রসারিত, পায়ের আঙুল টানটান, সাদা রাজহাঁসটি গলা নত করে, তার শোক আর বেদনা রাজপুত্রের সঙ্গে ভাগ করে নিচ্ছে。\nকিশোরী লিজ সামান্য খোলা মুখে তাকিয়ে থাকে, স্টেজের সেই সুশ্রী অবয়বে মুগ্ধ হয়ে। সেই নর্তকী তারই কাজিন, যে লিজের জন্মের আগেই তাদের সঙ্গে থাকতে এসেছিল এবং দাদীর কঠোর তত্ত্বাবধানে প্রশিক্ষণ নিয়েছে। সাধারণত সাদামাটা আর নীরব, তার কাজিনকে কখনো এত প্রাণবন্ত দেখায়নি, যেন উড়ে যাওয়ার জন্য প্রস্তুত এক রাজহাঁস। থিয়েটারের সকলে’র মতো সেও কাজিনের ছায়া-নৃত্যে মোহগ্রস্ত হয়ে পড়ে。\nলিজের হৃদস্পন্দন ক্রমেই দ্রুততর হয়—কী ঈর্ষণীয়! সেও সেই রাজহাঁস হতে চায়, চিরন্তন স্টেজে নিজের ছাপ রেখে যেতে চায়। সে জানে, সে পারবে। দাদী কি একবারও বলেননি, যখন ভেবেছিলেন লিজ শুনছে না, যে তার লম্বা, সোজা পা কত সুন্দর? তার কাজিন, প্রাক্তন প্রাইমা ব্যালেরিনা, কি বলেননি যে তার অসাধারণ সম্ভাবনা আছে? হ্যাঁ, একবার শুরু করলেই, একবার পয়েন্ট জুতো পায়ে দিলেই, দূর শহর থেকে মানুষ আসবে তাকে দেখতে। সে হবে এই শতাব্দীর শ্রেষ্ঠ নর্তকী, ব্যালের জগতে এক দীপ্তিমান নক্ষত্র!\nতখন সে জানত না, তার জন্য প্রতীক্ষা করে আছে শুধু দগ্ধকারী অগ্নিশিখা।"
  },
