  CollectionHall_127147_Desc = {
    Text = "টেইম নদীর স্রোত ধরে নিচের দিকে এগিয়ে যান, বেকম্যান স্ট্রিটের মোড়ে ডানদিকে ঘুরুন, আর প্রায় একশো ফুট হাঁটলেই, এক অগোচর কোণের ভেতর খুঁজে পাবেন 「রাইকার গোয়েন্দা এজেন্সি」।\n\nলন্ডিনিয়ামের সবচেয়ে সফল গোয়েন্দা সংস্থা হওয়া সত্ত্বেও, এখানে নেই পেশাদার গ্রন্থぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎぎ"
