  CollectionHall_127151_Desc = {
    Text = "মেয়েটি চোখ মেলে দেখে, সে অন্ধকারে ঘেরা।\n“এই!” সে চিৎকার করে ওঠে, “কেউ আছো?”\nতার কণ্ঠের প্রতিধ্বনি দুলে উঠে মিলিয়ে যায় সীমাহীন শূন্যতায়। সে গভীর শ্বাস নিয়ে আবার চিৎকার করে, “দিদি, ব্রাউন, ওয়েস্টি!”\n“কেউ আছো—”\nআগের চেয়ে আরও জোরালো সেই জিজ্ঞাসা ভেসে যায় দূরে, তারপর ধীরে ধীরে ফিরে আসে। দূর থেকে প্রতিধ্বনির ডাকে যেন কয়েকটি নীলচে আলোর সুতোর মতো রেখা এগিয়ে আসে, অসংখ্য ভাসমান, ধুলোর মতো কণায় গঠিত, সাপের মতো বাতাসে কুণ্ডলী পাকায়, ঢেউয়ের মতো ওঠানামা করে। অবিরাম আলোর স্রোত স্থির দাঁড়িয়ে থাকা মেয়েটির পাশ দিয়ে বয়ে যায়, দ্রুতই সমগ্র প্রান্তরটাকে নক্ষত্রসমুদ্র করে তোলে; ক্ষুদ্র কণাগুলো তার আঙুল আর চুলের ফাঁক দিয়ে সশব্দে বয়ে যায়, কোনো চিহ্ন না রেখে।\n“এটা… কী?”\nজ্বলজ্বলে ধুলো তার চারপাশে সামান্য ঢেউ তোলে, কোনো উত্তর দেয় না।\n“আমি মোম জাদুঘরটা মনে আছে, দিদিকে মনে আছে, আমি… বোধহয় মরে গেছি। এটা কি স্বর্গ?” সে চারদিকে তাকায়, “এখানে একটা ফেরেশতাও নেই কেন? তবে কি এটা নরক!”\nতার কণ্ঠ তার কানের পাশে গিয়ে ঝরে পড়ে, আর এবার, প্রতিধ্বনিও আর ফিরে আসে না।\nঅব্যাখ্যেয় এক নিঃসঙ্গতা তার হৃদয়ের গভীর থেকে উঠে আসে, আর এক ঝিমধরা ঘোরে সে অনুভব করে যেন সে ফিরে গেছে সেই সময়ে, যখন তার দিদি আর ব্রাউনের সঙ্গে দেখা হয়নি। অন্ধকার নর্দমা থেকে ভেসে আসা পচা দুর্গন্ধ চারদিকে ছড়িয়ে পড়ে, সে ঠান্ডায় কাঁপছে, ক্ষুধায় কাতর, তবু বেরোতে পারছে না, কারণ কেউ তাকে ধাক্কা মেরে ফেলে দিয়েছিল, আর নর্দমার মুখের ওপর একটা বড় পিপে চেপে বসানো ছিল।\nসে নিজের গালে চড় মেরে সামনে পা বাড়ায়।\nতার সামনে ধুলো সরে যায়, আবার পেছনে গিয়ে জমা হয়। পা তোলো, নামাও, পা তোলো, নামাও। সে হাঁটতেই থাকে, হাঁটতেই থাকে, কতক্ষণ ধরে হাঁটছে, কত দূর এসেছে, সে আর জানে না। সামনে কেবল আরও ধুলো আর অন্ধকার, আর পেছনে—যেদিক থেকে এসেছে, কিংবা যে পথ সে হেঁটে এসেছে—সবই চিহ্নহীন হয়ে গেছে, যতক্ষণ না—\n“জাগরণ সফল, জেনকিন, জেনকিন, তুমি কি আমাকে শুনতে পাচ্ছো?”"
  },
  CollectionHall_127151_Title = {
    Text = "পরিত্যক্ত পথ"
  },
  CollectionHall_127152_Desc = {
    Text = "সমস্ত সূচনার পিতা এসেছিলেন তারকামণ্ডলের পারে অবস্থিত অতল গহ্বর থেকে।\n\nতাঁর পদতলে জ্বলছিল অগ্নিশিখা, আর তিনি উচ্চারণ করলেন, “আগুন নিভে যাক।”\n\nগলিত পৃথিবী স্তব্ধ হয়ে গেল, আর তার মুখপটে পিতৃদেব উৎকীর্ণ করলেন প্রথম বিধান:\n“ভূমি হোক অস্তিত্বের ভিত্তিশিলা।”\nতখন উপত্যকাগুলো চিরে গেল, আর সমতলভূমি উন্মোচিত হলো বিস্তৃত আকারে।\nআর বাক্য পাথরে গঠিত হলো, প্রথম ফলক ঘোষিত হলো।\n\nতারপর সর্বপিতা তাঁর দৃষ্টি ফেরালেন ভারবাহী মেঘের দিকে, আর তিনি ঘোষণা করলেন: “মেঘগুলো বিলাপ করে ঝরুক।”\nজল একত্রিত হলো, আর তার উপর তিনি খোদাই করলেন দ্বিতীয় বিধান:\n“জল হোক সত্তার দোলনা।”\nআর জল জন্ম দিল হ্রদকে, হ্রদ ফুলে-ফেঁপে সমুদ্রে পরিণত হলো, আর সমুদ্র গ্রাস করল পৃথিবীর প্রান্তরেখা।\nআর বাক্য পাথরে গঠিত হলো, দ্বিতীয় ফলক অভিষিক্ত হলো।\n\nতারপর সর্বপিতা দেখলেন জলকে—কালো, নীরব—আর তিনি উচ্চারণ করলেন: “আলো হোক।”\nআলো বিস্ফোরিত হয়ে উঠল, আর তার উপর তিনি খোদাই করলেন তৃতীয় বিধান:\n“আলো হোক ধারক।”\nআর উষ্ণতা চুরি করে নিল অতল গভীরতার বুকে।\nআর বাক্য পাথরে গঠিত হলো, তৃতীয় ফলক পবিত্র হলো।\n\nতারপর সর্বপিতা দেখলেন মাটি, জল আর আলো গঠিত হয়েছে, আর তিনি ঘোষণা করলেন:\n“জীবন জাগরণ করুক।”\nতিনি তাঁর রক্ত ঝরালেন, আর তার উপর তিনি খোদাই করলেন চতুর্থ বিধান:\n“রক্ত ত্বরান্বিত করুক জীবনকে।”\nআর তাঁর রক্ত বৃষ্টি হয়ে ঝরল জলের উপর, আর গভীরতা ভরে উঠল জীবনে।\nআর বাক্য পাথরে গঠিত হলো, চতুর্থ ফলক মহিমান্বিত হলো।\n\nতারপর সর্বপিতা দেখলেন জীবন শেকড় গেড়েছে, আর তিনি বললেন:\n“জীবন হোক অন্তহীন রূপান্তরে।”\nক্ষুদ্র সত্তারা হামাগুড়ি দিল সেই ভূমিতে, যেখান থেকে জল সরে গিয়েছিল, আর তাদের উপর তিনি খোদাই করলেন পঞ্চম বিধান:\n“পরিবর্তন কখনো তন্দ্রায় যাবে না।”\nআর তারা বেড়ে উঠল শেকড়ে, অঙ্গে, বহুবিধ রূপে।\nআর বাক্য পাথরে গঠিত হলো, পঞ্চম ফলক সিলমোহর হলো।\n\nতারপর সর্বপিতা দেখলেন জীবন আর পরিবর্তন প্রাচুর্যে ভরা, আর তিনি বিধান দিলেন: “মৃত্যুও নেমে আসুক।” আর মৃত্যু উদ্ভূত হলো।\nধূসরকেশী, জীর্ণ আর দুর্বলরা মিলিয়ে গেল, আর তাদের উপর তিনি খোদাই করলেন ষষ্ঠ বিধান:\n“মৃতেরা প্রত্যাবর্তন করবে জেনেসিসে।”\nআর তাদের মাংস গলে গেল, টেনে নেওয়া হলো সর্বপিতার অদৃশ্য ভাঁজে।\nআর বাক্য পাথরে গঠিত হলো, ষষ্ঠ ফলক উৎকীর্ণ হলো।\n\nতারপর সর্বপিতা দেখলেন জীবন, মৃত্যু আর পরিবর্তন জড়ানো, আর তিনি বললেন:\n“এগুলোই আমার কর্ম, আর আমি একটি বর দান করব।”\nতিনি নিজের অস্থি থেকে নিলেন, আর তার উপর তিনি খোদাই করলেন সপ্তম বিধান:\n“সব কিছুর শেষে, আমার অস্থি ধারণ করবে আমার আধিপত্য। মাংস হোক মূল্য, আর জীবন পুনঃপ্রজ্বলিত হোক।”\nআর বাক্য পাথরে গঠিত হলো, সপ্তম ফলক পবিত্রীকৃত হলো।\n\nআর সর্বপিতা তাকালেন তাঁর গড়া সব কিছুর দিকে, আর তিনি বিশ্রাম ও পুনরুদ্ধার নিলেন।\nজল তাঁকে জড়িয়ে ধরল, আলো তাঁকে সান্ত্বনা দিল, মাটি তাঁকে আড়াল করল।\n\nআর সর্বপিতা তন্দ্রায় গেলেন। সব কিছু তাঁর বাক্যে সহনশীলতা পায়।\nএভাবেই তা স্থির আছে, এই যুগ পর্যন্তও।"
  },
  CollectionHall_127152_Title = {
    Text = "দিব্যবাণীর ফলক"
  },
  CollectionHall_127153_Desc = {
    Text = "তিনি সেই রাজা, যিনি সব জানেন, লেমুরিয়ার সর্বোচ্চ শাসক।\nল্যাপিস লাজুলি তার সিংহাসন, সোনা তার মুকুট। আত্মারা তার রাজদণ্ড, আর তিনি বিশ্রাম নেন শিখরে।\nযে পুরোহিতেরা দেবতাদের সেবা করে, তারাও তার সেবক, তার সামনে নতজানু হয়ে থাকে,\nনিষ্ঠাবান প্রজা আর ভক্ত বিশ্বাসী হিসেবে।\n\nরাতে, দেবতারা চাঁদের আলো পাঠান, তাকে আহ্বান করেন শাশ্বত প্রাসাদে,\nযেখানে তারা আত্মার খাদ্য ভাগ করে নেন, তাকে দান করেন দেবত্বময় জ্ঞান।\nঅন্তহীন স্বপ্ন তাকে দেখায় সব কিছুর সূচনা আর সময়ের অবসান।\nতিনি জেনেছেন: সব সূচনার উৎস বিশৃঙ্খলা; দেবতারা জেগে উঠে অন্ধকারে ভাসমান প্রাসাদ নির্মাণ করেছিলেন।\nতিনি জেনেছেন: সময়ের অন্ত হলো অন্ধকার, আর সবকিছু ফিরে যায় বিশৃঙ্খলায়।\n\nরাজাদের রাজা, দেবতাদের প্রিয়তম,\nকে তোমার সমকক্ষ?\nকে স্বপ্নে তোমার মতো আদেশ জারি করে, তোমার মহিমা ধারণ করে?\nমহান দেব-রাজা, তরুণ সার্বভৌম,\nগভীর ঘুমে তন্দ্রাচ্ছন্ন হও।\nতোমার প্রজা আর অনুসারীরা ধৈর্য ধরে অপেক্ষা করবে তোমার প্রত্যাবর্তনের, যখন তুমি দেবতাদের ভবিষ্যদ্বাণী ফিরিয়ে আনবে।\nসমুদ্রকন্যাদের শ্রদ্ধেয় শাসক, অতল গহ্বরের অধিপতি,\nআমরা তোমার নাম উচ্চারণ করি, আমাদের রক্ষা দাও,\nতুলু, তুলু।"
  },
  CollectionHall_127153_Title = {
    Text = "দেবরাজের স্তোত্র"
  },
  CollectionHall_127154_Desc = {
    Text = "বহু বছর ধরে, আমি উভহাশকে নিয়ে ভেবেছি.\nকিন্তু এই মন্দিরগুলোর ধ্বংসাবশেষের মাঝে এসে তবেই আমি তাকে সত্যিকারে প্রথম দেখলাম.\nআমি দেখলাম, সে ভারী শৃঙ্খলে বাঁধা, মাটিতে শুয়ে থাকতে বাধ্য, গলা বাড়িয়ে মরিয়া হয়ে পৌঁছাতে চাইছে ইতিমধ্যেই পচে যাওয়া খাদ্যের দিকে.\nএকটি কুকুরের মতো.\n\nক্যালিগুলার মৃত্যুর পর, টাইর‍্যান্টের সহষড়যন্ত্রী হিসেবে, সে তখন থেকেই মন্দিরের ধ্বংসাবশেষে লক করা আছে.\nআমি হাতে ধরা শৃঙ্খল টেনে আনলাম, সামনে নিয়ে এলাম টরেসের এক দাসকে.\nউভহাশ সঙ্গে সঙ্গে সোজা হয়ে দাঁড়াল, তার চোখের মণি প্রসারিত হলো, গলায় দ্রুত গিলতে থাকা শব্দ উঠল.\n\n「থামো।」\nআমি শৃঙ্খল টেনে দাসটিকে এমন দূরত্বে রাখলাম, যেখানে থেকে সে আর তাকে ছুঁতে পারে না.\n「আমাকে একজনকে খুন করতে সাহায্য করো।」\nসে দাঁত বের করে হাসল, প্রকাশ পেল ধারালো পশু-দাঁতের সারি.\n「তুমি 19তম মানুষ যে আমাকে এই কথা বললে, আর আমাকে তোমাকে না বলতে হচ্ছে।」\nআমি প্রাণপণে মুখের ভাব সামলে রাখলাম, যাতে সে আমার হতাশা টের না পায়:\n「কেন?」\n「যদি তুমি চাও আমি এক হাজার মানুষ মারি, আমি আনন্দের সঙ্গেই রাজি। একজন? তোমার দরকষাকষির পণ একেবারেই অপ্রতুল।」\n「যদি সেই মানুষটা হয় বর্তমান সম্রাট?」\nআমি গভীর শ্বাস নিলাম.\n「এই পণ কি যথেষ্ট?」\nউভহাশ উচ্চস্বরে হেসে উঠল:\n「এটা তো অঙ্কের প্রশ্ন, পুরোনো সাথী। এক মানে এক, আর এক হাজার মানে এক হাজার।」\n\n「আগুন! সোনালি প্রাসাদে আগুন লেগেছে!」\nদূরে গর্জে উঠল অগ্নিশিখা.\nটাইর‍্যান্ট, টাইর‍্যান্ট...\nআমি হতাশায় কেঁদে উঠলাম, সেনেকার জন্য, আর সেই মহিমান্বিত প্রাসাদের জন্য, যা এখন ধ্বংসস্তূপে পরিণত হতে চলেছে.\n「তুমি কি সত্যিই এতটা শোকাহত?」\nউভহাশ ঝুঁকে এলো আরও কাছে.\nসে ইতিমধ্যেই সেই টরেস দাসটিকে ভোগ করেছে, নিজের তৃপ্তি মিটিয়ে ঠোঁট চাটছে.\nহ্যাঁ, আমি তাকে প্রতিশ্রুতি দিয়েছিলাম, যদি সে টাইর‍্যান্টকে হত্যা করতে পারে, তবে স্বাধীনতার পাশাপাশি সে আরও এক হাজার নির্দোষ প্রাণ ভোগ করতে পারবে.\nসে কি বুঝতে পারে এই আগুনের মানে কী?\nসে কি বোঝে, এক অনুতাপহীন টাইর‍্যান্টের সেবা করার মানে কী?\nসম্ভবত না.\nসে তো কেবল এক জানোয়ার.\n\n「রোম নিজেই এক ধ্বংসাবশেষ, 」 জানোয়ারটি বলল.\n「বা বলা ভালো, তোমার দেশ, এই বিশ্ব...\nআমার চোখে, সবই এক অর্থহীন, অন্তহীন ধ্বংসস্তূপ.\nতোমরা এর জন্য কাঁদো, একে অপরকে হত্যা করো, করছো সবকিছুই নিষ্ফল আর অর্থহীন...\nসত্যি বলতে, আমি বুঝি না।」\n\nআমি তার ক্ষতবিক্ষত দেহের দিকে তাকালাম.\nএটা এক গোলেম, লক্ষ লক্ষ মাংস আর রক্ত দিয়ে গড়া, শত শত বছর ধরে ভেঙে গিয়ে আবার জোড়া লেগেছে, ঠিক রোমের মতো.\n「তোমার কী অবস্থা? তুমিও কি এক ধ্বংসাবশেষ?」\n「হয়তো।」\nসে আলসেমিভাবে শরীর টানল, দূরের সোনালি আলো নেচে উঠল তার সরু চোখে.\n「কিন্তু আমি পরোয়া করি না।」"
  },
  CollectionHall_127154_Title = {
    Text = "রক্তাক্ত ভোজ"
  },
  CollectionHall_127155_Desc = {
    Text = "হে লেমুরিয়ার প্রভু, আমার প্রার্থনা শ্রবণ করো।\n\nতোমার ভবিষ্যদ্বাণী আমাকে দাও, তোমার অন্তর্দৃষ্টি বর্ষণ করো,\n\nযাতে আমি তোমার রাজ্য পুনরুদ্ধার করতে পারি।\n\nএই অবিশ্বাসী ভূমিতে, সাগরে বেষ্টিত এই বরফময় প্রান্তরে,\n\nতোমার স্তম্ভ স্থাপন করো, আর গড়ে তোলো তোমার মন্দির।\n\n\nহে অতল গহ্বরের প্রভু, এই নিবেদিত কবিতা গ্রহণ করো।\n\nপূর্ণিমার মেষশাবকের নির্মল মাংস, পূর্ণবয়স্ক ষাঁড়ের শক্তিশালী হৃদয়,\n\nউর্ধ্বগামী ঈগলের তীক্ষ্ণ চোখ, আর সাগর চিরে চলা তিমির কঠিন অস্থি।\n\nল্যাপিস তোমার সিংহাসন, সোনা তোমার মুকুট,\n\nতোমার স্বপ্নলোক আমাকে দাও, তোমার দেববাণী শোনাও,\n\nযাতে আমি তোমার রূপ পুনরুদ্ধার করতে পারি।\n\nবরফের নীচের অতলে, তরঙ্গের তলদেশের রাজ্যে,\n\nআমি সময়মতো জন্ম নেওয়া মাতৃদর্শনকে উৎসর্গ করছি।\n\n\nহে সর্বজ্ঞ লেমুরিয়ার রাজা, আমার প্রার্থনার উত্তর দাও।\n\nতুমি তোমার দীর্ঘ তন্দ্রায় নিমজ্জিত হওয়ার পর শতাব্দী কেটে গেছে।\n\nতোমার নামে আমি কাজ করি, আর তোমার গৌরব আমি ঘোষণা করি, অবিরাম।\n\nআমার বিশ্বাস অটল, আমার হৃদয় ভক্তিময়।\n\nতুমি একমাত্র দেবরাজ, অমরত্বের মূর্ত প্রতীক।\n\nআমার প্রতীক্ষার অবসান ঘটাও, জগতে প্রত্যাবর্তন করো, আর তোমার প্রজ্ঞাবাণী আমাকে শোনাও।"
  },
  CollectionHall_127155_Title = {
    Text = "ধার্মিকের মহাশক্তি"
  },
  CollectionHall_127156_Desc = {
    Text = "অরিটা যখন জন্মাল, শহরে মহাপ্লাবনের আঘাত পুরোপুরি মিলিয়ে গেছে, কিন্তু দূরবর্তী ছোট ছোট শহরে মানুষ তখনও কেবল বেঁচে থাকার জন্য লড়ছে।\n\nপ্লাবন মানুষকে সাগর আর নদীকে ভয় করতে শিখিয়েছে; যারা পারত, তারা অনেক আগেই প্রয়াত আত্মা হয়ে চলে গেছে, আর এই ছোট মাছ ধরা গ্রামে যারা রয়ে গেছে, তারা বেশিরভাগই নারী আর বালকেরা, যারা অন্য কোথাও গিয়ে পা রাখার জায়গা খুঁজে পায় না।\nএই মলিন, নীরব স্থানে অরিটাই একমাত্র শিশু।\n\nসে একগুঁয়ে ভাবে বিশ্বাস করে দিদিমার বলা রূপকথাগুলো—তার বাবা-মা সাগরে ফিরে গেছে, অরিটার বড় হওয়ার প্রতীক্ষা করছে। সে একবার বড় হয়ে উঠলেই, সবাই আবার একত্র হবে, আর তারা আবারও সুখী পরিবার হয়ে উঠবে।\n\nযখন সে কথা বলতে শেখেনি, তখন যেন মনে হতো সে কোনো এক উষ্ণ তোষামোদকারীর আলিঙ্গনে ঘুমিয়েছিল; কিন্তু এখন অরিটার পক্ষে তার বাবা-মাকে নিয়ে অনেক কিছুই মনে করা আর সম্ভব নয়।\nতবু, নীরব জায়গায় বড় হওয়া এক শিশুর মতো, অরিটা “একাকিত্ব” বা “উজাড়” শব্দের মানে বোঝে না; তার নিজেরই একদল বন্ধু আছে।\n\nযে সব প্রাপ্তবয়স্ক প্লাবনে আতঙ্কিত হয়ে পড়েছিল, তাদের মতো নয়, অরিটা কোনোদিনই সাগরকে ভয় পায়নি।\nওশান কিংয়ের ডোমেইনের বাসিন্দা হিসেবে, তার স্বাভাবিকভাবেই সাগরের সঙ্গে বন্ধুত্ব করা উচিত।\nঅরিটা “স্থানীয়দের” সঙ্গে খেলতে শেখে।\nসে ঝিনুকের চলাফেরা নকল করে নাচে, সাগরঘাসের ভেতর দিয়ে সাঁতার কাটা ক্লাউনফিশদের দেখে শেখে।\nসে লেদারব্যাক কচ্ছপের খোলের ওপর শুয়ে থাকে, ঢেউয়ের টানে ভেসে ভেসে ভূমি থেকে দূরে সরে যায়।\nসাগরে, চাঁদের আলোয় স্নান করে, সে জেলিফিশের ঝাঁকের সঙ্গে খেলে।\n\nসে আনন্দ, সে কল্পনা, সে এক পরী।\n\nসে এক স্বপ্ন।"
  },
  CollectionHall_127156_Title = {
    Text = "সাগরের স্বপ্ন"
  },
  CollectionHall_127157_Desc = {
    Text = "গ্রামের এক মেয়েছেলে, গায়ে আড়ম্বরপূর্ণ গাউন, গলায় সোনা-সিলভার গয়না, হাতে পালকের পাখা—চুপিসারে ঢুকে পড়েছে উচ্চবিত্তের জগতে...\nএর চেয়ে বেশি অশোভন আর কী হতে পারে। নিম্নস্তরের কেউ আমাদের পরিসরে অনধিকার প্রবেশ করেছে—এ একেবারেই কেলেঙ্কারি...!\nআমি বলি, তাদের জন্য বাধ্যতামূলক পরিচয় ব্যাজ থাকা উচিত, যাতে তাদের আমাদের কারও সঙ্গে ভুল না হয়।\n—ডিউক ফিলিপ হ্যারল্ড\n\nআপনি যদি লন্ডিনিয়ামে থাকেন, তবে তথাকথিত “সোরেল প্রভাব” সম্পর্কে নিশ্চয়ই জানেন।\nএখনো কি ভয় পাচ্ছেন আপনার পোশাক বিকোবে না? তবে ভালো হয়, যদি আপনি প্রার্থনা করেন যে লেডি সোরেলের অনুগ্রহ পাওয়ার মতো কিছু যোগাযোগ আপনার আছে—হ্যাঁ, এমনকি হাস্যকরভাবে বোকা শূকরের লেজের মতো ঝুলন্ত টুপি-ও, যদি লেডি সোরেলের মাথায় ওঠে, তবে তা হু হু করে বিকোবে।\nতিনি নতুন যুগের পপ আইডল।\n—“লেডি সোরেলের খ্যাতি কুইজ”, ভদ্রমহিলার নির্দেশিকা\n\nসেটা ছিল এক নির্মল গ্রীষ্মরাত।\nআমরা মার্বেল পাতা বারানদায় পাশাপাশি বসে, পুরোনো সম্ভ্রান্ত বট্রাইটিস মদ চুমুক দিচ্ছিলাম, আলোচনা করছিলাম কবিতা আর বিশ্বশান্তি নিয়ে।\nতারপর কিছু একটা ঘটল @4\nমূল কথায় আসি? আ-হেম, ক্ষমা চাইছি...\nসংক্ষেপে বললে, এই নারী আমাকে ঠকিয়ে নিয়েছে তিন হাজার লিও ফাং, সোরল্যান্ডের দুইখানা সম্পত্তি, আর একখানা অকৃত্রিম হৃদয়!\n—এক হৃদয়ভাঙা ভিসকাউন্ট, যিনি নাম প্রকাশে অনিচ্ছুক"
  },
  CollectionHall_127157_Title = {
    Text = "গোলাপের নামে"
  },
  CollectionHall_127158_Desc = {
    Text = "বিচ্ছিন্ন হও। অনুভব করো। প্লাবিত হও। আক্রমণ করো।\n\nফিলিস্তিনী জাতির মধ্যে সেমিটিক মূল “p-l-sh”-এর প্রকৃত অর্থ নিয়ে পণ্ডিতেরা বহুদিন ধরে বিতর্ক করে আসছেন।\nজীবনে প্রথমবারের মতো গোলিয়াথ অনুভব করল, এই বৃদ্ধ পণ্ডিতদের মধ্যে সত্যিই কিছু অন্তর্দৃষ্টি আছে; কারণ এই চারটি সংক্ষিপ্ত শব্দ প্রায় তার সমগ্র ফিলিস্তিনী জীবনকে ধারণ করে।\n\nফিলিস্তিনীরা নিঃসন্দেহে এক সামুদ্রিক জাতি।\nতারা যেন লম্বা লেজওয়ালা হাঙরের ঝাঁক, রক্তের গন্ধে বাসযোগ্য দ্বীপের দিকে টেনে নেওয়া হয়, তারপর সেখানে থাকা সব আদিবাসীকে জবাই করে ফেলে।\n\nফিলিস্তিনীরা কখনো ক্লান্ত হয় না।\nতারা কোথাও থিতু হয় না; সবকিছু স্তিমিত হলেই তাদের অস্থির প্রবৃত্তি তাদের আবার এগিয়ে যেতে তাড়িত করে, নতুন শিকার খুঁজতে।\n\nফিলিস্তিনীরা আগামীকাল নিয়ে ভাবে না।\nতারা লুট করা সম্পদ অবিশ্বাস্য দ্রুততায় উড়িয়ে দেয়, শেষ ফোঁটা মদটুকুও পান করে ফেলে, তারপর উন্মত্তভাবে প্রজনন, লড়াই আর বিশ্বাসঘাতকতায় মেতে ওঠে…\n\nযখন তারা পাল তোলো, গোলিয়াথ সমুদ্রের বুকে জাহাজের রেখে যাওয়া চিহ্নের দিকে ফিরে তাকাল।\nফিলিস্তিনীর রক্ত, আদিবাসীর রক্ত, শত্রুর রক্ত, সমুদ্রপাখির রক্ত…\nসব একাকার হয়ে গেল, যেন গাঢ় লাল কালি অনন্ত নীলের ভেতর ছড়িয়ে পড়ছে।\n\nপরদিন সূর্য স্বাভাবিক মতোই উদিত হল, সমুদ্র ঝিকমিক করল অসংখ্য ভাঙা সোনার টুকরোর মতো, আর সবকিছু বিনা চিহ্নে মিলিয়ে গেল।\nতারা ছিল সমুদ্রে, অথচ সমুদ্র তাদের ভুলে গেছে।"
  },
  CollectionHall_127158_Title = {
    Text = "দৈত্যের তরবারি"
  },
  CollectionHall_127159_Desc = {
    Text = "কাশুরিয়ায়, ডুবে যাওয়া এক সভ্যতাকে ঘিরে কিংবদন্তি প্রচলিত আছে。\n\nকথিত আছে, লিখিত ইতিহাসেরও আগে, নক্ষত্রপুঞ্জের এক অস্বাভাবিক সরে যাওয়ায় এক প্রাগৈতিহাসিক সভ্যতা সমুদ্রগর্ভে তলিয়ে যায়, আর কাশুরিয়ানরাই সেই সভ্যতার বংশধর。\nবাণিজ্য আর মাছ ধরা ছাড়াও, কাশুরিয়ানদের সমুদ্রে পাড়ি জমানোর আরেকটি বড় কারণ হলো তাদের হারিয়ে যাওয়া পূর্বপুরুষের সভ্যতাকে খুঁজে বের করা。\nতারা বিশ্বাস করে, নির্দিষ্ট নক্ষত্র বিন্যাসের অধীনে জন্ম নেওয়া মেয়েরা এই প্রাচীন সভ্যতাকে অনুভব করতে পারে, তাদেরকে তার অবস্থানের দিকে পথ দেখায় এবং ঝড় থেকে নৌবহরকে রক্ষা করে。\n\nএই উদ্দেশ্যেই সেলেস্টকে বেছে নেওয়া হয়েছিল。\nসাদা পালওয়ালা জাহাজের মাস্তুলে বাঁধা অবস্থায়, সে নিচে ব্যস্ত মানুষের আনাগোনা দেখত。\nতার মধ্যে জাগত না কোনো আগ্রহ, না কোনো কৌতূহল。\n\nসেলেস্ট বাতাস আর পাখির মাধ্যমে সমুদ্রের আবহাওয়া টের পেত, কখনো কখনো দূরের ডুবে যাওয়া ভূমির ক্ষীণ আভাসও ধরতে পারত。\nতার মনে হতো, সে যেন সমুদ্র আর জাহাজেরই অংশ—প্রায়ই ভাবত, তার এই বন্দিত্ব তার ভেতরে কোনো অনুভূতির ঢেউ তোলে না。\nকখনো কখনো সে মাস্তুল ছেড়ে আকাশে উড়ে যাওয়া সাদা পাখিদের পিছু নিত, আর জাহাজটি ঘনিষ্ঠভাবে তার পিছু পিছু চলত。\nমানুষেরা বিশ্বাস করত, এই মেয়েটি নিরাপদ সমুদ্রযাত্রার প্রতীক, সে নৌবহরকে আশীর্বাদ দেয়, যাতে তারা নিরাপদে ফিরে আসতে পারে অফুরন্ত ধনসম্পদ আর উন্নত জ্ঞান নিয়ে。\nকিন্তু সে এসবের কিছুই জানত না।"
  },
  CollectionHall_127159_Title = {
    Text = "প্রভিডেন্সের পাল"
  },
  CollectionHall_127160_Desc = {
    Text = "টাপ, টাপ, টাপ।\nপদধ্বনি এগিয়ে আসে। টপ হ্যাট পরা এক ভদ্রলোক ধ্বংসস্তূপের ভেতর দিয়ে হেঁটে এসে মৃত্যুপথযাত্রী এক প্রহরীর সামনে দাঁড়ায়।\nভদ্রলোক: তুমি এখানে কী করছো?\n\n(ভদ্রলোকের ভীষণ তোতলামি আছে, আর প্রহরী কথা ঘুরিয়ে বলতে ভালোবাসে। তোমার পাঠের সুবিধার জন্য, কথোপকথনের কেবল মূল অংশগুলোই লিপিবদ্ধ করা হলো।)\n\nপ্রহরী: আমি কারাগার পাহারা দিচ্ছি।\nভদ্রলোক চারদিকে তাকালেন—উজাড় প্রান্তর, আর ধীরে ধীরে ভেঙে পড়া ধ্বংসাবশেষ, ডিজলিউশনের কলঙ্কে দাগধরা।\nভদ্রলোক: কিন্তু এখানে তো কোনো কারাগার নেই, নেই কোনো বন্দীও। তোমার রাজ্য আর অস্তিত্বই রাখে না।\nপ্রহরী: আমি কারাগার পাহারা দিচ্ছি।\nভদ্রলোক: কেন?\nপ্রহরী মাথা তোলে; শিশুর মতো মুখ, বিভ্রান্তি আর দৃঢ়তায় ভরা।\nপ্রহরী: জানি না... আমি বাড়ি যেতে চাই।\nপ্রহরী: আমি ওই প্রভুর জন্য কারাগার পাহারা দিচ্ছি। প্রভু খুশি হলে, আমি বাড়ি যেতে পারব।\nসে জানেই না সেই প্রভু কে, বা কেন তাকে পাহারা দিতে হবে।\nভদ্রলোক আর কিছু জিজ্ঞেস করেন না, যেন এটাই সবচেয়ে স্বাভাবিক ব্যাপার।\nভদ্রলোক: তোমার বাড়িটা কেমন?\nপ্রহরী: সেখানে শুধু শীত আর রাত, অন্তহীন অরণ্য আর সাগর।\nভদ্রলোক: শুনে তো বাসযোগ্য মনে হয় না।\nপ্রহরী: আমি দিনের আলো ঘৃণা করি। দেখছো? আমি মোম দিয়ে গড়া। সূর্যকে ছুঁলেই আমি মিলিয়ে যাবো।\nপ্রহরী: তাই আমি এখানে লুকিয়ে আছি, একা নিজে থেকে বাড়ি ফিরতে পারি না।\nভদ্রলোক চিন্তিত ভঙ্গিতে মাথা নাড়লেন। হঠাৎই তিনি উৎফুল্ল হয়ে উঠলেন।\nভদ্রলোক: কী অদ্ভুত কাকতাল! তুমি মোমের, আর আমি ঘটনাচক্রে একজন মোম ভাস্কর।\nভদ্রলোক: চল, একটা চুক্তি করি—আমি তোমাকে দিনের আলোয় হাঁটার ক্ষমতা দিতে পারি, আর তোমার বাড়ির পথ খুঁজে পেতে সহায়তা করতে পারি। বদলে, তুমি হবে আমার সহায়তা।\nপ্রহরী: সহায়তা, সেটা কী?\nভদ্রলোক: তুমি আমার মোম জাদুঘর পাহারা দেবে। এটা এই কারাগারের মতো নয়; এটা শিল্প, আর শিল্প কখনো ভেঙে পড়ে না।\nপ্রহরী: শিল্প কি এতটাই শক্তিশালী?\nভদ্রলোক আনন্দে হেসে ওঠেন।\nভদ্রলোক: হ্যাঁ, এতটাই শক্তিশালী।\n\nগল্পের শেষে, প্রহরী যেমন ভাবে এলোমেলোভাবে এই কারাগারে এসে পড়েছিল, তেমনই এলোমেলোভাবে ভদ্রলোকের পিছু নিলো।\nসে সবসময়ই স্রোতের টানে ভেসে যাওয়া একজন মানুষ।"
  },
