  CollectionHall_127161_Desc = {
    Text = "তুমি পা রাখো এক অনুর্বর, প্রাণহীন উজাড় ভূমিতে।\n\nমানবতার দীপ্তির সব চিহ্ন বহু আগেই মিলিয়ে গেছে। শুকিয়ে যাওয়া আত্মারা ছাই আর ধোঁয়ার ভেতর দিয়ে টেনে টেনে হাঁটে, কষ্টেসৃষ্টে শ্বাস ধরে রাখে।\n\nএখানে বেঁচে থাকা কোনো বিজয় নয়।\nকোথায় শেষ হয় এই যাত্রা, কেউ জানে না। তারা ঘুরে বেড়ায়, ঘুরে বেড়ায়, আবারও ঘুরে বেড়ায়, অনন্ত শূন্যতার এক চক্রে বন্দী হয়ে।\n\nযতক্ষণ না তাদের পদক্ষেপ থমকে যায়, আর তারা দগ্ধ মাটিতে লুটিয়ে পড়ে, চোখ আকাশের দিকে, হাত বাড়িয়ে মিনতি করে:\n\nআমার যাত্রার শেষ যেন হয়ে ওঠে এক নতুন শুরু।\n\nএই অস্থিগুলো মাটি হোক, আহার হোক, বসন্ত হোক, যাতে ভঙ্গুর কুঁড়ি আবারও ধুলো ভেদ করে মাথা তোলে।"
  },
  CollectionHall_127161_Title = {
    Text = "ধ্বংসভূমিতে পুনর্জন্ম"
  },
  CollectionHall_127162_Desc = {
    Text = "অগণিতবার সে গভীর রাত্রির নিস্তব্ধতায় নিজেকে জিজ্ঞাসা করেছে: কেন তাকে এই অন্তহীন যন্ত্রণা সহনশীলতা দিয়ে সহ্য করতে হবে?\nকেউ উত্তর দেয়নি。\nতার কর্কশ হুইসপার ভেঙে গিয়ে খণ্ডাংশে পরিণত হয়েছে, কোনো দেবতার কানে পৌঁছায়নি কখনো。\nতার যন্ত্রণা পচে গিয়ে পুঁজে রূপ নিয়েছে, আর গভীরতর ঘৃণার মদন তৈরি করেছে。\nএকদিন, সে লক্ষ্য করল আশেপাশের মানুষের শরীর থেকে কালো তরল ঝরছে, যা তার নিজের রক্তের মতো。\nতারা দ্রুত উন্মাদনায় ডুবে গেল, ঠিক তার মতোই。\nহয়তো ওটা তাদের যন্ত্রণা ছিল; সে শীতল চোখে তাকিয়ে রইল, অন্তরে এক ক্ষীণ তৃপ্তি অনুভব করল。\nকিন্তু যদি ওটাই যন্ত্রণা হয়, তবে কি সে বহু আগেই অন্ধকারে গ্রাস হয়ে যায়নি?\nসে lingering সেই কালো স্রোতের কাছে এগিয়ে গেল এবং অপ্রত্যাশিতভাবে সেখানে খুঁজে পেল মুক্তি。\nতবু সেই মুক্তি কোনো স্বস্তি আনল না; সে যেন সহস্রাব্দ ধরে নরকে নির্বাসিত এক দানব, যার কামনা ঘৃণায় ক্ষয়প্রাপ্ত。\nতার দেহ শৃঙ্খলে আবদ্ধ, তার আত্মা সীসার ভারে নুয়ে পড়া。\nশুধু ভৌতিক আর্তনাদই তার ভারী আত্মাকে শুদ্ধ করতে পারে, তাকে মুক্ত শ্বাস নিতে দেয়。\nএসো, যা আমি আস্বাদন করেছি তা-ই তুমি চেখে দেখো, এবং আমারই রূপ নাও。\nসে দেখল, লাল আসলে এক বিস্ময়কর মূল বর্ণ。\nসে অবশেষে বুঝল: যন্ত্রণার কোনো কারণ নেই。\nঅথবা নিজেই তা পান করো, অথবা অন্যদের আমন্ত্রণ জানাও ভাগ করে নিতে。\nআজ রাতে, সে তিক্ত মদ ঢেলে রেখেছে, আমন্ত্রণ জানিয়েছে সমগ্র শহরকে।"
  },
  CollectionHall_127162_Title = {
    Text = "রক্তিম লালে নিমজ্জন"
  },
  CollectionHall_127163_Desc = {
    Text = "আমার নৌকাটাকে কোনো কিছুর দ্বারা শক্ত করে জড়িয়ে ধরা হয়েছে; প্রপেলার প্রাণপণে ঘুরতে চাইছে, ভয়ংকর শব্দ তুলছে।\nউপরে কিউমুলোনিম্বাস মেঘ জমেছে, অন্ধকার মেঘের ভেতর দিয়ে বিদ্যুৎ স্রোত বইছে।\nএকটি বজ্রপাত যখন মাস্তুলে আঘাত করল, প্রপেলার শুঁড়ের বাঁধন ছিঁড়ে আবার ঘুরতে শুরু করল।\nআমি স্বস্তির নিঃশ্বাস ফেললাম, কিন্তু প্রধান প্রকৌশলী চিৎকার শুরু করল।\n\nএক ধরনের আঠালো তরল সাগরের জলে মিশে গেল, আর বাইরে বুনো ঝড়ের মধ্যে, গন্ধটা বাতাসে ভেসে দূরে চলে গেল, আমার নাকে রয়ে গেল শুধু মৃত্যুর গন্ধ।\nকিন্তু আমি বুঝলাম, ওই জ্বলজ্বলে তরল আসলে এক ধরনের রক্ত।\nআমার সবচেয়ে প্রিয় সঙ্গী, আমার সবচেয়ে বিশ্বাসী জাহাজ, ডুবে যাওয়ার আগে তার সবটুকু দিয়ে গেছে—যে ব্লেডগুলো জলের বুক চিরে এগিয়ে যাওয়ার কথা ছিল, সেগুলোই দানবের শুঁড় কেটে ফেলেছে।\n\nএটা এক শুভ লক্ষণ! আমরা খুব শিগগিরই ঝড় থেকে বেরিয়ে আসব!\nআমি এই ভাবনা দিয়ে আমার নাবিকদের সান্ত্বনা দিতে যাচ্ছিলাম, এমন সময় মাথা তুলে দেখি, আলোহীন সাগরের কেন্দ্রে এক টুকরো আলো জ্বলে উঠেছে।\nএকটা বাতিঘর? কী করে সম্ভব? না, অসম্ভব।\nআমরা সাগরের মাঝখানে। নিকটতম ভূমি শত শত মাইল দূরে। এখানে কেউ কী করে বাতিঘর বানাবে?\n\nআমার নাবিকরা একসঙ্গে কাঁদতে, প্রার্থনা করতে, আর ঘরের গান গাইতে শুরু করল।\nতারপর, বাতিঘর হঠাৎ নিভে গেল।\nসব আলো মিলিয়ে গেল, আর গর্জন করা ঝড় ডেকে গুঁড়ি গুঁড়ি বৃষ্টিতে পরিণত হলো।\nনাবিকরা দয়ালু প্রভুর স্তবগান করতে লাগল, বিপদ থেকে বেঁচে ফেরার আনন্দে নিমজ্জন হলো।\nকিন্তু আমি স্পষ্টই দেখেছি।\n\nআলোর ভেতর থেকে যে অবয়ব মিলিয়ে গেল, সে নিঃসন্দেহে এক সুশ্রী নারী।"
  },
  CollectionHall_127163_Title = {
    Text = "প্রবল বর্ষণের মাঝে"
  },
  CollectionHall_127164_Desc = {
    Text = "যখন নায়ক অবশেষে তার মহাযাত্রার পরিসমাপ্তি টানে, আর মানুষ ছবির বইয়ের শেষ পৃষ্ঠা বন্ধ করে ঘুমের অতলে ভেসে যায়।\n\nদীর্ঘ রাত্রি নেমে এলে, হেলটের কাহিনি শুরু হয়।\n\nসে উত্তরের দিকে দীর্ঘ উপকূলরেখা ধরে যাত্রা করে, স্রোতস্বিনী পার হয়, পর্বতমালা অতিক্রম করে, অবশেষে পৌঁছে যায় হিমশীতল ভূমির প্রান্তে।\nবহু বছর কেটে গেছে সেই শিহরণ জাগানো বিদ্রোহের পর, যেখানে হেলট যেখানেই গিয়েছে, সেখানেই শান্তি ও সমৃদ্ধি বয়ে এনেছে। দাস ও প্রভুর মাঝে এক সূক্ষ্ম ভারসাম্য গড়ে উঠেছিল, যা সহিংস বিদ্রোহকে করে তুলেছিল বেমানান ও হাস্যকর।\nতাকে জিজ্ঞাসাবাদ করা হয়েছে, উপহাস করা হয়েছে, এবং শেষ পর্যন্ত ভুলে যাওয়া হয়েছে।\nকিন্তু সে কখনও নিজের পক্ষে সাফাই গায়নি।\n\nযোদ্ধা হেলট এসেছিল আর চলে গিয়েছিল বাতাসের মতো, মারে ইন্টারনামের হৃদয়ে স্বাধীনতার বীজ বপন করে। পাঁচ বছর, দশ বছর, একশো বছর...\nএকদিন, তারা মাটি ভেদ করে বেরিয়ে আসবে এবং বিকশিত হবে।\n\nকেউ জানে না এই স্পার্টান ঘাতককে কোথায় সমাধিস্থ করা হয়েছে, যদিও শোনা যায় তার পুরাতন বন্ধু এপামিনন্দাসই তার দেহাবশেষের দেখভাল করেছিল।\nবহু বছর পরে, যদি তুমি কোনো জুঁই-ঢাকা সবুজ টিলার পাশ দিয়ে যাও, হয়তো দেখতে পাবে একটি ছোট সমাধিফলক, তাতে লেখা:\n\nএই ঘাসের নিচে শুয়ে আছে এক যোদ্ধা, অথবা বরং,\nসে একসময় ছিল যোদ্ধা।\nসে বৃদ্ধ পেরিক্লিসের কন্যা এবং টিলোসের গর্ব।\nকবি থ্রাসিয়াস তার যুদ্ধকুশলতার স্তব গেয়েছেন।\nআর কালোচুল স্পার্টানরা তার কীর্তি আরও ভালো জানে।"
  },
