  CollectionHall_127167_Desc = {
    Text = "তাকে বলা হয় মৃত্যুকে বুকে নিয়ে জন্মানো অভিশপ্ত শিশু, অনাশীর্বাদপ্রাপ্ত কন্যা।\nতার আর তার বোনের যে \"দোলনা\" ছিল, তা সদ্য ভেঙে চুরমার হয়েছে, আর ফাটল গলে উথলে পড়ছে তীব্র আলোকধারা, মাটিতে গিয়ে শিকড় গাঁথছে। মুহূর্তের মধ্যে সবুজ ঘাস শুকিয়ে যায়, ফুলের রঙ উবে যায়, এমনকি দূরের গাছ আর হ্রদের মাছও প্রাণশক্তি হারিয়ে ফেলে, হয়ে যায় প্রাণহীন খোলস।\nতার পরিবার আতঙ্কে হাঁ করে তাকিয়ে থাকে, তাড়াহুড়ো করে অন্য সব দোলনা সরিয়ে নেয়। সে দোলনা থেকে নিজেকে ছাড়িয়ে বেরোতে লড়াই করে, যেন ডিম ফোটানো বাচ্চা পাখি, কিন্তু তার বাড়িয়ে দেওয়া হাতগুলোকে ঘৃণাভরে সরিয়ে দেওয়া হয়, আর সে যা দেখে, সবই অবজ্ঞায় বিকৃত মুখ।\nশুধু তার বোন, যে সেই রাতেই জন্মেছিল আর তার চেয়ে আগে পরিণত হয়েছে, সে-ই তাকে চিরকাল বুকে জড়িয়ে রাখবে। আত্মা-পাখির মতো কণ্ঠে সে লোরি গায়।\n\"ঘুমাও, ঘুমাও, আমার প্রিয় বোন;\nঘুমাও, ঘুমাও, মধুর স্বপ্ন নিশ্চয়ই আসবে।\"\n\nতার অস্তিত্ব থাকার কথা নয়, আর যদি সে না থাকত, তবে তার দীপ্তিময় বোন পাপের ছায়ায় কলঙ্কিত হতো না।\nআমার বেচারা বোন, সে সবসময়ই ভাবে, তোমার অস্তিত্বের যে মূল্য, তা তোমার বহন করার কথা ছিল না।\nআমার বেচারা বোন, সে সবসময়ই ভাবে, যতক্ষণ না বোনের পক্ষে সম্ভব, ততক্ষণ সে নিশ্চয়ই তোমার জন্য নিজেকে পুরোপুরি বিলিয়ে দেবে।\n\"ঘুমাও, ঘুমাও, আমার প্রিয় বোন;\nঘুমাও, ঘুমাও, স্বপ্নের মধ্যেও তোমায় ভালোবাসি।\""
  },
