  CollectionHall_127168_Desc = {
    Text = "সে দেখল গির্জার সুউচ্চ চূড়া মোমবাতির মতো গলছে, আর তার গলিত অংশ ঝরে পড়ছে পুরোহিতের নির্মল সাদা ডানার ওপর।\nরঙিন কাঁচের জানালার সাধুরা দ্রুত পচে কঙ্কালে পরিণত হচ্ছে, তারপর মুহূর্তের মধ্যে আবার শিশুর রূপে ফিরে যাচ্ছে।\nতীক্ষ্ণ আর কোমল জ্যামিতিক আকৃতি উচ্চারিত হতে লাগল ভক্তদের মুখ থেকে, আর সেই ধ্বনি ভরে তুলল সমগ্র প্রার্থনাগৃহ।\n\nসে দেখল রেলস্টেশনের স্থান বারবার ভাঁজ খাচ্ছে অ-ইউক্লিডীয় জ্যামিতির মতো; দূরের প্ল্যাটফর্ম হাত বাড়ালেই ছোঁয়া যায়, অথচ একেবারে কাছে থাকা টিকিট গেটটি অবিশ্বাস্য দূরত্বে সরে গেছে।\nপ্রাঙ্গণের ঘড়ি ঘুরছে উল্টো দিকে, আর কঙ্কালসার ভিড় হাঁটছে পিছন দিকে, অদৃশ্য সুতোয় টেনে নিয়ে যাচ্ছে কেউ, আর আকাশের মেঘ থেকে ঘন বেগুনি ধোঁয়া নেমে এসে ঢুকে পড়ছে ট্রেনের মুখে।\n\nসে দেখল বনের ভেতরের সেই 「শূন্যতা」 আকার নিচ্ছে; গাছ, পাথর আর লতা-পাতা কেবলমাত্র সেই 「শূন্যতা」 আঁকা স্বচ্ছ অবয়বের সীমানা টেনে দিচ্ছে।\nরাজহাঁসের পালক ক্রমাগত বদলে যাচ্ছে মোজাইক রঙে, আর যেখানে তারা সাঁতার কাটছে, সেখানে হ্রদের জল জমে যাচ্ছে স্বচ্ছ রঙিন কাঁচের পাতের মতো।\nযে বেঞ্চে যুগলরা গা ঘেঁষে বসে আছে, তার নিচে এক তীব্র কমলা-হলুদ ছায়া মালিকের গোড়ালিতে দাঁত বসানোর জন্য ব্যাকুল হয়ে কুরে কুরে খেতে চাইছে।\n\nসে দেখল অপেরা হলের সুরের নোটগুলো বৃষ্টির ফোঁটার মতো আছড়ে পড়ছে দর্শকদের গায়ে, আর সে দেখল কবরস্থান ধীরে ধীরে উঠছে-নামছে, যেন কোনো নিঃশ্বাস ফেলা দৈত্যাকার জন্তুর চামড়া...\n\nসে অনেক কিছু দেখেছে, অগণিত। সে যা দেখেছে, তা বলেছে মাকে, শিক্ষকদের, বন্ধুদের, আর যা দেখেছে তা এঁকেছে নিজের ছবিতে।\nসে চেয়েছিল তার দেখা সেই জগতকে মানুষের সামনে তুলে ধরতে, কিন্তু তার চারপাশের মানুষের সংখ্যা ক্রমেই কমে গেল, আর এক একটি জগৎ ভেসে যেতে লাগল তার থেকে আরও দূরে।\n\nকিন্তু কেন এমন হলো? সে তো কেবল দেখেছে, আর তা লিপিবদ্ধ করেছে।\nপিকম্যান বুঝতে পারল না।\n\nবিষণ্ন পিকম্যান আয়নার সামনে দাঁড়াল।\nসে দেখল এক ঘুল তার দিকে দাঁত বের করে হাসছে, ধারালো, দাঁতভরা চোয়াল মেলে।\n\n「বাস্তবকে প্রত্যক্ষ করার চেয়ে গুরুত্বপূর্ণ আর কিছু নেই। উন্মাদনা, বিশৃঙ্খলা, লোভ...\nদেখতে চাও, পিকম্যান?」\n\nআত্মজাগরণপ্রাপ্ত পিকম্যান তাকে দেখে মৃদু হাসল, আর পা বাড়াল আয়নার ভেতরে।\n\nসে কেবল নিজের চোখে বাস্তবের চূড়ান্ত উন্মাদনাকে প্রত্যক্ষ করতে চেয়েছিল, আর তা বিশ্বস্তভাবে ফুটিয়ে তুলতে চেয়েছিল নিজের ক্যানভাসে।\n\nসে না মানুষ, না ঘুল।\n\nসে শুধু পিকম্যান, বাস্তববাদী চিত্রকর।"
  },
  CollectionHall_127168_Title = {
    Text = "বাস্তববাদী বিরোধাভাস"
  },
  CollectionHall_127169_Desc = {
    Text = "যখন কেউ অতীত আর ভবিষ্যতের সবকিছু জেনে ফেলে, তাকে স্বাগত জানায় আনন্দ নয়, অন্তহীন শোক আর হতাশা।\nতার চোখ সবকিছুর আড়ালের সুতো দেখতে পায়—এক প্রান্ত বাঁধা অতীতে, অন্য প্রান্ত ভবিষ্যতে।\nএই সুতোগুলোর নামই ভাগ্য।\nসে কীভাবে দেখে তার চারপাশের মানুষদের?\nমানুষ দয়ালু আর ভালোবাসায় ভরা, তবু ঔদ্ধত্যে অন্ধ আর সন্দেহে কলুষিত।\nকিন্তু তাদের ভাগ্য, আর মানবতার দীপ্তির পরিণতিও, তাদের সাক্ষাতের মুহূর্ত থেকেই সিলমোহর হয়ে যায়।\nসে নিশ্চয়ই তাদের ভালোবাসে; নইলে কেন বারবার সাহায্যের হাত বাড়িয়ে দিত, কেনই বা তাদের আগুন দিত?\nসে নিশ্চয়ই তাদের প্রতি প্রত্যাশা পোষণ করে; নইলে কেন ধ্বংসের মাঝখানে পুনর্জন্মের ছায়ায় পা বাড়াত?\nভালোবাসার কারণেই সে শোক অনুভব করে।\nপ্রত্যাশার কারণেই সে বারবার হতাশ হয়।\nসে গভীরভাবে ডুবে আছে এক কালো জলাভূমিতে, ক্লান্তিহীন হাতে গুছিয়ে চলেছে অসংখ্য কালো সুতো।\nভাগ্যের চাকা ঘুরে চলে বারবার।\nসে দেখে লোভী আগুন আকাশ জুড়ে ঝাড়ু বুলিয়ে যাচ্ছে।\nসে দেখে অন্ধ একগুঁয়েমি কীভাবে আত্মবিস্ফোরণের দিকে ঠেলে দেয়।\nসে দেখে উন্মত্ত বিভ্রান্তি কীভাবে ধ্বংসকে ত্বরান্বিত করে।\nকেওস সর্বদাই এসে পড়ে।\nআশা আর হতাশা বৃথাই ঘুরপাক খায়, অন্তহীন।\nযতক্ষণ না সে অন্ধকারে এক ঝলক ক্ষণস্থায়ী তারার আলো দেখে।\nসেই আলো, ক্ষীণ হলেও, তার দীর্ঘ রজনীতে প্রবল দীপ্তি ছড়ায়।\nসেই দেখার মুহূর্তেই, তার চোখ থেকে একটি অশ্রুবিন্দু গড়িয়ে পড়ে।"
  },
  CollectionHall_127169_Title = {
    Text = "অদৃশ্য চক্র"
