  CollectionHall_129601_Desc = {
    Text = "<Title:পরিচিতি>\nবিশ্ব থেকে বিচ্ছিন্ন এক দ্বীপে বসবাসকারী, প্রাণবন্ত ও বন্য প্রকৃতির এক তরুণী।\nতার চঞ্চল স্বভাব এবং জন্মগত অতিমানবীয় শক্তির কারণে, প্রথম পরিচয়ে অনেকেই তার অতিরিক্ত উৎসাহী ঘনিষ্ঠতার সাথে মানিয়ে নিতে কষ্ট পায়। তবে কিছুটা সময় কাটালেই বোঝা যায়, সে শুধু যতটা সম্ভব বন্ধুদের সাহায্য করতে চায়।\nযদিও তার সাহায্যের পদ্ধতি মাঝে মাঝে সাধারণ মানুষের থেকে ভিন্ন হয়, তবে ফলাফলের দিক থেকে দেখলে, বেশিরভাগ সময় সে সাহায্যপ্রার্থীর সমস্যা সমাধান করে ফেলে, সম্ভবত?\nনিয়ন্ত্রণ প্রতিরোধ অপসারিত অবস্থায় সে নিজের ক্ষমতা নিয়ন্ত্রণ করতে পারে না, যার ফলে গবেষণাগারে প্রায়ই বিস্ফোরণ ঘটে।\nপ্রয়োজনীয় শিক্ষার অভাবে, মাঝে মাঝে মস্‌কে অনেকক্ষণ ধরে হাত-পা নেড়ে ইশারা করতে হয় যাতে কথোপকথনকারী তার কথা বুঝতে পারে। অবশ্য, মস্‌-এর পক্ষে অন্যদের ইশারা বোঝার জন্য এত কষ্ট করার দরকার হয় না, তার অসাধারণ অন্তর্দৃষ্টি এই সমস্যা সহজেই সমাধান করে দেয়।\nনোটিরা এবং রহস্যরক্ষকের সাথে তার অত্যন্ত ঘনিষ্ঠ সম্পর্ক। তার মতে, তিন জনের মধ্যে একসাথে অভিযানে যাওয়ার একটি প্রতিশ্রুতি ছিল, তবে নোটিরার এ বিষয়ে কোনো স্মৃতি নেই, আর রহস্যরক্ষক সেই অভিজ্ঞতা সম্পর্কে কিছুই বলতে রাজি নয়।\nমাঝে মাঝে মস্‌-এর পাশে মিসাগ টুপি পরা একটি সামুদ্রিক ভোঁদড় দেখা যায়, মস্ তাকে 「ছোট কয়লাবল দ্বিতীয়」 বলে ডাকে। যখনই এমন হয়, কিছু জমা দেওয়ার কথা থাকা হোমওয়ার্ক রহস্যজনকভাবে উধাও হয়ে যায়।"
  },
