  CollectionHall_129810_Desc = {
    Text = "একটি চক্রে, যা কখনও লিপিবদ্ধ হয় না, রামোনা: টাইমওর্ন ঘড়িঘরের পেছনের ফুলবাগানের উপর দিয়ে পা বাড়ায়।\nচোখের কোণ দিয়ে সে গোলাপ উদ্যানের আভাস পায়, যেখানে গুচ্ছ গুচ্ছ উজ্জ্বল ফুল উন্মত্ত উগ্রতায় ফুঁটে আছে।\nদুর্লভ এক মুহূর্তের বিরতির পর, সে সব অপ্রয়োজনীয় ভাবনা ঝেড়ে ফেলে, যাত্রা অব্যাহত রাখে চূড়ান্ত যুদ্ধক্ষেত্রের দিকে।\nকাদা ছিটকে পড়ে রক্তিম পাপড়ির উপর, আর অন্ধকার D-পঙ্ক তা দ্রুত গিলে নেয়, বাতাসে ভেসে থাকে শুধু এক গর্বিত ছায়া।"
