  CollectionHall_130220_Desc = {
    Text = "ড্যান্ডেলিয়ন, পাখির চেয়েও ছোট, মৃদু বাতাসের চেয়েও হালকা।\n\nযখন ড্যান্ডেলিয়ন প্রথম প্রান্তর পার হলো, সে সেখানকার ছড়িয়ে-ছিটিয়ে থাকা টাম্বলউইডদের জিজ্ঞেস করল: তোমরা কীভাবে বংশবিস্তার করো?\nটাম্বলউইড বলল: 「আমরা আমাদের বীজ চারদিকে ভাসিয়ে দিই, যতক্ষণ না শেকড় গাড়ার মতো মাটি খুঁজে পাই।」\nভবঘুরে পথিকের কোনো ঘর নেই, ড্যান্ডেলিয়ন এমন দীর্ঘশ্বাস ফেলে আরেকটি বাতাসের ঢেউয়ে চেপে উড়ে গেল।\n\nযখন ড্যান্ডেলিয়ন দ্বিতীয় মরুভূমি পার হলো, সে সেখানে বিক্ষিপ্তভাবে ছড়িয়ে থাকা ক্যাকটাসদের জিজ্ঞেস করল: তোমরা কীভাবে টিকে থাকো?\nক্যাকটাস বলল: 「আমরা আমাদের শেকড় মাটির গভীরে প্রোথিত করি, দুর্লভ জলের উৎস থেকে রস টেনে নিই।」\nকঠোর পরিবেশেও দৃঢ়ভাবে বেঁচে থাকা——ড্যান্ডেলিয়ন এমন ভাবনায় মগ্ন হয়ে সেখান থেকে চলে গেল।\n\nকিছুক্ষণ পর, ড্যান্ডেলিয়ন শহরের আকাশ দিয়ে উড়ে গেল।\nঅন্ধকার রাতে ভেসে ওঠা শহরজুড়ে আলোর ঝলকানি, মানুষের জীবনযাত্রার চিহ্ন।\nদীর্ঘ যাত্রার শেষে, ড্যান্ডেলিয়নের বীজ অবশেষে সেই মাটিতে ঝরে পড়তে চলেছে।"
