  CollectionHall_130221_Desc = {
    Text = "আরাকনে জানত, সে এমন একটি কাজ করছে যা ব্যর্থ হতে বাধ্য।\nসে আলতো করে চরকা ঘোরাত, দিনের পর দিন মানুষের সুখ-দুঃখ, সাম্রাজ্যের উত্থান-পতন, স্ফুলিঙ্গের মতো কবিতা ও ভালোবাসাকে সেই কালজয়ী বিশাল জালে বুনে চলত।\nসে অসাধারণভাবে করত এই কাজ—নিখুঁত, সংযত, কোমল। যা 'ভুল' তা বর্জন করত, যা 'সঠিক' তা বেছে নিত।\nপ্রজন্মের পর প্রজন্ম নবজন্মের হাসি ফুটিয়ে তুলত, অগণিত সভ্যতা ছাইয়ের মধ্যে নতুন ইতিহাস রচনা করত। কিন্তু বুননের আনন্দ, বুননের ক্লান্তি, সমস্ত কোমল অনুভূতি—সবই অনন্ত দাসত্বের ক্ষয়ে নীরবে ঝরে গিয়েছিল। সে নিজ হাতে দুর্বলতা ছেদন করেছিল, শুধু জাগ্রত ইচ্ছাশক্তি রেখেছিল, শুধু এটুকু নিশ্চিত করতে যে প্রতিটি সিদ্ধান্ত দায়িত্ববোধ থেকে আসে, দুর্বলতা থেকে নয়।\nকিন্তু গভীরতম বিয়োগান্তকতা দাসত্ব নিজে নয়, বরং সে স্পষ্টই জানত—সে যতই মেরামত করুক, যতই বুনুক, পৃথিবী শেষ পর্যন্ত সেই নীরব শূন্যতার দিকেই এগিয়ে যাবে। সভ্যতা ভঙ্গুর বালির দুর্গের মতো, জোয়ার একদিন আসবেই। তার প্রচেষ্টা ছিল দর্শকহীন এক মঞ্চায়ন, প্রতিধ্বনিহীন এক চিরন্তন প্রহরা।\n'নিয়তি আমাদের চিরকালের একাকীত্বে দণ্ডিত করেছে, কেন মেনে নেব এই নিষ্ঠুর শাস্তি?'\n'ছিঁড়ে ফেলো, ধ্বংস করো... তাহলেই তুমি এই দাসত্ব থেকে মুক্তি পাবে...'\nসে চোখ নামিয়ে সেই অতিরিক্ত ভাবনাগুলো আলতো করে কেটে ফেলল, আর একঘেয়ে অথচ একাগ্রভাবে বুনে চলল, ধরে রাখল, কাঁদতে থাকল, সহ্য করে গেল...\nসমস্ত অর্থহীন সংগ্রাম, সমস্ত সমাধানহীন নিয়তি আগে থেকেই এই জালে বোনা ছিল।\nআর জালের কেন্দ্রে, সে দেখতে পেল নিজেকে।"
  },
