  CollectionHall_131664_Desc = {
    Text = "ভাবি তো... আজ তোমার জন্য কেমন গল্প বুনি?\nআহ, পেয়ে গেছি। ছোট প্রভু ও ভদ্রমহিলাদের জন্য এক কাহিনি...\n<Italic:\"রাত বারোটার ঘন্টাধ্বনিতে পাপের কথা কোরো না বর্ণন,\nনা হলে তোমার অন্যায়ের আত্মারা শুরু করবে আরোহন।\">"
