  CollectionHall_131668_Desc = {
    Text = "পুরোনো আর অদ্ভুত, অদ্ভুত আর পুরোনো! মৃত স্ত্রী হেঁটে আসে মধ্যরাতের ছাঁচের কোলো।\nওই বিশ্বাসঘাতক লম্পট, এত দুঃসাহসী, এত নিষ্ঠুর—তাকে আমরা ফেলে দেব ফুটন্ত কড়াইয়ের ভেতর।\nআমাদের নিরাকার দেবকন্যা তার আর্তনাদ শোনেন, তিনি ছিঁড়ে নেবেন তার মুখের চামড়া, তিনি তাকে সম্পূর্ণ নিষ্কাশন করবেন!\nআমরা চিরে খুলব তার বক্ষ, তুলে নেব তার অস্থি, আমাদের ভদ্রমহিলার সিংহাসনের সামনে তা বিছিয়ে দেব অর্ঘ্যের মতো।"
