  CollectionHall_132222_Desc = {
    Text = "যদি সত্যিই ইচ্ছা পূরণ হতো, তাহলে পন্টোস চাইত বিদায় আসার আগে একটু অন্তত জানান দিক।\nতার বাবা-মা নিঃশব্দে অদৃশ্য হয়ে গিয়েছিল, একটি শান্ত বিকেলে, বোন লেইসা একটি রিকশা ভাড়া করেছিল, তারপর এসেছিল দীর্ঘ, সেই সময় তার অচেনা লোহার দানব, ডিজেলের গন্ধ আর গর্জনের মধ্যে সে পৌঁছেছিল সেই সমুদ্রতীরের ছোট্ট শহরে।\nবাবা-মা কোথায় গেছে সে বিষয়ে লেইসা একটি কথাও বলেনি, তীব্র ঝগড়ার পর সে ছুটে গিয়েছিল লবণাক্ত গন্ধে ভরা বন্দরে।\nঅতিরিক্ত চওড়া চোখের দূরত্বের সামুদ্রিক মানুষেরা অদ্ভুত আকৃতির মাছ বিক্রি করছিল, যেগুলো মানুষের পক্ষে পৌঁছানো অসম্ভব এমন গভীর অতল থেকে আনা।\n「হ্যালো, দূরে থাকো, এই মাছগুলো হয়তো যে জিনিসগুলো এদের ধরেছে সেগুলোর মতোই অভিশাপে আক্রান্ত।」\nপথচারী গলা নামিয়ে বলল, কেউ চায়নি এই নতুন আসা সুদর্শন যুবক ঝামেলায় জড়িয়ে পড়ুক।\nসে অভ্যাসবশত প্রতিপক্ষের দিকে হেসেছিল, কিন্তু দৃষ্টি অজান্তেই পড়ল সেই অন্ধকার পচা টোপটির উপর, এর বড় হাঁ-করা মুখ ভরা ধারালো দাঁতে, কুৎসিত、বিকৃতি、উদ্ধত, কল্পনার কোনো কণ্ঠস্বর এই মৃত বস্তুর সারাজীবনের কথা বলছিল।\nঅন্ধকার、আলোহীন সমুদ্রের তলদেশে, এটি প্রলোভন দিত、লুণ্ঠন করত、সব উপায় ব্যবহার করত, এর শরীর ছিল একটি দৃঢ় বন্দিখাঁচা, যা আটকে রাখত এর সন্তান、প্রিয়জন、শত্রু、এবং শিকারকে।\nএর জীবনের সুন্দর জিনিসগুলো ক্ষণস্থায়ী হওয়ার কথা ছিল, কিন্তু এটি তাদের সবাইকে ধরে রেখেছিল, তারা এর শরীরকে বাহন করে, ঘনিষ্ঠভাবে একে অপরের উপর নির্ভর করে, চিরকাল বিচ্ছেদহীন।\nপন্টোস হঠাৎ মাথা ঝাঁকাল, আতঙ্কিত হয়ে কানের কাছে তীক্ষ্ণ গুঞ্জনের মধ্যে চারদিকে তাকাল।\nশব্দ জোয়ারের মতো মিলিয়ে গেল, সে সবকিছুকে একটি ক্ষণিক বিভ্রম মনে করল, মনে মনে নিজের স্নায়বিকতা নিয়ে ঠাট্টা করল।\nতারপর কোনো কিছু টের না পেয়েই নির্ধারিত নিয়তির দিকে ডুবে গেল।"
  },
  CollectionHall_132222_Title = {
    Text = "জীবন্ত বন্দিখাঁচা"
  },
  CollectionHall_133709_Desc = {
    Text = "সকালের অশ্বারোহণে কাউন্টির ভদ্রলোকদের সাথে পাশাপাশি ঘোড়া চালিয়ে সংস্কার বিলের অবস্থান জানতে হয়; কোল্ড বুফেতে বিভিন্ন পরিবারের মহিলাদের সাথে শোভন প্রশংসা বিনিময় করতে হয়, দীর্ঘ টেবিলের নৈশভোজে রুপোর মোমদানির আলো-ছায়ায় সেই দীর্ঘ ও ভণ্ডামিপূর্ণ খাবার-পূর্ব প্রার্থনা শুনতে হয়, আর অপেরা শেষে বক্সের করিডোরে অন্তহীন সামাজিক শিষ্টাচার সামলাতে হয়।\n\n「একমাত্র পেছনের বাগানের লনে বিকেলের চা, সেটাই সত্যিকার অর্থে আমার নিজের সময়।」\n「এই প্রথমবার আমি বিকেলের চায়ে কোনো অতিথিকে আমন্ত্রণ জানাচ্ছি, আলোচনার বিষয় বেছে নেওয়ার অধিকার আমি তোমার হাতে তুলে দিচ্ছি।」\n\nসোরেল সদ্য ঢালা লাল চায়ের কাপ তুলে নিল।\n「তুমি কি জানতে চাও কোঁৎ দ্য ক্রেমে সর্বশেষ জমা দেওয়া সংসদ সংস্কার বিলে কী অবস্থান নিয়েছেন? নাকি বোমোনা পরিবার দুই দলের মধ্যে কীভাবে সূক্ষ্মভাবে বাজি ধরছে? অথবা শুধুই কোনো ভাইকাউন্টের মেয়ের গোপন বিষয়ে আগ্রহী?」\n「কিছুই লাগবে না? তুমি শুধু আমার টেবিলের গোলাপি মিষ্টির স্বাদ জানতে চাও?」\nসে হালকা একটু চুমুক দিল, দূরে তাকিয়ে থাকা দৃষ্টি ফিরে এসে তোমার ওপর স্থির হলো।\n「তাহলে ভালো করে স্বাদ নাও।」\n「কিছু স্বাদ আছে, যা সত্যিই নিজে হাতে করলে তবেই অনুভব করা যায়।」\n「তাই না, আমার শ্রদ্ধেয়——সেই মহামান্য?」\n\nমিসাগার স্কুল ইউনিফর্ম পরা আগন্তুকের কলার আর হাতার কাফ থেকে কালো কুয়াশা উথলে উঠছিল, কুয়াশা দ্রুত গড়িয়ে ঘন কালো বিশৃঙ্খলায় পরিণত হলো।\n「হিহিহি, তুমি কি সত্যিই মনে করো, নিয়তি থেকে পালাতে পারবে?」\n「রোদ চমৎকার, আমি আগে আমার দুর্লভ অবসর সময়টুকু উপভোগ করতে চাই। এখনকার সবচেয়ে জনপ্রিয় লাল চা আর স্পঞ্জ কেক চাখতে চাইলে, যথেচ্ছ। অন্য বিষয়, দুপুরের বিশ্রামের সময় শেষ হলে তারপর আসুন।」"
  },
