  CollectionHall_133710_Desc = {
    Text = "মিথাগের একজন অনুকরণীয় ছাত্রী হিসেবে, রামোনা সফলভাবে বিচক্ষণতা ও যুক্তিকে তার কর্মের পরম নীতি হিসেবে গ্রহণ করেছে, সর্বদা শান্ত থেকেছে, সর্বদা হাস্যোজ্জ্বল থেকেছে, সর্বদা অতুলনীয়ভাবে নির্ভরযোগ্য থেকেছে।\nকিন্তু মাঝে মাঝে, এমন রামোনাও গভীর চিন্তায় ডুবে যায়, যখন সে বিশ্বের চরম আতঙ্ক, অথবা চরম জাঁকজমকের মুখোমুখি হয়——\nসীমাহীন, দৃষ্টিসীমা জুড়ে ছড়িয়ে থাকা গোলাপি রঙের দিকে তাকিয়ে, রামোনা নীরবে স্তব্ধ হয়ে যায়।\nসে যতদূর জানে, তিন সপ্তাহের বেশি সময় লাগে না, চেরি ফুল ফোটা থেকে ঝরে যেতে, তাই এই ভারী হয়ে ডালে ডালে ঝুলে থাকা ফুলগুলো, বিস্তৃত ও ঘন পাতাগুলো, শীঘ্রই ম্লান হয়ে যাবে, জীর্ণতা ও শূন্যতায় ডুবে যাবে।\nআর মানুষের প্রত্যাশিত জীবনকাল, তিন সপ্তাহের চেয়ে অনেক বেশি, তিন বছরের চেয়ে অনেক বেশি, তিরিশ বছরের চেয়েও অনেক বেশি, তবুও এই চেরি গাছগুলোর মতোই, মাত্র একবারই আসে।\nমানুষের সবচেয়ে বড় মায়াভ্রম হলো এই বিশ্বাস যে সে চিরকাল বেঁচে থাকবে।\nরামোনা এটা বোঝে।\nফুল ফোটা ও ঝরে যাওয়া, প্রকৃতির একটি অতি সাধারণ নিয়ম, আর মানুষের জন্ম-মৃত্যুও, মূলত প্রকৃতির একটি ঘটনা মাত্র।\nরামোনা এটাও বোঝে।\nকিন্তু মানুষ হয়ে জন্মালে, নিজের অস্তিত্বকে অর্থবহ করতে চাওয়াটা স্বাভাবিক, প্রতিটি নবজন্ম এই কারণেই মিথাগের দ্বারে পা রাখে।\nতারা ডিজলিউশনের বিরুদ্ধে লড়াইয়ের অগ্রদূত, মানবজাতির ভবিষ্যৎ রক্ষার একটি গুরুত্বপূর্ণ প্রতিরক্ষা সারি।\nতাদের জীবন কেবল একটি নিরপেক্ষ প্রাকৃতিক ঘটনা নয়, বিলুপ্তি অবধারিত হলেও, তারা সত্যিই এই পৃথিবীর কক্ষপথ বদলে দিচ্ছে।\nআর এই পথে, তারা কাঁধে কাঁধ মিলিয়ে লড়াই করে, ঝড়-বৃষ্টিতে একসাথে এগিয়ে যায়।\nযেমন একটি গাছের একটি ফুল, আরেকটি ফুলের পাশে মিশে থাকে, একসাথে কুঁড়ি মেলে, একসাথে দোলে ঝরে পড়ে, একসাথে সম্পূর্ণ পুষ্প হয় ও শুকিয়ে যায়।\nএখন, ফিরে যাওয়ার সময় হয়েছে।\nসেই ফুল, যার উপর সে ভরসা করতে পারে, এবং যে তার ভরসার যোগ্য, এখনও তার জন্য অপেক্ষা করছে।"
