  CollectionHall_134293_Desc = {
    Text = "<Title:পরিচিতি>\nভাগ্য থিয়েটারের মালিক, নাট্যকার, অভিনেত্রী, ভাগ্যের চিরন্তন বুনকর এবং চিরন্তন বন্দী……\nজন্মের পর থেকেই আরাকনি ভাগ্যের সুতো দেখার ক্ষমতা নিয়ে জন্মেছিলেন। 「মোইরাই」 নামের সেই চরকা ব্যবহার করে, তিনি প্রতিটি মুহূর্তে বিশ্বের জন্য ভাগ্য বুনে চলেছেন, ভাগ্যের সেই ভঙ্গুর ভারসাম্য রক্ষা করে চলেছেন। এর জন্য, তিনি নিজের মধ্যকার সমস্ত সুন্দর ও দুর্বল দিকগুলোকে নির্বাসিত করেছেন, সকল ভাগ্যের জন্য সবচেয়ে সঠিক সিদ্ধান্ত নিয়েছেন, এবং একাই সমস্ত ভাগ্যের পাপের বোঝা বহন করেছেন।\nতিনি অনেক আগেই জানতেন, ভাগ্যের জালের শেষ প্রান্তে ধ্বংস অনিবার্য। তবুও তিনি অনাদিকাল ধরে অবিরাম বুনে চলেছেন, তাঁর গভীরভাবে ভালোবাসা সবকিছুকে ধীরে ধীরে সেই সর্বগ্রাসী বিলুপ্তির সমাপ্তিতে তলিয়ে যেতে দেখেছেন।\nতিনি বুনে চলেছেন, অপেক্ষা করেছেন, সেই সুতোর জন্য অপেক্ষা করেছেন যা তিনি কখনো পূর্বদর্শন করেননি — যা ভাগ্যের জালকে অতল গহ্বর থেকে উদ্ধার করবে।"
