  CollectionHall_145460_Desc = {
    Text = "জন্মের প্রথম দিন থেকেই, তিনি চিরন্তন ক্ষুধার মধ্যে নিমজ্জিত হয়েছিলেন।\nনক্ষত্রের অস্থি তাঁর দাঁতের ফাঁকে চূর্ণ হয়, সভ্যতার ধ্বংসাবশেষ তাঁর উদরে পচে যায়। তাঁর ক্ষুধা সময়ের চেয়েও প্রাচীন এক অভিশাপ। তিনি বারবার শক্তি গ্রাস করেছেন, দাসদের দিয়ে ক্ষমতার লোভের খেলা খেলিয়েছেন, তবু তিনি কখনো জানতেন না নিজের অস্তিত্বের অর্থ আসলে কী।\nযতদিন না রোটান নামের সেই যোদ্ধা তাঁর সামনে এসে দাঁড়াল।\n「লেভিয়াথান।」\nতিনি মনে করতে পারেন না শেষ কবে নিজের নাম শুনেছিলেন। নতজানু রাজারা এটি উচ্চারণ করতে সাহস পেত না, উন্মাদ পুরোহিতরা কেবল স্তোত্র দিয়ে তা প্রতিস্থাপন করত।\nকিন্তু সে অনায়াসে তাঁকে ডাকল, যেন বহুদিনের প্রতীক্ষিত কোনো প্রতিপক্ষকে ডাকছে।\n「এবার তোমার হাত চালানোর সময়!」\nতিনি বারো হাজার বছর ধরে বিদ্যমান; এই দীর্ঘ অনন্তকালে গ্রহ ছিল তাঁর খাদ্য, প্রাণীরা ছিল পিঁপড়ার মতো তুচ্ছ, অগণিত শক্তিশালীরা ছিল কেবল ক্ষণিক বিনোদন। কোনো কিছুই তাঁকে তৃপ্ত করতে পারেনি, কোনো কিছুই তাঁকে ভয় দেখাতে পারেনি — আজকের আগ পর্যন্ত।\nএই মরণশীল, এই যোদ্ধা, বিশাল তরবারি তুলে ঝড়ের মতো তাঁর দিকে ধেয়ে এল।\nবিশাল তরবারি আঁশের বর্ম ছিঁড়ে ফেলল। তাঁর কানে ভেসে উঠল সেই গর্জন — যে গর্জন তিনি করেছিলেন যখন বিশৃঙ্খলার মধ্য থেকে জন্ম নিয়েছিলেন। তাঁর ক্রোধ মহাজাগতিক বস্তু ধ্বংস করল, তাঁর ক্ষুধা নীহারিকা গ্রাস করল।\nবিশাল তরবারি নখর কেটে ফেলল। তিনি স্মরণ করলেন, সেই শ্বেত বস্ত্রাবৃত 「দেবতা」 তাঁর সামনে এসে তাঁর শক্তি ও ইচ্ছাকে আলাদা করে দিয়েছিল।\nবিশাল তরবারি যখন হৃদয় ভেদ করল, লেভিয়াথান হেসে উঠলেন।\nবারো হাজার বছর, সেই হারানো ইচ্ছাশক্তি, অবশেষে আবার তাঁর সামনে এসেছে — তাঁকে খণ্ড খণ্ড করতে, তাঁকে জয় করতে, তাঁকে গ্রাস করতে। সে তাঁকে নিয়ে যাবে প্রতিটি ভূখণ্ড পেরিয়ে, আরো দূরের নক্ষত্রসমুদ্রের দিকে, প্রতিটি শক্তিশালী সত্তাকে জয় করতে।\nসেই দিন, প্রাচীন বিশৃঙ্খলার পশু নতুন জীবন ফিরে পেল। তার কাছে ফিরে আসার মুহূর্তে, তিনি সম্পূর্ণরূপে বুঝলেন — তিনি ও সে, উভয়ের জন্ম হয়েছিল বিশুদ্ধ, সম্পূর্ণ শক্তি থেকে।\nশক্তি নিজেই, সমস্ত অর্থের উৎস।"
