  CollectionHall_146400_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রাচীন দেবতারা সেই তারাকাশের তিমির চিরন্তন ক্রোধ প্রশমিত করতে পারেননি, তাই তাঁরা কেবল তাঁর আত্মা ও কারোকে বিচ্ছেদ করতে বাধ্য হলেন। তাঁর ইচ্ছাশক্তি বিরান ভূমিতে পতিত হয়ে ক্ষয়·রোটান নামের এক যোদ্ধায় রূপান্তরিত হলো।\nসে স্বভাবতই যুদ্ধপ্রিয়, চরম শক্তির সাধনাকেই তার একমাত্র সহজাত প্রবৃত্তি ও গৌরব মনে করে। এই লক্ষ্যে সে তারাকাশের তিমির বাছাই প্রতিযোগিতায় প্রবেশ করে, তার সাথে চুক্তি করে, এবং যখন শক্তি শীর্ষে পৌঁছায়, তখন বিশাল তরবারি দিয়ে নিজের আধিপত্যকে হত্যা করে সেই তারা-গ্রাসকারী দানবের ক্ষমতা নিজের মধ্যে আত্মস্থ করে নেয়।\nতীক্ষ্ণ তিমির হাড় কারোকে ভেদ করে, অন্ধকার অস্থি-বর্ম খোলসকে ঢেকে ফেলে, আর সেই তারাকাশ ধারণকারী দুই চোখে শুধু শত্রুর প্রতি শীতল উদাসীন দৃষ্টি অবশিষ্ট থাকে।\nসে ধ্বংসে আনন্দ পায় না, অর্থহীন হত্যাকেও তুচ্ছ মনে করে। সে যা চায় তা হলো শুধু আরও উল্লাসজনক শত্রু, শুধু আরও প্রবল শক্তি।\nসেই সবচেয়ে বিশুদ্ধ যোদ্ধা শক্তিশালী প্রতিপক্ষের ছায়া অনুসরণ করে নক্ষত্র-সমুদ্রের প্রতিটি কোণ পদদলিত করে চলে, যতক্ষণ না সমস্ত শক্তিশালীরা তরবারির নিচে পড়ে, যতক্ষণ না সমস্ত পথ শেষ প্রান্তে পৌঁছায়।"
