  CollectionHall_149045_Desc = {
    Text = "「ফুলের মালাটা পরে নাও, এটাই তোমার পুরস্কার অনুষ্ঠান, প্রিয় ছোট্ট নাইট।」\nযখন ডেইজি ফুলে মাঠ ভরে যেত, তখন অলস সৈনিকরা প্রহরার অজুহাতে সেই কিশোরকে নিয়ে এখানে ঘুরে বেড়াত।\nআকুইটেন ডাচিতে সবচেয়ে পরিচিত ফুল দিয়ে বোনা গহনা, আলতো করে সোনালি চুলের উপর রাখা হলো।\n「মহোদয়, হয়তো… আমাদের প্রশিক্ষণে যাওয়া উচিত?」\nকিশোর এই কথা বলতে বলতেও বাধ্য ছেলের মতো সাদা ফুলের মালাটা সোজা করে পরে নিল।\nএই ছোট্ট উদ্ভিদ, সর্বদা আলোয় স্নাত, কিশোরের রাজ্যে আশার প্রতীক।\nআবার চোখ খুলতেই সেই উজ্জ্বল দৃশ্যগুলো আর ছিল না।\nযুদ্ধের ঘোড়া হ্রেষা দিচ্ছে, শত্রুরা তাচ্ছিল্যের সাথে ঝাঁপিয়ে পড়ছে, হাজারো সৈন্যের মাঝে সে একা।\nতারপর, কানফাটানো কোলাহল হঠাৎ থেমে গেল——\nকালো জোয়ার তার আত্মায় ঢেলে পড়ল।\nতার সাথে ভেসে এলো বর্শা মাংস ভেদ করার ছেঁড়া শব্দ, রক্তের প্রবাহের শব্দ, শত্রুর আর্তনাদ।\nসেই মুখগুলোর তাচ্ছিল্য মিলিয়ে গেল, তার জায়গায় এলো সর্বগ্রাসী ভয় আর পশ্চাদপসরণ।\nআর কিশোর যন্ত্রের মতো হাত তুলল, বিদ্ধ করল, টেনে বের করল, আবার তুলল।\nশেষ সৈনিকটি পড়ে যাওয়া পর্যন্ত।\nধুলোর কুয়াশায় অগণিত মুখ ঢেকে গেল, বিজয়ী ও পরাজিতের ধ্বংসাবশেষ মাটিতে স্তূপ হয়ে পড়ল, আর কোনো পার্থক্য রইল না।\nছায়া তার পিঠে জড়িয়ে ধরে ঠাট্টা করে বলল: 「চালিয়ে যাও। তোমার বর্শা নামাও, আরও একবার।」\n「রক্ষক আর ধ্বংসকারীর মধ্যে, সবসময়ই মাত্র একটি সরু রেখার ব্যবধান। এখন তুমি তোমার পছন্দ করে ফেলেছ।」\nঅন্ধকার আকাশ ঢেকে দিল, রক্ত মাটি ভিজিয়ে দিল।\nসে দূরের মাঠের দিকে তাকাল——মাত্র একটি রাতেই, সেখান থেকে চিরতরে হারিয়ে গেল আগের সেই রঙ।\nবাতাস কিশোরের পোশাকের কোণ উড়িয়ে দিল, আর ভেসে গেল সেই ভাগ্যক্রমে টিকে থাকা ঘাসের উপর দিয়ে।\nনিঃশব্দ রাতের মধ্যে, এমন এক কোণে যা শয়তানও জানে না, একটুকরো অস্পষ্ট বিশুদ্ধ সাদা তখনও তার চোখের গভীরে রয়ে গেল।\nএটি ছিল এই রাজ্যের শেষ ডেইজি ফুল, যেখানে কেউ মনোযোগ দেয় না সেখানে নীরবে বেড়ে উঠছিল।\nলাল রঙে রঞ্জিত হলেও, ডাঁটা বাঁকা হলেও, তবু পড়ে যায়নি।"
  },
