  CollectionHall_48635_Desc = {
    Text = "<Title:পরিচিতি>\nমিসা অ্যাকাডেমির ভারপ্রাপ্ত ডিন।\nক্রাউলি ম্যাকিননের অধীনে শিক্ষালাভ করেছেন এবং হার্বার্টের সরাসরি কনিষ্ঠ সহপাঠী।\nহার্বার্ট কর্তৃক গুরুহত্যার প্রত্যক্ষদর্শীদের একজন; গুরুর মৃত্যুর পর থেকে তিনি অ্যাকাডেমির যাবতীয় বিষয় পরিচালনা করে আসছেন।\nচরম দক্ষতাবাদী, কখনো দেরি করেন না; চুল ছোট রাখেন কারণ এতে আঁচড়ানোর সময় বাঁচে।\nযুদ্ধের কারণে নিজের মাতৃভূমি এলক থেকে পালিয়ে অবৈধভাবে লেওতে এসেছেন।\nডান হাতের তর্জনী স্বাভাবিকভাবে বাঁকাতে পারেন না; শোনা যায় এটি বন্দিশিবিরে নির্মম নির্যাতনের প্রমাণ।"
  },
