  CollectionHall_48636_Desc = {
    Text = "<Title:পরিচিতি>\nতিনজন প্রতিষ্ঠাতার একজন, ওয়ার্ড ফিলিপস এবং ক্লার্কশের সাথে মিলে মিসাগ বিশ্ববিদ্যালয়ের পূর্বসূরি — মিসাগ একাডেমি প্রতিষ্ঠা করেছিলেন।\nতিনি প্রথম 「জাগ্রত সত্তা」 এবং জাগ্রত সত্তা প্রযুক্তি প্রদানকারী অস্তিত্ব।\nদীর্ঘকাল ধরে ব্ল্যাক পুল পাহারা দিয়ে আসছেন, যারা তাঁর মুখ দেখেছে তাদের সংখ্যা হাতে গোনা যায়, তিনি মিসাগ বিশ্ববিদ্যালয়ের সর্বোচ্চ গোপনীয়তাগুলোর একটি।\n「শ্‌... তোমার @2-কে পরীক্ষা করার চেষ্টা করো না।」"
