  CollectionHall_48950_Desc = {
    Text = "মারণ মাধুর্য ভরে উঠেছে বাতাস। সাবধান—মৃত্যুর আঠালো আলিঙ্গন তোমার গলায় জড়িয়ে আসছে।"
  },
  CollectionHall_48950_Title = {
    Text = "মিষ্টি স্লাগ"
  },
  CollectionHall_48968_Desc = {
    Text = "মিথ্যাগ ক্যাম্পাসে লর্ড ডেক্সটারের দণ্ড নিয়ে নানা গুজব ঘুরে বেড়ায়।\n\n\"নিশ্চয়ই প্রভুর দণ্ডে তার হাসির মতোই বহু গোপন রহস্য লুকিয়ে আছে।\nএতে কি এমন রূপা বসানো, যা জাগ্রতদের শক্তি বশে আনতে পারে, নাকি ভেতরে গোপনে গানপাউডার ভরা, যা মুহূর্তে আগ্নেয়াস্ত্রে রূপ নিতে প্রস্তুত?\nএসো, লর্ড ডেক্সটার নিজেই আমাদের তা জানিয়ে দিন!\"\n\nদ্রুত উদ্বোধনী বক্তব্য লিখে নিয়ে, হান্না ক্যামেরা তাক করল লর্ড ডেক্সটারের দিকে, অধীর আগ্রহে অপেক্ষা করতে লাগল দণ্ডের ধারণকারীর মুখনিঃসৃত কথার জন্য।\n\n\"এটা? বিশেষ কিছু নয়, কেবল ডেক্সটার পরিবারের দৈনন্দিন ব্যবহার্য দণ্ড, বিশেষভাবে বানানো।\nআমারটায় যে রত্ন বসানো, তা আমার ভাইয়েরটার চেয়েও কম দামী।\nযদি বলতেই হয়, কীভাবে এটা আলাদা...\nএতে একবার আমার বাবা-মা আর ভাইয়ের রক্ত লেগেছিল; ওটা কি গুণের মধ্যে পড়ে?\""
  },
  CollectionHall_48968_Title = {
    Text = "অভিজাতের দণ্ড"
  },
  CollectionHall_48969_Desc = {
    Text = "লন্ডিনিয়ামের আন্ডারগ্রাউন্ড জগতে একটি গল্প ঘুরে বেড়ায়।\n\nব্যস্ত জেটিঘাটে, নির্জন গলিতে, আর কোলাহলমুখর মদের আসরে...\nতুমি কখন, কোথায় সেই মেয়েটিকে পাবে, তা কখনোই জানো না— হাতে ক্যামেরা, চোখে চশমা, গায়ে ইউনিফর্ম। কিন্তু একবার তাকে পেয়ে গেলে, তুমি কিনতে পারো যেকোনো তথ্য, আর তার একমাত্র মূল্য—\n\nতোমারই জানা একটি গোপন কথা তাকে দিতে হবে।\n\nকেউ মদের দোকানে শোনা এক মাতাল সত্যকে বিনিময় করেছে প্রতিদ্বন্দ্বীর মরণঘাতী দুর্বলতার জন্য।\nকেউ নিজের দুর্বলতাকে বিনিময় করেছে প্রিয়জনের অজানা অতীতের বিনিময়ে।\nমেয়েটির কাছে অসংখ্য তথ্যের টুকরো জমা আছে, কিন্তু একটি তথ্য আছে, যা কোনো গোপন কথার বিনিময়েও কেনা যায় না।\n\n「আমার ব্যাপারে? দুঃখিত, সেটা বিক্রির জন্য নয়।」"
  },
  CollectionHall_48969_Title = {
    Text = "তথ্যই জীবন"
  },
  CollectionHall_48970_Desc = {
    Text = "মিথ্যাগে যে মানুষটিকে কখনোই উসকানো চলবে না, তিনি আর কেউ নন, মিস সিলভিয়া—ধরা যাক, ডল দ্বিতীয় স্থানে।\n\nমিথ্যাগের একমাত্র মনোবিজ্ঞানী হিসেবে, এই রহস্যময় নারী শুধু মিশনে ট্রমাগ্রস্ত অনুসন্ধান কর্মকর্তাদের সান্ত্বনা দেন না, জাগ্রতদের অশান্ত আবেগও শান্ত করেন। তিনি জাগ্রতদের ভয় পান না; বরং তাদের মানসিকভাবে মোকাবিলা করেন—কী ভয়ংকর এক সত্তা।\n\nকৌতূহলে তাড়িত হয়ে আর যথাযথ সম্মানবোধের অভাবে, কিছু নবীন ছাত্র গভীর রাতে গোপনে মিস সিলভিয়ার ক্লিনিকে ঢুকে পড়েছিল।\n\nতারপর, তারা জ্ঞান হারায়। পরদিন সকালে, তারা ক্যাম্পাস স্কোয়ারে জেগে ওঠে, মাথা ধুকপুক করছে, কিন্তু মনের স্বচ্ছতা আগে কখনো না-দেখা রকম।\n\nতাদের পকেট থেকে পড়ে যাওয়া একটি নোট কেউ তুলে নেয়:\n\n“যদি আপনার মনোরোগ সংক্রান্ত পরামর্শের প্রয়োজন হয়, অনুগ্রহ করে আগে থেকেই মিস এরিকার কাছে অ্যাপয়েন্টমেন্ট নিন—\nসিলভিয়া”"
  },
  CollectionHall_48970_Title = {
    Text = "মানস প্রাচীর"
  },
  CollectionHall_48971_Desc = {
    Text = "অভিজাত নারীটি করুণা ও ঘৃণার মিশ্র অনুভূতিতে রুমাল দিয়ে নাক ঢেকে, অনিচ্ছুক গয়নাগুলো তার দাসীর হাতে তুলে নিতে বলল।\nসে মনে মনে ভাবল:\nভালোই হয়েছে—দরিদ্রাশ্রমের বালকেরা অন্তত একবার মাংস খেতে পারবে।\n\nসব খাবার বালকদের সঙ্গে ভাগ করে নিয়ে, করিডরে অনাহারে মূর্ছা যাওয়ার পর সে বলল:\nআমি ভালো আছি। ডাক্তার ডেকো না; তার ফি দিয়ে কয়েকটা রুটিই কেনা যাবে।\n\nযখন দয়ালু চিত্রশিল্পীটি পরিচিত এক ডাক্তারকে নিয়ে এল এবং দীর্ঘমেয়াদি ব্যবস্থার প্রস্তাব দিল, সে ভাবল:\nআগে আমার ওপরই ওরা এটা প্রয়োগ করবে। আমি নিশ্চিত না হওয়া পর্যন্ত বালকদের ওপর ওদের কথিত চিকিৎসা প্রয়োগ করতে দেব না।\n\nসারা নিজের জন্য যেকোনো কষ্ট সহ্য করতে পারত।\nকিন্তু সে সহ্য করতে পারত না যে, তার প্রতিটি প্রচেষ্টার শেষ পরিণতি কেবলই ট্র্যাজেডি হয়ে দাঁড়ায়।"
  },
  CollectionHall_48971_Title = {
    Text = "সংকট বিন্দু"
  },
  CollectionHall_48972_Desc = {
    Text = "অন্ধকারে এক হাত অন্ধের মতো খোঁজে, তার প্রভুকে সন্ধান করে।\n\nসেই রক্তাক্ত রাতে, নিষ্ঠুরভাবে তা মালিকের দেহ থেকে ছিঁড়ে নেওয়া হয়েছিল।\nএখন অপরাধীটি তার চারপাশে প্রবাহিত হয়, অদ্ভুত এক গুঞ্জন ছড়িয়ে দেয়।\n\n\"ত্যাগ করো, আমাদের সঙ্গে চলো। মোমের ভাস্কর তোমাকে সম্পূর্ণ ভুলে যাবে।\"\n\nহাতটি অচঞ্চল থাকে, গর্বিত, সরু আঙুলগুলো কেবল নড়ে ওঠে।\n\n\"প্রভু আমাকে ভুলবেন না।\nআমি তার শিল্পীসুলভ অভিব্যক্তির একমাত্র মাধ্যম—\nতুমি বোঝো না, তার কাছে আমার মানে কী।\"\n\n\"যেমন কেউ প্রেমিকাকে ভুলে যেতে পারে, সময়কে ভুলে যেতে পারে, কিন্তু কখনো ভুলো না নিজেকে।\"\n\nঅন্ধকারে এক সহানুভূতিহীন হাসি প্রতিধ্বনি তোলে।\n\"বরং উল্টোটা, মানুষ সবার আগে নিজেকেই ভুলে যায়।\nকিন্তু তাতে ক্ষতি কী—\"\n\nসময় সব ব্যাখ্যা করবে, আর হাতটি শেষ পর্যন্ত শিখবে:\nভুলে যাওয়ার বাইরে কিছুই নয়।\nতারা শতাব্দীর পর শতাব্দী ধরে প্রবাহিত হয়েছে, মানুষের গল্পের উন্মোচন দেখেছে, যা পরদিনই বিস্মৃত হয়েছে।\nআর তারা এখনো বয়ে চলে।"
  },
  CollectionHall_48972_Title = {
    Text = "বিস্মৃতির হাত"
