  CollectionHall_48973_Desc = {
    Text = "ওয়ার্ড·ফিলিপস সাহেবের আশ্রয়ে আসার পর থেকে, অ্যালিস্টেয়ার তার সঙ্গে মিথ্যাগের অসংখ্য উচ্চপর্যায়ের বৈঠকে অংশ নিয়েছে।\n\n\nযদিও নাম উচ্চপর্যায়ের বৈঠক, আসলে সেগুলো অনেকটা মাসিক বিতর্ক প্রতিযোগিতার মতো:\n\nফিলিপস সাহেব নরম গলায় কথা বলেন, আলোচনাকে এগিয়ে নিয়ে যান;\n\nক্লার্কাস তীক্ষ্ণভাষী, অনমনীয়।\n\nতারা পালা করে পক্ষে বা বিপক্ষে দাঁড়ায়, মিথ্যাগের ভবিষ্যৎ নিয়ে, অথবা আগামী মাসে জাগরণ অধ্যয়ন বিভাগের সম্পদ বণ্টন নিয়ে অন্তহীন তর্কে লিপ্ত হয়।\n\nমিস টাওইল নীরব পর্যবেক্ষক, সহজে কখনো নিজের মতামত দেন না।\n\nঅ্যালিস্টেয়ার নিজে চেষ্টা করে নিরপেক্ষ স্কোরকিপার হতে, মাঝে মাঝে রেফারির ভূমিকাও নিতে হয় তাকে, এমনকি একবার ছোট কনফারেন্স টেবিলটিকে বিপর্যয় থেকে বাঁচাতে কিছু যুদ্ধকৌশলও ব্যবহার করতে হয়েছিল।\n\n\nএখন বৈঠকে বাকি আছে মাত্র দুই সদস্য: একজন কখনোই কালো পুকুর ছেড়ে যেতে পারে না, আর অন্যজন আর কখনোই ভূগর্ভ ছেড়ে যেতে পারে না, সেই সম্ভাব্য 「ভবিষ্যৎ」-এর অনুসন্ধানে।\n\nআর সেই টেবিলটির কথা—ওটা সেই ঘটনার পর থেকেই নিখোঁজ।"
