  CollectionHall_48974_Desc = {
    Text = "তাভি কালো জলাশয়ের তলদেশে ঘুমিয়ে আছে।\n\nসেখানে চিরকাল নিঃশব্দ ও আলোহীন, শুধু এক হতাশাজনক অন্ধকার বিরাজ করে।\nকোনো অতিথি কখনো এখানে আসেনি, কোনো শব্দ কখনো এখানে পৌঁছায়নি।\nএটি সেই স্থান যেখানে ধ্বংস পৌঁছাতে পারে না——\n\nকারণ বিপর্যয় ইতিমধ্যেই নেমে এসেছে।\n\nকালের শৃঙ্খলার অধিকর্তা হিসেবে, সে অসংখ্য মর্মান্তিক পরিণতি প্রত্যক্ষ করেছে।\nনিয়মের একজন সদস্য হিসেবে, সে রাত্রির আগমন ঠেকাতেও অক্ষম।\nযদি তাই হয়, তবে অস্তিত্বহীন স্থানে লুকিয়ে থাকা ছাড়া উপায় নেই, অস্তিত্বহীন রূপে সেই ব্যক্তির আগমনের অপেক্ষা করা যাকে বলা যায় 'চলক'।\n\nসেই ব্যক্তি অবশ্যই একদিন আসবে।"
