  CollectionHall_48987_Desc = {
    Text = "তার জীবনের প্রথম অর্ধেক ছিল বিশৃঙ্খল, অন্ধকার, রক্তমাখা।\n\nখাও। ঘুমাও। আবার খাও।\nতারপর একদিন সে চোখ মেলে সচেতনতা লাভ করল।\n\nবলা হয়, সে তার সব সহোদরকে গিলে খেয়েছে এবং একমাত্র জীবিত প্রত্যাবর্তনকারী হয়ে উঠেছে।\n\nবলা হয়, সে মহা-সর্প ও এক মানবের সন্তান।\n\nএকটি কালো, অভিশপ্ত কলার তার গলায় শক্ত করে বাঁধা।\nএটাই তাকে বাঁচিয়ে রাখে, তাকে নিয়ন্ত্রণ করে, এবং নিশ্চিত করে যে সে কখনোই গির্জার বিরুদ্ধে দাঁড়াতে না পারে।\n\nতার মনে অসংখ্য জিজ্ঞাসা, সে পৃথিবী সম্পর্কে কৌতূহলী; তবু জন্মের মুহূর্তেই তার সব অন্য সম্ভাবনা কেড়ে নেওয়া হয়েছে।\n\nসুন্দর, বিপজ্জনক।\nগোপনীয়, তবু জাঁকজমকপূর্ণ।\nসে এই সবই।\n\nদুঃখের বিষয়, এগুলো তার সত্তার কেবল উপরিতলটুকু আঁচড়ায়।\n\nএই বিবরণ শুনে আলবিনোর জন্য তোমার মনে যে সামান্য করুণা জাগবে, সেটাই তোমার সর্বনাশ ডেকে আনবে।"
