  CollectionHall_48988_Desc = {
    Text = "একজন ডাক্তারের কর্তব্য হলো আরোগ্য দান করা।\n\nকিন্তু এমন এক চিকিৎসা আছে, যেখানে দরকার সবচেয়ে ধারালো ছুরি: চামড়া চিরে ফেলা, পেশি ভেদ করা, বক্ষ খোলা।\nসেখানে পচন কেটে তুলে ফেলতে হয়, তারপর ভরসা রাখতে হয় দেহের উপর, যে সে নিজেই সেরে উঠবে।\n\nএটাকে তার পাপ হিসেবে ধরা উচিত নয়।\nতবু প্রতিটি অস্ত্রোপচারের পর, সে নিজেকে খুঁজে পায় মেয়েটিকে গল্প শোনাতে, যেন এর ক্ষতিপূরণ দিচ্ছে।\n\nসে ভালো গল্পকার ছিল না; তার কথা ছিল খণ্ডাংশে ভাঙা, অসংলগ্ন।\nতবু মেয়েটি মন দিয়ে শুনত।\n\nযেখানে তার হাত একদিন কেটেছিল, সেই মাংস যেন ওই কথাগুলো থেকেই শক্তি টেনে আনে, ধীরে ধীরে, একগুঁয়েভাবে নিজেকে জোড়া লাগাতে থাকে..."
  },
  CollectionHall_48988_Title = {
    Text = "বিচ্ছেদ ও ক্ষত"
  },
  CollectionHall_48989_Desc = {
    Text = "বিশাল দানবটি রাতের আঁধারে ওত পেতে থাকে।\n\nকেবিনের ভেতরে, এক মা সারাদিনের সংযম ভেঙে অবশেষে তার হারানো কন্যার জন্য হাহাকার করে ওঠে।\n\nপ্রতিটি মধ্যরাতে, তার শোক উথলে ওঠে, কাঁচা ও অনাবৃত।\n\nএটি শুরু হয় সলতে-পোড়া কান্না দিয়ে, তারপর রূপ নেয় হাহাকারে, তারপর উচ্চারিত হয় সেই নাম, যা আর কখনোই দানবটির নয়।\n\nতার কণ্ঠের যন্ত্রণাময় সুর বিদীর্ণ করে দানবটির হৃদয়—এক হৃদয়, যা এখনো সম্পূর্ণ মানবিক।\n\n<Italic:বাড়ি ফিরে আয়, লিসা।>\n<Italic:ওহ, আমার লিসা।>\n\nদানবটি নীরব থাকে।\n\nসে অন্ধকারে গুটিয়ে শুয়ে পড়ে এবং গভীর নিদ্রায় ডুবে যায়।\n\nএকদিন, সে ফিরে আসবে—「বাড়ি」 নামের সেই স্থানে।"
  },
  CollectionHall_48989_Title = {
    Text = "রাতের আড়ালে"
  },
  CollectionHall_48990_Desc = {
    Text = "কেউ জন্মগতভাবে দলনেতা নয়; অন্তত এল্টন ছিল না।\n\nদলনেতা হওয়ার আগে, সে ভেসে বেড়িয়েছে নৌবাহিনী আর বণিক জাহাজের ফাঁকে, একাধিকবার প্রায় জলদস্যু হয়ে উঠতে উঠতে।\n\nসৌভাগ্যবশত, শেষ পর্যন্ত সে থিতু হয় এক অনুসন্ধানী জাহাজে।\nজাহাজটি মেরু মহাদেশ ঘুরে বেড়াত, প্রতিটি অবতরণই ছিল এক নতুন অভিযান।\n\nতার কাজ ছিল দুর্বলদেহী বিজ্ঞানীদের সরঞ্জাম বয়ে নিয়ে যাওয়া।\nএ নিয়ে সে গর্বিত ছিল: তার কাঁধে তোলা জিনিসগুলোই হয়তো পৃথিবী বদলে দেওয়ার চাবি।\nআর সেই বিজ্ঞানীরাই হয়তো ইতিহাস নতুন করে লিখবে।\n\nএটাই এল্টন বিশ্বাস করত—যতক্ষণ না এক বরফঝড় তাদেরকে এক গুহায় আটকে ফেলে, আর যতক্ষণ না একদল উপাসক রাতের আঁধারে তাদের উপর ঝাঁপিয়ে পড়ে।"
  },
  CollectionHall_48990_Title = {
    Text = "অভিযাত্রীর ব্যাগ"
  },
  CollectionHall_48991_Desc = {
    Text = "সে সবসময়ই ছিল নীরব, পরিশ্রমী এক ছাত্র।\n\nসকাল 8টায়, যখন অন্য গবেষকরা মুখে গুঁজে রাখা পাউরুটি নিয়ে তাড়াহুড়ো করে ঢুকত, তখন সে ইতিমধ্যেই একটি ল্যাব রিপোর্ট শেষ করে ফেলত।\n\nসে থেকে যেত রাত বারোটা পর্যন্ত, যখন ল্যাব ভবনের শেষ আলোটিও নিভে যেত, তারপর ধীরে ধীরে গুছিয়ে বেরিয়ে পড়ত।\n\nসে আশেপাশের পথভোলা বিড়ালগুলোকে প্রতিদিন খাওয়াত।\n\nপরে, সেই পথভোলা বিড়ালগুলো হারিয়ে গেল—কেউ জানল না, তারা কোথায় গেল।\n\nপ্রফেসর ক্রাউলি তার ল্যাব নোট আর রিপোর্টগুলো পর্যালোচনা করলেন।\nওগুলো ছিল সংক্ষিপ্ত, নিখুঁত—চোখে না পড়ার মতো, তবু নির্ভুল।\n\nএই ছাত্রটি তাকে ভাবিয়ে তুলল।\n\nভাবনা ভালো; তা প্রায়ই কৌতূহ্যের দিকে নিয়ে যায়।\n\nঅবশ্য, তখন ক্রাউলি বুঝতে পারেননি: তা আরেক কিছুর দিকেও নিয়ে যেতে পারে—মৃত্যু।"
  },
  CollectionHall_48991_Title = {
    Text = "মৃত্যুর বিশ্লেষণ"
  },
  CollectionHall_48992_Desc = {
    Text = "তুমি এতদিন ধরে নেই, অথচ আমি টেরই পাইনি।\n\nআমি এখনও সেই দিনের স্বপ্ন দেখি—বাম হাতে বন্দুকের গর্জনের যন্ত্রণা, রক্তক্ষরণের কুয়াশা, আমাদের পিছু ধাওয়া করা উন্মত্ত ইঁদুরগুলো...\nতারপর তুমি এলে, মাইথ্যাগের ইউনিফর্ম গায়ে, আমাকে সেই অভিশপ্ত পুরোনো দুর্গ থেকে বের করে আনলে।\n\nস্বপ্নের শেষে, তুমি আমার রোগশয্যার পাশে দাঁড়িয়ে আমাকে বলেছিলে:\nঅনুসন্ধান কর্মকর্তাদের জন্য, মৃত্যু সবসময় ঠিক পেছনেই লেগে থাকে।\n\nআমি আর বাস্তবতা আর স্বপ্নের ফারাক বুঝতে পারি না।\n\nযখনই বিভ্রান্ত হই, আমি হাত বাড়াই বাম হাতের দিকে—যদি ঠান্ডা, জটিল ধাতব অংশটা অনুভব করি, বুঝি আমি জেগে আছি।\n\nকিন্তু বেশিরভাগ সময়, আমার আঙুলে ধরা পড়ে শুধু শূন্যতা।"
  },
  CollectionHall_48992_Title = {
    Text = "প্রিয় বন্ধুকে"
  },
  CollectionHall_48993_Desc = {
    Text = "ক্রাউলি যত বছর পড়িয়েছেন, প্রতি বছরই তার নামের পাশে জুটেছে 「সবচেয়ে জনপ্রিয় মেন্টর」-এর খেতাব।\n\nতার সামান্য বেখাপ্পা ওয়েস্ট কনস্টান্তে উচ্চারণ আর অকৃত্রিম হাসি অগণিত ছাত্রের মন জয় করেছে, হার্বার্টও তাদেরই একজন।\n\nA.F.2@1 সালে, নানা আপত্তি উপেক্ষা করে ক্রাউলি সেই সময়ের একেবারে সাধারণ, নজরকাড়া নয় এমন হার্বার্টকেই ছাত্র হিসেবে বেছে নেন।\n\nএকসঙ্গে তারা পর্বতমালা পেরিয়েছে, স্রোতস্বিনী ডিঙিয়েছে, মরুভূমি হেঁটে অতিক্রম করেছে, একের পর এক D-ফাটলের বাইরে রেখে গেছে তাদের পদচিহ্ন।\n\n\nহার্বার্ট আজও মনে করতে পারে প্রথমবার D-ফাটল দেখার শক।\n\nক্রাউলি দাঁড়িয়ে ছিলেন উথলে ওঠা কালো কুয়াশার সামনে, তার অবয়ব তার তুলনায় ক্ষুদ্র, প্রায় গিলে খাওয়া যাচ্ছে যেন।\n\n「শ্—শুনতে পাচ্ছ?」\n\nহার্বার্ট চোখ বন্ধ করল।\nতার কানে ভেসে এল শুধু নীরব, গড়িয়ে চলা এক সাগরের শব্দ; চারপাশের পৃথিবী যেন ভেসে সরে গেল দূরে।\n\nক্রাউলি উৎফুল্ল হয়ে উঠলেন।\n「এটাই কবিতা,」 তিনি বললেন।\n「ব্রহ্মাণ্ডের সবচেয়ে রহস্যময়, সবচেয়ে গভীর কবিতা।」\n\nবহু বছর পরে, ক্রাউলিকে নিয়ে হার্বার্টের স্মৃতিগুলো প্রায় মুছে গিয়েছিল—\nকীভাবে তারা একসঙ্গে কাজ করত, তর্ক করত, এমনকি কীভাবে সে তাকে 「হঠাৎ করেই」 মেরে ফেলেছিল, সেটাও।\n\nকিন্তু কালো কুয়াশার নিচে সেই হাসিটা সে কখনো ভুলতে পারেনি।\nসেই মুহূর্তে, সে কবিতাকে দেখেছিল।"
  },
