  CollectionHall_49018_Desc = {
    Text = "এ.এফ. 314 সালে, গভীর শীতের এক রাতে, আকুতলিন জুড়ে বিস্ফোরণের শব্দ প্রতিধ্বনিত হলো।\n\nপৃথিবী কেঁপে উঠল, আর বনভূমি দুপুরের মতো আলোয় ভরে উঠল।\nজীবনের আর্তচিৎকার ও প্রকৃতির বিলাপের সঙ্গে সঙ্গে গ্রামটি মাটির সঙ্গে মিশে গেল।\n\nডেক্সটারের বর্ণনায়—যে 「আকুত বিপর্যয় তদন্ত」 অভিযানে অংশ নেওয়া আউয়েকেন সিস্টেমের এক প্রাক-মহাবিদ্যালয় ছাত্র—সেই রাতে আকাশচুম্বী অগ্নিশিখার ভেতর কালো ও রুপালি রঙের আভা তীব্রভাবে জ্বলে উঠেছিল।"
