  CollectionHall_49747_Desc = {
    Text = "ক্ষয়ক্ষতের দাগ থেকে জন্মানো অতিরিক্ত বৃদ্ধি।\nএখন পর্যন্ত, এই বৃদ্ধির সংঘটন এবং বিভিন্ন ধরনের বৃদ্ধির বিন্যাস সম্পর্কে কোনো সুনির্দিষ্ট নিয়ম খুঁজে পাওয়া যায়নি।\nএটি অতিরিক্ত অঙ্গ বা শুঁড় হতে পারে, আবার গিয়ার বা ধাতুর মতো অজৈব পদার্থও হতে পারে।"
  },
  CollectionHall_49747_Title = {
    Text = "D-হাইপারপ্লাসিয়া"
  },
  CollectionHall_49748_Desc = {
    Text = "<Title:সংজ্ঞা ও বৈশিষ্ট্য>\n5 মিটারের বেশি ব্যাসবিশিষ্ট এক বিশাল ডি-মার্ক, যা ক্রমাগত প্রসারিত হতে পারে।\nডি-রিফ্টকে তাদের আকারের ভিত্তিতে C, B, A, S, SS এবং SSS শ্রেণিতে ভাগ করা হয়।\nসময়ের সাথে সাথে এগুলো বিস্তৃত হতে থাকে, যার ফলে কেবল নিয়মিত ডিজলিউশন বিস্তারই নয়, সুনামি ও ঘূর্ণিঝড়ের মতো অস্বাভাবিক প্রাকৃতিক বিপর্যয়ও ডেকে আনে।\n\n<Title:প্রতিকার পদ্ধতি>\nসিলভার থেকে পরিশোধিত রৌপ্য চাবি নির্দিষ্ট মাত্রায় ডি-রিফ্টকে দমন, এমনকি 「বন্ধ」 করতেও সক্ষম।\nকিপাররা রৌপ্য চাবির মাধ্যমে নিজেদের আত্মিক শক্তি বৃদ্ধি করে, আত্মিক মাত্রার সঙ্গে অনুরণন ঘটিয়ে ডি-রিফ্টের উপর এক উচ্চ-মাত্রিক প্রতিরক্ষা প্রাচীর গঠন করে, যা সাময়িকভাবে তাকে 「বন্ধ」 রাখে।"
  },
  CollectionHall_49748_Title = {
    Text = "D-ফাটল"
  },
  CollectionHall_49749_Desc = {
    Text = "D-রিফ্টের কেন্দ্রবিন্দুই সাধারণত সেই প্রধান শত্রু, যাকে রক্ষকদের মাঠ পর্যায়ের মিশনে মোকাবিলা করতে হয়।\nএটি D-প্রপঞ্চ ছড়িয়ে দিতে পারে, নিজের বৈশিষ্ট্যের ভিত্তিতে আশেপাশের D-প্রপঞ্চকে প্রভাবিত করে এবং আঞ্চলিক বৈশিষ্ট্য সৃষ্টি করে।"
  },
  CollectionHall_49749_Title = {
    Text = "মহাবিপর্যয়"
  },
  CollectionHall_49750_Desc = {
    Text = "<Title:সংজ্ঞা ও বৈশিষ্ট্য>\nD-প্রপঞ্চ ব্যক্তির দেহে রূপান্তর, ডিজলিউশন এবং মৃত্যু ডেকে আনে।\nএটি মানুষের মতো জৈব সত্তা, প্রাণী ও উদ্ভিদ, এবং খনিজ ও ধাতুর মতো অজৈব পদার্থ—সবকিছুকেই প্রভাবিত করে। D-রিফ্টের নিকটে অবস্থানকারী ব্যক্তিরা D-প্রপঞ্চের প্রভাবে আরও বেশি সংবেদনশীল হয়ে ওঠে।\nএ পর্যন্ত কোনো পদার্থই D-প্রপঞ্চের প্রতি অনাক্রম্যতা প্রদর্শন করতে পারেনি।\n\n<Title:পর্যায়সমূহ>\nপ্রারম্ভিক স্তর: দেহের পৃষ্ঠে উল্টো ত্রিভুজাকৃতির কালো D-চিহ্ন দেখা যায়, এর সঙ্গে থাকে D-পঙ্কের নিঃসরণ।\nমধ্য স্তর: D-চিহ্ন বিস্তৃত হয়, D-পঙ্কের অবিরাম নিঃসরণ চলতে থাকে। মানসিক ক্ষতি ঘটে, এবং D-হাইপারপ্লাসিয়া বিকাশ লাভ করতে পারে।\nশেষ স্তর: D-চিহ্ন দ্রুত বিস্তৃত হয়, D-পঙ্কের নিঃসরণ আরও ত্বরান্বিত হয়। অধিকাংশ ব্যক্তি এই পর্যায়ে সম্পূর্ণভাবে সুস্থবুদ্ধি হারিয়ে ফেলে।\nচূড়ান্ত স্তর: দেহ ভেঙে পড়ে, শারীরবৃত্তীয় মৃত্যু ঘটে। মানসিক দূষণ অব্যাহত থাকে, যতক্ষণ না ব্যক্তি সম্পূর্ণভাবে কলুষিত হয়ে পুরোপুরি বিলীন হয়ে যায়, আর জাগরণের কোনো সম্ভাবনাই অবশিষ্ট থাকে না।\n\n<Title:বিশেষ কেসসমূহ>\nদেহগত কেস: শারীরিক সক্ষমতা ও ইন্দ্রিয়শক্তি বৃদ্ধি পায়। কিছু ব্যক্তির ক্ষেত্রে উড্ডয়ন, মনের উপর নিয়ন্ত্রণ, অথবা D-হাইপারপ্লাসিয়া ও বিপর্যয়ের ফলে সৃষ্ট অন্যান্য প্রভাবের মতো বিশেষ ক্ষমতা দেখা যায়।\nআত্মাগত কেস: মানসিক প্রভাব ন্যূনতম, মৌলিক সুস্থবুদ্ধি বজায় থাকে। কিছু ব্যক্তি প্রায় স্বাভাবিক আচরণ করে, যেন তারা D-প্রপঞ্চ দ্বারা একেবারেই প্রভাবিত হয়নি।"
  },
