  CollectionHall_49751_Desc = {
    Text = "<Title:সংজ্ঞা ও লক্ষণ>\nডিজলিউশনের ফলে ব্যক্তি তার দেহ হারিয়ে ফেলে, এবং ডি-স্লাইম ও (ক্ষয়িত) ধূলিকণায় রূপান্তরিত হয়।\nডিজলিউশন সম্পন্ন হওয়ার পর, তাদের অস্তিত্ব এই বিশ্ব থেকে মুছে যায়।\n\n<Title:পর্যায়ভিত্তিক বৈশিষ্ট্য>\nপ্রারম্ভিক পর্যায়: যারা আক্রান্ত ব্যক্তিকে ভালোভাবে চিনত না, তারা তার অস্তিত্ব ভুলে যেতে শুরু করে।\nমধ্য পর্যায়: পরিচিতদের স্মৃতিতে আক্রান্ত ব্যক্তির উপস্থিতি ক্ষীণ হতে থাকে, এবং লিখিত নথিতে ডি-মার্ক দেখা দেয়, অক্ষরগুলো ঝাপসা হয়ে যায়।\nশেষ পর্যায়: পরিচিতদের স্মৃতিতে আক্রান্ত ব্যক্তির ছাপ আরও ম্লান হতে থাকে, অবশেষে তারা সম্পূর্ণ ভুলে যায়; কেবল অস্পষ্ট এক অনুভূতি মাত্র থেকে যায়।\n\n<Title:অস্তিত্ব মুছে যাওয়া>\nচূড়ান্ত পর্যায়ে, আক্রান্ত ব্যক্তির অস্তিত্ব—তার সব চিহ্নসহ—সম্পূর্ণরূপে বিলুপ্ত হয়।\nতারা কখনও ছিল, তা প্রমাণ করার মতো কিছুই অবশিষ্ট থাকে না—যেমন অধিকাংশ মানুষের ক্ষেত্রেই ঘটে।"
  },
  CollectionHall_49751_Title = {
    Text = "দ্রবীভূত হওয়া"
  },
  CollectionHall_49752_Desc = {
    Text = "সিলভার হয়তো ডিজলিউশনের অন্তিম সীমানা: এটি এক প্রতিফলক পদার্থ, যা জীবনের উপর ডিজলিউশনের ক্ষয়চিহ্ন পড়লে সম্ভাব্যতার ভিত্তিতে গঠিত হয়। এতে শুধু বিপুল ভৌত শক্তি সঞ্চিত থাকে না, এটি আত্মিক মাত্রার সঙ্গেও এক সংযোগ স্থাপন করে। কিছু ক্ষেত্রে, এই সংযোগ এমনকি 「আত্মিক মাত্রা」-তেও হস্তক্ষেপ ঘটাতে পারে। ডিজলিউশনের বিরুদ্ধে মানবতার দীপ্তির সংগ্রামে সিলভার অন্যতম মূল উপাদান। কিন্তু এর গঠনের স্বতন্ত্র প্রকৃতির কারণে সিলভার যেমন অতি স্বল্পপ্রাপ্য, তেমনি ভীষণ মূল্যবান।"
  },
  CollectionHall_49752_Title = {
    Text = "সিলভার"
  },
  CollectionHall_49753_Desc = {
    Text = "<Title:সারসংক্ষেপ>\nসিলভার কোর ব্যবহার করে এমন সকল প্রযুক্তিকে সম্মিলিতভাবে সিলভার কোর টেকনোলজি বলা হয়।\nবিশ্বের অধিকাংশ মানুষ সিলভার কোরের অস্তিত্ব সম্পর্কে জানে না। কেবলমাত্র মিসাগার বিশ্ববিদ্যালয়ই সিলভার কোর টেকনোলজি আয়ত্ত করেছে এবং সিলভার কোরের গবেষণা ও উন্নয়ন অব্যাহত রাখতে একটি বিশেষ সিলভার কোর গবেষণা ও প্রয়োগ বিভাগ প্রতিষ্ঠা করেছে।\n《মিস্টেরিয়া চুক্তি》 অনুসারে, মিসাগার বিশ্ববিদ্যালয় ফিউশন ইরোশনের বিরুদ্ধে যৌথভাবে লড়াই করতে এবং সংকট মোকাবেলায় মিস্টেরিয়া চুক্তি পর্যালোচনা পরিষদকে সিলভার কোর টেকনোলজি সরবরাহ করে।\n\n<Title:জাগ্রত সত্তা?>\nমিসাগার বিশ্ববিদ্যালয়ের জাগ্রত সত্তা প্রযুক্তিতে, জাগ্রত সত্তার গঠন সিলভার কোরকে কেন্দ্র করে সম্পন্ন হয়।\nযদিও জাগ্রত সত্তার গঠন প্রক্রিয়া《সিলভার কোর প্রযুক্তি নির্দেশিকা》-তে নথিভুক্ত নয়, তবুও অনেক জাগ্রত সত্তা নিজেদের নিয়ে এভাবে রসিকতা করে:\n「হেই, আমরাও তো এক ধরনের সিলভার কোর টেকনোলজি, তাই না?」\n\n<Title:ফিউশন ইরোশন পর্যবেক্ষণ যন্ত্র>\nচশমা, মুখোশ ইত্যাদি বিভিন্ন ডিজাইনে পাওয়া যায়। সিলভার কোর দিয়ে তৈরি, যা পরিধানকারীকে গোপন অঞ্চল পর্যবেক্ষণ করতে এবং ফিউশন ইরোশন দেখতে সক্ষম করে।\n\n<Title:মিসাগার বিশ্ববিদ্যালয় যোগাযোগ যন্ত্র>\nসবচেয়ে সাধারণ ডিজাইনটি হলো বিশ্ববিদ্যালয়ের প্রতীক আকৃতির একটি ব্রোচ। এর মূলে রয়েছে বিশেষভাবে প্রক্রিয়াজাত সিলভার কোর। যোগাযোগ যন্ত্রগুলো শুধু পরস্পরের সাথে সংযুক্ত হতে পারে না, বরং মিসাগার ক্যাম্পাসের সাথে অতি দূরপাল্লার যোগাযোগও স্থাপন করতে পারে। সংকেত স্থিতিশীল এবং <Italic:সাধারণ পরিস্থিতিতে> প্রাকৃতিক ঘটনা দ্বারা প্রভাবিত হয় না।\n\n<Title:মিসাগার প্রবেশ অনুমতিপত্র>\nসিলভার কোরযুক্ত একটি বিশেষ অনুমতিপত্র। কেবলমাত্র এই অনুমতিপত্র বহনকারী ব্যক্তিরাই মিসাগার বিশ্ববিদ্যালয়ের কুয়াশা প্রতিবন্ধকে হারিয়ে যাওয়া এড়াতে পারে।\nঅনুমতিপত্রবিহীন ব্যক্তিরা কেবল বিশ্ববিদ্যালয়ের বাইরের বনে অন্তহীন সংবেদন বিভ্রান্তিতে আটকে পড়বে, যতক্ষণ না পালাক্রমে দায়িত্বরত তদন্তকারী তাদের বহিষ্কার করে।"
  },
  CollectionHall_49753_Title = {
    Text = "রৌপ্য প্রযুক্তি"
  },
  CollectionHall_49754_Desc = {
    Text = "<Title:মূলনীতি>\nরৌপ্য কোর থেকে জাগ্রত, পরীক্ষার মাধ্যমে রূপান্তরিত, অথবা কোনো দুর্ঘটনা থেকে জন্ম নেওয়া...\nতারা প্রাচীন, তবু নতুন। প্রাচীন—কারণ বহু শতাব্দী আগে জাদুকরেরা প্যাপিরাসের গোপন পাণ্ডুলিপিতে জাগ্রতদের উপস্থিতি লিপিবদ্ধ করে গিয়েছিল।\nতারা নতুন—কারণ আমরা এখনো জাগ্রতদের প্রকৃতি সম্পূর্ণভাবে বুঝে উঠতে পারিনি, অথচ তাদের সঙ্গেই বিশ্বরক্ষার অভিযাত্রায় পা বাড়িয়েছি।\nতাদের ওপর আস্থা রাখার পাশাপাশি, মনে রেখো: সতর্কতা কখনো শিথিল কোরো না।\n\n<Title:বৈশিষ্ট্য>\nজাগ্রতদের ব্যক্তিত্ব সম্পন্ন, এবং তারা তাদের 「পূর্বজীবন」-এর স্মৃতিচারণ ধরে রাখে; কিন্তু তাদের অনন্য সক্ষমতার কারণে, তাদেরকে মানবাকৃতি অস্ত্র হিসেবে ব্যবহার করা হয়েছে।\nসমাজের স্থিতিশীলতা বজায় রাখতে, বিভিন্ন দেশে জাগ্রতদের অস্তিত্ব কঠোর গোপনীয়তার আড়ালে রাখা হয়।\nবর্তমানে কেবল মিথাগ বিশ্ববিদ্যালয়ের মাধ্যমে জাগ্রত হওয়া জাগ্রতদেরই 「চুক্তি」 স্বীকৃতি দেয়। মিথাগ বিশ্ববিদ্যালয়ের বাইরে জাগ্রত হওয়া যে কোনো জাগ্রতকে 「চুক্তি」-ভঙ্গকারী হিসেবে গণ্য করা হয় এবং তাদের জন্য আনুষ্ঠানিক নথিভুক্তি ও নিয়ন্ত্রণ প্রয়োজন।\n\n<Title:স্তর>\nজাগ্রতদের সক্ষমতা ভিন্ন ভিন্ন হলেও, গবেষকরা বিভিন্ন সক্ষমতার মধ্যে কিছু স্থায়ী সাদৃশ্য খুঁজে পান।\nএই সাদৃশ্যের ভিত্তিতে, মিথাগ বিশ্ববিদ্যালয় কৃত্রিমভাবে জাগ্রতদের কয়েকটি স্তরে শ্রেণিবদ্ধ করেছে।\nএকই স্তরের জাগ্রতরা একে অপরের সঙ্গে অধিকতর সমন্বয়ে কাজ করতে পারে; অন্যদিকে ভিন্ন স্তরের মধ্যে কিছু মাত্রার পারস্পরিক বর্জন দেখা যায়—শুধু বিশৃঙ্খলা স্তরে এই প্রপঞ্চটি দেখা যায় না।\nস্তরান্তর বর্জনের কারণ এখনো অজানা। মিথাগ বিশ্ববিদ্যালয়ের জাগ্রত বিভাগীয় অধ্যাপক ডল-এর মতে, এটি হয়তো আত্মিক মাত্রার ওপর কিছু অজ্ঞেয় সত্তার প্রভাবের সঙ্গে সম্পর্কিত; যদিও এই অনুমান সমর্থন করার মতো কোনো প্রমাণ এখনো পাওয়া যায়নি।"
  },
  CollectionHall_49754_Title = {
