  CollectionHall_49758_Desc = {
    Text = "<Title:Founding Date>\nবন্যার আগে\n\n<Title:Founder>\nমিরিয়াম\n\n<Title:Overview>\nপুরোনো মহাদেশ থেকে উদ্ভূত এক প্রাচীন সংগঠন।\nএর সদস্যদের সাধারণত দেখা যায় মাছের মতো উপরের দেহ আর মানুষের মতো নিচের দেহ নিয়ে; তারা মূলত মহাসাগর ও উপকূলীয় অঞ্চলে সক্রিয়, কখনোই স্থলভাগের গভীরে প্রবেশ করে না।\nবলা হয়, তারা সমুদ্র পাড়ি দেয় রাজাধিরাজের পথ অনুসরণ করতে এবং দেবলোকের আবির্ভাব ঘটাতে।\nসমস্ত উৎসর্গ নিবেদিত হারিয়ে যাওয়া লেমুরিয়া রাজ্য এবং তার তন্দ্রাচ্ছন্ন রাজাকে।"
  },
