  CollectionHall_49759_Desc = {
    Text = "<Title:Founding Date>\nবন্যার সময়\n\n<Title:Founder>\nঅজানা জীব\n\n<Title:Overview>\nএক গোপন ধর্মীয় সংগঠন।\nতারা ডিজলিউশন-কে ঈশ্বরপ্রদত্ত দান এবং রূপালি পদার্থকে ঈশ্বরের দেহ বলে মানে, বিশ্বাস করে ডিজলিউশন পাপ শুদ্ধ করে এবং নিয়ে যায় নির্দোষ নির্মল ভূমিতে।\nসংখ্যায় বিপুল হলেও তাদের গতিবিধি থাকে গোপন; যেখানে যেখানে ডিজলিউশন ঘটে, সেখানেই তাদের ক্ষীণ চিহ্ন টের পাওয়া যায়।\nগুঞ্জন আছে, তারা নাকি এক প্রাচীন ও সম্মানিত পরিবার থেকে উদ্ভূত, যাদের সমষ্টিগত অন্তর্ধান আজও ইতিহাসের এক বিতর্কিত রহস্য।"
