  CollectionHall_49762_Desc = {
    Text = "<Title:রৌপ্য কোর>\nঅওয়েকেনাররা তাদের রৌপ্য কোর ছাড়া কার্যকর থাকতে পারে না। দেহ সম্পূর্ণভাবে বিচ্ছিন্ন হয়ে গেলেও, যতক্ষণ রৌপ্য কোর অটুট থাকে, ততক্ষণ অওয়েকেনারকে পুনরায় জাগ্রত করা সম্ভব।\n\n<Title:দেহ>\nঅওয়েকেনারের দেহ নানান উপাদান দিয়ে গঠিত হতে পারে। নির্দিষ্ট উপকরণ ও গঠনবিন্যাস অওয়েকেনার নিজস্ব পছন্দ ও বৈশিষ্ট্যের সঙ্গে সম্পর্কিত।\nঅওয়েকেনারের দেহ মিথাগ বিশ্ববিদ্যালয়ের কর্মীরা পূর্বনির্ধারিতভাবে সরবরাহ করে না; বরং জাগরণ অনুষ্ঠানের সময় রৌপ্য কোরে সঞ্চিত আত্মিক শক্তি থেকেই তা গঠিত হয়। সুতরাং জাগরণ অনুষ্ঠানে প্রয়োজনীয় রৌপ্য কোর ও রৌপ্য চাবির পাশাপাশি অওয়েকেনারের দেহ সংশ্লেষণের জন্য বিপুল পরিমাণ উপাদান প্রস্তুত রাখতে হয়। সাধারণ উপাদানের তালিকা সংযোজনী 3-এ দেওয়া আছে।\nঅতিরিক্তভাবে, মিথাগ বিশ্ববিদ্যালয়ে অওয়েকেনারের দেহের রক্ষণাবেক্ষণ ও মেরামতের জন্য বিশেষায়িত বিভাগ ও গবেষক নিয়োজিত আছেন।"
  },
  CollectionHall_49762_Title = {
    Text = "জাগরণকারী গঠন"
  },
  CollectionHall_49763_Desc = {
    Text = "<Title:দৈনন্দিন জীবন>\nঅওয়েকেনাররা মিথাগ বিশ্ববিদ্যালয়ের কর্মীদের সমান অধিকার ভোগ করে। তারা ক্যাম্পাসের সুবিধাসমূহ ব্যবহার করতে এবং তদন্ত সংক্রান্ত পুরস্কার গ্রহণ করতে পারে।\nযখন তাদের সঙ্গী অনুসন্ধান কর্মকর্তাদের মাঠপর্যায়ের কোনো দায়িত্ব থাকে না, অওয়েকেনাররা ক্যাম্পাসজুড়ে অবাধে চলাফেরা করতে পারে। অধিকাংশ অওয়েকেনার তাদের অতীতের শখ ও অভ্যাস অনুসরণ করে নিজের পছন্দের কাজ খুঁজে নেয়; কেউ কেউ শ্রেণিকক্ষে প্রবেশ করে বর্তমান যুগ সম্পর্কে জানতে চায়, কিংবা অনুসন্ধান কর্মকর্তাদের সঙ্গে মেলামেশা করে।\nকিছু বিশেষ পরিস্থিতি ছাড়া, সাধারণত অওয়েকেনারদের খাওয়া বা ঘুমানোর প্রয়োজন হয় না। তবে তারা যদি এসব কাজ করতে চায়, তাতে কোনো নেতিবাচক প্রভাব পড়বে না।\n\n<Title:যুদ্ধ>\nযুদ্ধক্ষেত্রের নির্দেশনা ও লিঙ্ক বজায় রাখার মধ্যে শক্তি ব্যয়ের ভারসাম্য রক্ষার জন্য মিথাগ বিশ্ববিদ্যালয় “নসিস ট্রান্সফার” নামের এক বিশেষ যন্ত্র উদ্ভাবন করেছে।\nমাঠপর্যায়ের স্যুটকেসে স্থাপিত “নসিস ট্রান্সফার” অওয়েকেনারদের ক্ষমতাকে কার্ড আকারে রূপান্তর করতে পারে, যার মাধ্যমে অওয়েকেনারদের নির্দেশনা প্রদান সম্ভব হয়।"
  },
  CollectionHall_49763_Title = {
    Text = "জাগরণকারীর আচরণ"
