  CollectionHall_49764_Desc = {
    Text = "<Title:প্রতিষ্ঠার তারিখ>\nA.F.306\n\n<Title:প্রতিষ্ঠাতা>\nহার্বার্ট·রোজেনথাল\n\n<Title:সংক্ষিপ্ত বিবরণ>\nএকটি উগ্র ব্যক্তিমালিকানাধীন গবেষণা সংগঠন।\nবিপর্যয় থেকে বাঁচতে মানুষের সঙ্গে ডিজলিউশন সত্তার সংমিশ্রণের মাধ্যমে মানব বিবর্তনের চেষ্টা করে।\nপ্রায় 20 জন উগ্র সদস্য নিয়ে গঠিত, যারা নির্দোষদের পরীক্ষামূলক বিষয় হিসেবে গণ্য করে, এবং নৃশংস পদ্ধতি প্রয়োগ করে।\nমিথাগ বিশ্ববিদ্যালয়ের কুখ্যাত দেশদ্রোহী হার্বার্ট·রোজেনথাল দ্বারা প্রতিষ্ঠিত, আলোবাহকদের গির্জার সঙ্গে ঘনিষ্ঠ সহযোগিতায় নিয়োজিত।\nতাদের প্রতীক হলো ভাস্করের সমতল ছেনি, যা নাকি সেই সাইপ্রিয়ট রাজাকে শ্রদ্ধা জানিয়ে বেছে নেওয়া, যে এক মূর্তির প্রেমে পড়েছিল।"
