  CollectionHall_51019_Desc = {
    Text = "<Title:প্রতিষ্ঠার তারিখ>\nপ্রলয়ের পূর্বে\n\n<Title:প্রতিষ্ঠাতা>\nঅজানা\n\n<Title:সংক্ষিপ্ত বিবরণ>\nএকটি যাযাবর জাতি, যারা আসিরীয় সাম্রাজ্য থেকে বিচ্ছিন্ন হয়ে বেরিয়ে এসেছে।\nরেমুয়াহে মরুভূমির প্রচণ্ড ঝড়ের আড়ালে লুকিয়ে থেকে, তারা অত্যন্ত আদিম উপায়ে জীবনযাপন করে, বাইরের জগতের সঙ্গে খুব কমই যোগাযোগ রাখে। আরাম গোষ্ঠী পূজো করে 「প্রাচুর্যের মাতৃবৃক্ষ」-কে; তার অসাধারণ প্রজনন ক্ষমতা এবং পবিত্র নদীর জলকে ভর করে তারা নিজেদের জনসংখ্যার পরিসর ধরে রাখে।\n「রেমুয়াহে ঘটনা」-র পর, আরাম গোষ্ঠী বিনা চিহ্নে বিলীন হয়ে যায়; আর কোনো খবর পাওয়া যায়নি।"
  },
  CollectionHall_51019_LockTip = {
    Text = "অধ্যায় 7: 「কামনার স্রোত」 সম্পন্ন করো"
  },
  CollectionHall_51019_Title = {
    Text = "অ্যারামাইটস"
  },
  CollectionHall_51038_Title = {
    Text = "07 কামনার স্রোত"
  },
  CollectionHall_51373_Title = {
    Text = "অজ্ঞেয় সত্তা"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:পরিচিতি>\nমিসাগ বিশ্ববিদ্যালয়ের অধ্যাপক, সমাজকর্মী এবং অভিজাত।\nএকসময় ছিলেন অমিতব্যয়ী প্লেবয়, কিছু তুচ্ছ অপরাধ করেছিলেন এবং আইনের উভয় পক্ষেই তাঁর সুনাম ছিল।\nপরবর্তীতে তাঁর পরিবার ধর্মীয় গোষ্ঠীর হাতে নিশ্চিহ্ন হয়ে যায় এবং তিনিই একমাত্র জীবিত ব্যক্তি। এরপর কী ঘটেছিল, তা কেবল তিনিই জানেন।\nরামোনার পালক পিতা হওয়া সত্ত্বেও, রামোনার উৎপত্তি সম্পর্কে তিনি সম্পূর্ণ নীরব।\nযৌবনে প্রতিটি বিষয়ে অকৃতকার্য হয়েও, পরে মিসাগের অধ্যাপক হয়ে গেলেন।\nস্বভাবে উচ্ছৃঙ্খল ও মুক্তমনা, তবুও কোনো নারী বা পুরুষের সাথে কখনো কোনো প্রণয়ের গুজব ওঠেনি।\nসব মিলিয়ে, এক দ্বন্দ্বে ভরা মানুষ।"
  },
  CollectionHall_51374_LockTip = {
    Text = "প্রস্তাবনা সম্পন্ন করো"
  },
  CollectionHall_51374_Title = {
    Text = "ডেক্সটার"
  },
  CollectionHall_51375_Desc = {
    Text = "<Title:পরিচিতি>\nডেক্সটারের পালিত কন্যা, নায়কের সবচেয়ে বিশ্বস্ত তদন্ত সঙ্গী।\nছোটবেলা থেকেই একাডেমির বিভিন্ন বিভাগের ক্লাসরুমে ঘুরে বেড়িয়েছে, তাই ক্ষয়ীভবন প্রপঞ্চ, জাগ্রত সত্তা প্রভৃতি বিষয়ে তার যথেষ্ট জ্ঞান রয়েছে।\n\nছোটবেলায় রামোনাও একসময় তার 「জন্মদাতা পিতামাতা」-র প্রতি আকাঙ্ক্ষা অনুভব করেছিল, কিন্তু ডেক্সটার ও শিক্ষকদের যত্ন ও ভালোবাসায় সে অনেক আগেই একাডেমিকে তার প্রকৃত ঘর হিসেবে মেনে নিয়েছে।\n\nশান্ত, যুক্তিবাদী এবং যথাযথ পরিমাণে সদয় — তার মধ্যে কোনো 「অদ্ভুত」 বৈশিষ্ট্য নেই — মিসাগের এই উদ্ভট মানুষগুলোর মাঝে তার 「স্বাভাবিকতা」 বরং আলাদাভাবে চোখে পড়ে।\nযদিও সবসময় নির্বিকার মুখ করে থাকে, তবে যারা তাকে ভালো করে চেনে তারা জানে, এটা কেবল একজন 「প্রতিভাবান」-এর ক্লান্তি মাত্র।"
  },
