  CollectionHall_57597_Desc = {
    Text = "<Title:পরিচিতি>\nলেন্টিনিয়েন মহানগরীর বর্তমান বিশপ, এবং পূর্ববর্তী বিশপের দ্বারা দুর্ঘটনাক্রমে জাগ্রত একজন জাগ্রত সত্তা।\nসৃষ্টিকর্তা পিতৃদেবের একনিষ্ঠ ভক্ত, জীবন দিয়ে পিতৃদেবের শিক্ষা পালন করেন, দয়া ও সহিষ্ণুতার হৃদয় দিয়ে জগতের সকল কিছুর প্রতি আচরণ করেন, জনসাধারণের মধ্যে অত্যন্ত উচ্চ সম্মান উপভোগ করেন, এমনকি কিছু ভক্ত তাঁকে \"লেন্টিনিয়েনের সাধু\" বলে অভিহিত করেন।\nবিড়ম্বনার বিষয় হলো, সকল কিছুর প্রতি এই করুণা ও সহানুভূতিই তাঁর মানব জীবনকে কেড়ে নিয়েছিল।\nজীবদ্দশায় তিনি ক্ষয়রোগ নিরাময়ের চেষ্টা করেছিলেন, এর জন্য জীবন ফলকের কাছে নিজের রক্তমাংস উৎসর্গ করতেও দ্বিধা করেননি, ধর্মপ্রদেশের \"রোগীদের\" যন্ত্রণা লাঘব করতে এবং তাদের জীবন দীর্ঘায়িত করতে। তাঁর মৃত্যুর পর, ফলকটি নিখোঁজ হয়ে যায়—যতক্ষণ না তিনি একজন জাগ্রত সত্তা হিসেবে পুনরায় জেগে ওঠেন।\nকাপড়ের টুকরো ও ব্যান্ডেজের আড়ালে ঢাকা তাঁর দুই চোখ আত্মার দীপ্তি দেখতে সক্ষম, তাই রহস্যরক্ষককে দেখামাত্রই তিনি নিশ্চিত হন: রহস্যরক্ষকই পিতৃদেবের ভবিষ্যদ্বাণীতে উল্লিখিত ফ্যাকাশে দূত, যিনি এই অন্ধকারে নিমজ্জিত হতে চলা বিশ্বকে রক্ষা করতে পারেন।"
  },
