  CollectionHall_57598_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রাগৈতিহাসিক সভ্যতা লেমুরিয়ার সর্বকনিষ্ঠ শিশু-রাজা।\nশৈশব থেকেই অসাধারণ প্রতিভাধর, প্রতিদিন বিশ ঘণ্টারও বেশি সময় গভীর ঘুমে কাটান, আর জেগে থাকলেও সর্বদা তন্দ্রাচ্ছন্ন দেখায়।\nমাঝে মাঝে দেবতাদের পছন্দ-অপছন্দ অনুভব করতে পারেন, বিভিন্ন কালপর্বের খণ্ডাংশ স্বপ্নে দেখেন, এই কারণেই তাঁকে পূজা করা হয়, ভয় করা হয় এবং রাজা হিসেবে সম্মান করা হয়।\nকিশোর রাজা এসব নিয়ে মাথা ঘামান না। তিনি কেবল দেবতাদের প্রত্যাদেশ ও ভবিষ্যদ্বাণী থেকে নিষ্ক্রিয়ভাবে পলায়ন করেন।\n\nঅবশেষে লেমুরিয়ার ধ্বংসের অমোঘ নিয়তি তিনি পূর্বদর্শন করেছিলেন, কিন্তু কীভাবে তা পরিবর্তন করবেন তা জানতেন না, তাই নীরব থাকতে বাধ্য হন।\nযেদিন বিপর্যয় নেমে এল, সকলে হতাশায় ডুবে গেল। প্রজাদের প্রত্যাশায় সাড়া দিতে, তিনি একটি মিথ্যা ভবিষ্যদ্বাণী রচনা করলেন।\nএক অমর রাজার কথা, এবং তাঁর পুনরায় পৃথিবীতে আবির্ভাবের ভবিষ্যদ্বাণী।\nশেষ পর্যন্ত, পুরনো পৃথিবী প্লাবনে তলিয়ে গেল। যুগ বদলাল, নতুন মানবজাতি আবার ভূমিতে বংশবিস্তার করল, প্রাগৈতিহাসিক ঘটনা আর কেউ জানল না।\nসম্ভবত তিনিও আন্দাজ করতে পারেননি যে, তাঁর অনিচ্ছাকৃত ভবিষ্যদ্বাণী মানুষের দ্বারা বারবার পুনর্ব্যাখ্যায়িত হবে।\nশেষ পর্যন্ত, তিনি বিশ্বাসের শক্তিকে অবমূল্যায়ন করেছিলেন।"
  },
