  CollectionHall_57599_Desc = {
    Text = "<Title:পরিচিতি>\nআলান গোষ্ঠীর বিদেশি দূত, স্বপ্নের প্রত্যাদেশ অনুসরণ করে লেমওয়াশিতে এসেছেন বলে দাবি করেন।\nআলান গোষ্ঠীর দলকে নেতৃত্ব দিয়ে দীর্ঘকাল ঝড়ের প্রাচীরের বাইরে ঘুরে বেড়িয়েছেন, আলান গোষ্ঠীর পবিত্র বৃক্ষ — প্রাচুর্যের মাতৃবৃক্ষকে পুনরুজ্জীবিত করার সম্ভাবনা খুঁজছেন।\nপ্রকৃতপক্ষে লণ্ঠন চার্চের অধীনস্থ। তাঁর সেই চিরন্তন করুণাময় হাসির আড়ালে লুকানো প্রকৃত উদ্দেশ্য এখনও কেউ জানে না, হয়তো যাত্রা এগিয়ে চললে কিছুটা আঁচ করা যাবে।"
  },
  CollectionHall_57599_LockTip = {
