  CollectionHall_57600_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রাগৈতিহাসিক সভ্যতা লেমুরিয়ায় বসবাসকারী, তার পরিবারের সকলেই ছিলেন নিষ্ঠাবান ধর্মপ্রাণ আধ্যাত্মিক সাধক।\nশৈশব থেকেই নিরলস সাধনায় রত ছিলেন, এবং বড় হয়ে তার ইচ্ছানুযায়ী রাজধানীর মন্দিরে প্রবেশ করেন এবং একজন পুরোহিত হন।\nতিনি দৈবিক নিদর্শনের জন্য আকুল ছিলেন, অলৌকিক অভিজ্ঞতার জন্য তৃষ্ণার্ত ছিলেন, কিন্তু সেসব কখনো আসেনি।\n\nতুরু যখন রাজা হিসেবে সিংহাসনে আরোহণ করলেন, তিনি তাঁর পার্শ্বচর মহাপুরোহিত হলেন।\nনতুন রাজাকে প্রথমবার দেখার মুহূর্তে, তিনি চরম বিভোর ও আনন্দ অনুভব করলেন, এবং সঙ্গে সঙ্গে বুঝতে পারলেন যে এই-ই সেই দৈবিক সত্তা যার জন্য তিনি আকুল ছিলেন — মর্ত্যলোকে ঈশ্বরের অবতার।\nহ্যাঁ। তাঁর অস্তিত্বের অর্থই হলো এই বালক রাজার সেবা করা।\n\nমহাপ্লাবন যখন মহাদেশ ও লেমুরিয়ার সভ্যতাকে সমুদ্রের তলদেশে ডুবিয়ে দিল, তখনও তাঁর এই বিশ্বাস কখনো টলেনি।"
  },
  CollectionHall_57600_LockTip = {
