  CollectionHall_57602_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রাচীন কিংবদন্তি অনুসারে, পৃথিবীতে দুটি দানবীয় পশু বিদ্যমান ছিল, একটি জলের গভীর অতলে এবং অন্যটি ইডেনের পূর্বে অবস্থান করত।\nএই দুই দানবীয় পশু কেবল সময়ের অন্তিম মুহূর্তেই মিলিত হতে পারত, এবং তারা জীবনের জননী তিয়ামাতের কাছে বলিরূপে নিবেদিত হবে, যাতে জীবনের পুনর্জন্মচক্র বিনিময়ে পাওয়া যায়।\n\nলোতান হলো সেই কিংবদন্তির আড়ালে লুকিয়ে থাকা 「পশু「।\nসে গ্রহের একটি প্রাকৃতিক সৃষ্টি, এবং কিংবদন্তির থেকে ভিন্নভাবে, সে একই সাথে অতলের জল এবং ইডেনের আত্মা।\nসে বিশুদ্ধ বিশৃঙ্খলার শক্তি, অদম্য মুক্ত আত্মা, এবং অনির্ধারিত শৃঙ্খলা।\nধ্বংস ও নিয়ম — এই দুটি ক্ষমতা বিশ্ব তাকে প্রদান করেছে। দুটি সম্পূর্ণ বিপরীত সহজাত প্রবৃত্তি লোতানের দেহে সংঘর্ষ করে, এবং তাকে ছিন্নভিন্ন করতে সক্ষম এই শক্তির ভারসাম্য রক্ষার জন্য, তাকে যুদ্ধের মাধ্যমে ধ্বংসের আকাঙ্ক্ষা মুক্ত করতে হয়।\nলোতানকে গ্রহ ইতিহাস রক্ষার দায়িত্ব অর্পণ করেছে। তার 「কাজ「 হলো গ্রহের ইচ্ছা অনুসরণ করে গ্রহের ভাগ্যকে প্রভাবিত করে এমন ব্যক্তিদের নির্মূল ও দমন করা, কিন্তু এমন ব্যক্তি কোটি কোটি বছরেও বিরল।\nঅন্তহীন, মিশন অবতরণের অপেক্ষায় একঘেয়ে সময়ে, লোতান একজন প্রতিদ্বন্দ্বীর আবির্ভাবের জন্য আকুল।\n\nএই কারণে, সে একসময় সেই তরুণ শিশু-রাজার দিকে দৃষ্টি নিবদ্ধ করেছিল, এমনকি পতনের বিপর্যয়ও ডেকে এনেছিল।\nতবুও কিছুই তার উত্তাল যুদ্ধের ইচ্ছাকে ক্ষতিগ্রস্ত করতে পারেনি, তার পুনর্জাগরণের সাথে সাথে সেগুলো কেবল আরও প্রবল হয়ে উঠেছে।"
  },
