  CollectionHall_57603_Desc = {
    Text = "<Title:পরিচিতি>\nসমাধি-অস্থি নগরীর প্রাক্তন যুবরাজ, বর্তমানে দেবতা হিসেবে পূজিত শবভক্ষক ঘুলদের রাজা।\nতিনি একজন বুদ্ধিমান ও ন্যায়পরায়ণ যুবক হলেও, তাঁর অনন্য খাদ্যাভ্যাস — মৃতদেহ ভক্ষণ — রাজপরিবারের আশঙ্কার কারণ হয়ে দাঁড়ায়।\nসিংহাসন ত্যাগের আগের রাতে তাঁর পিতা রাজা দুলেসাইনকে বিষ প্রয়োগে হত্যা করেন। ক্ষয় ও গ্রাসের প্রক্রিয়ায় তাঁর চেতনা মন্দিরে প্রতিষ্ঠিত দেবসত্তার সাথে মিশে যায়, এবং তিনি নিজের দেহের স্বাদ আস্বাদন করেন — সেই বিস্ময়কর মাধুর্য তাঁকে চিরকাল তাড়িত করে।\nতিনি আহারকে এক রোমান্টিক শিল্প হিসেবে দেখেন — এটি কেবল জিহ্বার তৃপ্তি নয়, বরং বিস্মৃতদের স্মরণে রাখার উপায়।\nক্ষয় সবকিছু ধ্বংস করে, অতীতকে বাতাসে মিলিয়ে দেয়, কিন্তু দুলেসাইন প্রতিটি জীবিত সত্তার কিংবদন্তি ও সাধারণত্বের সাক্ষী হন, রক্ত ও মাংসকে নিজের স্মৃতিতে সংরক্ষণ করেন — অনন্তকাল পর্যন্ত।"
  },
