  CollectionHall_57604_Desc = {
    Text = "<Title:পরিচিতি>\nএককালে এক অঞ্চলের শাসনকর্তা ম্যানর লর্ড ছিলেন।\nশোনা যায়, তাঁর মাতৃগ্রহ ক্ষয়ে ধ্বংস হওয়ার পর, এক বিশাল উল্কাপিণ্ডে চড়ে ক্যাম্ব্রিয়ান উপত্যকায় পতিত হন।\nগবাদি পশু ব্যবস্থাপনা, ভূমি অধিগ্রহণ এবং ঝুঁকিপূর্ণ বিনিয়োগ পরিচালনায় দক্ষ।\nপ্রতিবার বাইরে গেলে, তাঁর পেছনে অমর সেবকদের এক বিশাল বহর অনুসরণ করে।\n১ জন পা রাখার টুল হিসেবে, ২ জন চারণকবি বিনোদনের জন্য, আর ৪ জন গাড়োয়ান……\nপোপও তাঁকে দেখলে নিজের সাদামাটা জাঁকজমকে লজ্জা পাবেন।"
  },
  CollectionHall_57604_LockTip = {
