  CollectionHall_57605_Desc = {
    Text = "<Title:পরিচিতি>\nটিঙ্কটের প্রিয় যমজ বোন।\nজন্মের শুরু থেকেই সে এক অনন্য 「প্রতিভা」 প্রদর্শন করেছিল। তার অনিয়ন্ত্রিত ক্ষমতার কারণে, ফেইন্ট কেবল চিরকাল 「শিশুবন্ধনী」তে কুঁকড়ে থাকতে বাধ্য হয়, বড় হতে অক্ষম।\nতাকে গোষ্ঠীর জন্য দুর্ভাগ্য বয়ে আনা ব্যক্তি হিসেবে গণ্য করা হয়েছিল, তাই টিঙ্কটের সাথে তাকেও তাদের আবাসস্থল থেকে বিতাড়িত করা হয়।\n\nবোন উচ্চবিত্তদের দানের উপর নির্ভর করে জীবনধারণের রসদ জোগাড় করত, এবং সেই সম্পদের অধিকাংশই সে ফেইন্টের ভরণপোষণে ব্যয় করত।\nএক বিপর্যয়ের পর, সে একটিমাত্র 「টিকিট」 উপার্জন করে এবং ফেইন্টকে প্রতারণা করে সেই জনশূন্য গ্রহ ছেড়ে যাওয়ার যাত্রায় পাঠিয়ে দেয়।\nউড্ডয়নের মুহূর্তে, ফেইন্ট তার প্রথম এবং শেষ প্রতিরোধ করেছিল:\nসে শিশুবন্ধনী ত্যাগ করে সকলের জীবনশক্তি শোষণ করার হুমকি দিয়ে টিঙ্কটকে চলে যেতে বাধ্য করে……\nনিজেকে 「ত্রুটিপূর্ণ」 মনে করায়, সে অত্যন্ত হীনম্মন্যতায় ভোগে।\n\nএকসময় সে খাওয়া প্রত্যাখ্যান করেছিল, আশা করেছিল তাড়াতাড়ি অনাহারে মারা যাবে, যাতে টিঙ্কটের বোঝা না হয়।\nদীর্ঘদিন এভাবে চলার ফলে, তার খাবারে বাছবিচার করার বদঅভ্যাস তৈরি হয়ে গেছে।\n\nঅন্ধকার কোণ পছন্দ করে। সাধারণত ফেইন্টকে খুঁজে পেতে ভূগর্ভস্থ কক্ষের মতো জায়গায় যেতে হয়।"
  },
