  CollectionHall_57606_Desc = {
    Text = "<Title:পরিচিতি>\nকেটিগুলা মরুভূমি অঞ্চলে জন্মগ্রহণকারী একজন অনাথ। যখন সে কিশোরী ছিল, তখনই সে স্থানীয় অনেক দুর্ভাগা শিশুকে আশ্রয় দিয়েছিল।\nএই শিশুদের নিয়ে পৃথিবীতে টিকে থাকার সংগ্রামে, সে সযত্নে একটি মিথ্যা বাহ্যিক আবরণ তৈরি করেছিল, যা দিয়ে সে বিদ্বেষপূর্ণ আক্রমণ প্রতিহত করত।\nঅনেকের চোখে, সে ছিল নিষ্ঠুরতা ও উন্মাদনার মূর্ত প্রতীক।\nযেকোনো সংঘর্ষেই, সে সবচেয়ে উন্মত্ত উদ্দীপনা ও সবচেয়ে নির্মম উপায়ে তার বন্দুকের সামনে দাঁড়ানোর সাহস করা শত্রুদের জবাব দিত।\nসময়ের সাথে সাথে, এমনকি সেখানকার সদ্য কথা শেখা শিশুরাও জানত যে অসীম বালুসাগরে একজন অ্যাম্বার রঙের মৃত্যুদূত বিচরণ করে।\nN-এর সাথে এক সংঘর্ষে, প্রত্যাশিতভাবেই সে সেই খেলায় হেরে গিয়েছিল এবং তাই সবকিছু হারিয়েছিল।\nকিন্তু এমনকি N-ও জানত না যে, সে অনেক আগেই নক্ষত্রমণ্ডলের কারো দৃষ্টি আকর্ষণ করেছিল।\nনিয়তি-নির্ধারিত মৃত্যুর পর, সে প্রতিশ্রুতি অনুযায়ী তাঁর শক্তি উত্তরাধিকারসূত্রে পেয়েছিল, সেইসাথে তাঁর নির্ধারিত দায়িত্বও।\nতার দেহে নক্ষত্রমণ্ডলের সত্তা নিহিত রয়েছে; সে অনেক আগেই তাঁদের একজন হতে পারত।\nযদি সেই চূড়ান্ত মুহূর্তের আগমন রোধ করা অনিবার্যভাবে অসম্ভব হয়, তবে তিনি সবকিছু ত্যাগ করে পরম আকাশে ফিরে যাবেন, হয়ে উঠবেন সেই প্রথম এবং শেষ আশ্রয়স্থল।"
