  CollectionHall_57607_Desc = {
    Text = "<Title:পরিচিতি>\nমেল্টডাউন·ডোর মূলত মিসাগার্ড তথা সমগ্র মানব বিজ্ঞানের গর্ব ছিলেন। ফিউশন ইরোশনের বিরুদ্ধে দীর্ঘ লড়াইয়ের মধ্যে তিনি উপলব্ধি করলেন যে, ফিউশন ইরোশন যখন দেহকে ক্ষয় করে, তখন একই সাথে সত্যের দিকে যাওয়ার পথও উন্মুক্ত করে।\nএকটি প্রাচীন রহস্যময় বাণী খোদাই করা পাথরের ফলকের সাথে আকস্মিক সংস্পর্শের পর, তিনি এই অন্ধকার ও সীমাহীন পথে চলার সিদ্ধান্ত নিলেন। পুতুল দেহ প্রতিস্থাপনের মাধ্যমে জীবন ধারণ করা ত্যাগ করে, তিনি ফিউশন ইরোশনকে তাঁর ব্রেইন ক্যাসকেটকে গ্রাস করতে দিলেন।\nঅবশেষে তাঁর ইচ্ছা পূর্ণ হলো — তিনি ফিউশন ইরোশনের প্রকৃত সারমর্ম উপলব্ধি করলেন, কিন্তু একই সাথে সম্পূর্ণরূপে ধ্বংস ও শূন্যতার দিকে এগিয়ে গেলেন।\nসেই প্রদীপের মতো সকলকে পথ দেখানো বিশ্বাস ও যুক্তি অদৃশ্য হওয়ার পর, মেল্টডাউন·ডোর স্কুলের শিক্ষক-ছাত্রদের দৃষ্টির আড়ালে ধ্বংসের পথ অনুসরণ করতে শুরু করলেন। বেশ কয়েকটি হতাহতের ঘটনায় \"সহায়তা\" করার পর অবশেষে মিসাগার্ড তাঁকে শনাক্ত করে এবং সর্বোচ্চ স্তরের নজরদারি ও দমন প্রয়োগ করা হয়।\nতবে ধ্বংসপ্রাপ্ত পুতুল দেহের আড়ালে, সেই প্রতিভাধর অবিনশ্বর আত্মা যেন এখনও বিশ্বের পেছনে আরও গভীর, আরও অন্ধকার কোনো স্থানের সাথে দূর থেকে প্রতিধ্বনিত হচ্ছে।"
  },
  CollectionHall_57607_LockTip = {
