  CollectionHall_57609_Desc = {
    Text = "<Title:পরিচিতি>\nমিসাগারের 「মস্তিষ্ক」 হিসেবে পরিচিত প্রতিভাবান পণ্ডিত, মিসাগারের ফিল্ড উপদেষ্টাদের একজন।\n১৪ বছর বয়সে মিসাগারে ভর্তি হন, অ্যালিস্টেয়ারের জীবন-ধারণ যন্ত্রের উন্নতিকরণে নেতৃত্ব দিয়েছিলেন।\nএকবার বাইরে যাওয়ার সময় ক্ষয়রোগে সংক্রমিত হন, পুরো আশি পৃষ্ঠার জাগরণ প্রক্রিয়ার নির্দেশনা লিখে শান্তভাবে মৃত্যুবরণ করেন।\nমৃত্যুর পর সঙ্গীরা নির্দেশনা অনুসরণ করে তাঁর সিলভার কোরটি জাগরণ যন্ত্রে স্থাপন করেন, তৈরি করেন 「ডোর জাগরণ সত্তা」।\nজাগ্রত হওয়ার পর, তিনি শান্তভাবে উঠে পোশাক পরেন, শান্তভাবে গবেষণাগারে প্রবেশ করেন, শান্তভাবে জীবদ্দশায় অসমাপ্ত গবেষণা চালিয়ে যান।\nআহা! প্রতিভাবানদের জগৎ এতটাই নীরস ও সাদামাটা।"
  },
