  CollectionHall_57610_Desc = {
    Text = "<Title:পরিচিতি>\nএক ভিনগ্রহী প্রজাতির আত্মিক সত্তা, যে ক্ষয়গ্রাসে গ্রাস হওয়া গ্রহ থেকে পালিয়ে এসেছিল, সদ্য মৃত এক কিশোরীর দেহ দখল করে নেয় এবং তার পিতামাতার মতো মৃত্যুর ভাগ্য এড়াতে সক্ষম হয়।\nকিন্তু সুসময় বেশিদিন স্থায়ী হয়নি। এই মানবদেহে ক্ষয়গ্রাসের লক্ষণ দেখা দেওয়ার পর, তার আত্মিক সত্তাও ক্ষয়গ্রাসে আবদ্ধ হয়ে দেহের ভেতরে স্থির হয়ে যায়, আর পালাতে অক্ষম হয়।\nক্ষয়গ্রাসের সংক্রমণের ভয়ে মানসিক ভাঙনের শিকার হয়ে সে নিজে থেকে মিসাগের সাথে যোগাযোগ করে এবং নিজেকে জাগ্রত সত্তায় রূপান্তরিত করার অনুরোধ জানায়, বিনিময়ে নিজের প্রজাতির জ্ঞান ও প্রযুক্তি প্রদানের প্রতিশ্রুতি দেয়।\nজাগ্রত সত্তা হওয়ার পর একাডেমিতে যান্ত্রিক, বৈদ্যুতিক ও মানসিক সম্পর্কিত গবেষণা পরিচালনা করে। ক্ষয়গ্রাসের প্রতি অত্যধিক ভয়ের কারণে ক্ষয়গ্রাস গবেষণা করতে অক্ষম, এমনকি মানসিক আঘাতের কারণে অন্ধকারকেও ভয় পায়, ঘুমাতে সাহস করে না, প্রতিদিন অতিসংবেদনশীলতা ও স্নায়বিক অস্থিরতার মধ্যে দিন কাটায়।"
  },
