  CollectionHall_57611_Desc = {
    Text = "<Title:পরিচিতি>\nমানসিক জগতে জন্ম নেওয়া একটি আত্মিক সত্তা, যে মূলত ধূসর সমুদ্রের বিস্তীর্ণ ও শূন্য প্রান্তরে একাকী ভাসমান ছিল। মাঝে মাঝে আগত মানসিক পরিব্রাজকদের অনুসরণ করে পৃথিবীতে এসেছিল, বিভিন্ন ইচ্ছা অনুভব করেছিল, এবং তাদের মস্তক ছিন্ন করে সমুদ্রে সংগ্রহ করত, তাদের জ্ঞান ও আবেগ শোষণ করত।\nএক হাজার ছয়শো বছরেরও বেশি আগে জাগ্রত হয়েছিল এবং জাগরণকারীর দেহে ভর করে তার মস্তক ছিন্ন করেছিল। মানসিক শক্তি শোষণের বৈশিষ্ট্যের কারণে, অস্তিত্ব টিকিয়ে রাখতে মস্তক সংগ্রহ করে চলেছিল, এবং বিনোদনের জন্য প্রয়োজনের চেয়ে অনেক বেশি মস্তক শিকার করে খেলা করেছিল। যতক্ষণ না প্রকৃত দোকানদারের সাথে দেখা হয়, তাকে বশীভূত করা হয় এবং একটি বিনিময় চুক্তি হয়, সহকারী হিসেবে দোকানদারের জীবনের শেষ পর্যন্ত তাকে অনুসরণ করে।\nদোকানদারের সাথে প্রকৃত বন্ধুত্ব গড়ে তোলা দানবটি তার আসল আকাঙ্ক্ষা বুঝতে পেরেছিল, দোকানদারের মস্তক ছিন্ন করেছিল এবং তার চেহারা ও দোকান উত্তরাধিকারসূত্রে পেয়েছিল। তারপর থেকে আর যথেচ্ছ মস্তক শিকার করে না, বরং বিনিময় দোকানের মাধ্যমে রহস্যবিদ্যা সংক্রান্ত অনুরোধ সমাধান করে মস্তক অর্জন করে, এবং গ্রাহকদের সাথে কথোপকথনের মাধ্যমে দোকানদারকে হারানোর একাকীত্ব প্রশমিত করে।\nবর্তমান ইচ্ছা হলো দোকান এবং দোকানদারের প্রিয় শহরকে রক্ষা করা।"
