  CollectionHall_57612_Desc = {
    Text = "<Title:পরিচিতি>\nজীবিত থাকাকালীন তিনি ছিলেন একজন বিশ্বভ্রমণকারী জাদুকর।\nছোটবেলা থেকে সার্কাসে বড় হয়েছেন, জীবন ভরা ছিল অনেক 「বহিরাগত」 দিয়ে—চোর, পলাতক আসামি, পরিত্যক্ত শিশু, প্রতিবন্ধী, বিকৃতাঙ্গ...\nক্যাসিয়াও ছিলেন একজন 「বহিরাগত」: তিনি আবেগ অনুভব করতে পারতেন না, নিজে থেকে কোনো আবেগ তৈরিও করতে পারতেন না।\nতিনি ছিলেন এক খাঁটি পারফরম্যান্স প্রতিভা, সবসময় দর্শকদের উচ্ছ্বসিত করতালি জিততেন।\nএমনকি পরে @2-এর সম্মুখীন হয়ে, ধর্মদ্রোহিতার শিকার একটি আত্মায় পরিণত হওয়ার পরেও, তিনি জীবিতকালের মতোই জাদু প্রদর্শন করে যেতেন, দর্শকদের 「রূপকথার মতো এক বিস্ময়কর জগতে」 আমন্ত্রণ জানাতেন।\nঅদ্ভুত বিষয় হলো, প্রতিটি দর্শক জাদু শো দেখার পর অনুভব করত যে 「কিছু একটা যেন নেই」, জীবন ক্রমশ নিরানন্দ হয়ে উঠত।\nতারা বিভ্রান্ত হতো, অসাড় হয়ে যেত, এমনকি আত্মহত্যাও করত।\nআর আমাদের জাদুকর মহোদয়া? তিনি পর্দার আড়ালে লুকিয়ে, আনন্দের সাথে নিজের অর্জিত মিষ্টি 「পারিশ্রমিক」 চুষে খেতেন।\nজমকালো পারফরম্যান্সের খরচ অনেক বেশি, তিনি শুধু টেকসই উন্নয়নের জন্যই এটা করতেন।"
  },
