  CollectionHall_57613_Desc = {
    Text = "<Title:পরিচিতি>\nঘটনাক্রমে বিশ্বরেখার বাধা অতিক্রমকারী এক রহস্যময় সত্তা, এবং রামোনার আরেকটি সম্ভাবনা।\n「সেই ঘটনায়」, গোপনরক্ষকের নিরাপত্তার জন্য, জাগ্রত সত্তার শক্তিকে শরীরের নিয়ন্ত্রণ নিতে দিতে বাধ্য হয়েছিল।\n\nঘটনা শেষ হওয়ার পর, @2 রামোনার উপর যে প্রভাব রেখে গেছে তা কখনো মুছে যায়নি।\n@2-এর চেতনা তার শরীরে রয়ে গেছে, দিনে দিনে চেতনার অস্তিত্বের জায়গা সংকুচিত করছে।\nএই কারণে, সে অন্তহীন সংগ্রাম ও যন্ত্রণায় নিমজ্জিত।\n\nঅন্যদের চিন্তিত করতে না চাওয়ায়, বাইরে সব ঠিক আছে এমন ভান করে\n, নিজের চুল ও জীবনযাত্রা সুশৃঙ্খলভাবে গুছিয়ে রাখে।\nমাঝে মাঝে চেতনা হারিয়ে যায়, শূন্য দৃষ্টিতে তাকিয়ে থাকে\n, এমনকি অন্য একটি কণ্ঠস্বরে কথা বলে।\nএ নিয়ে উদ্বিগ্ন হওয়ার প্রয়োজন নেই। উৎস ভিন্ন হলেও, সবকিছুই গোপনরক্ষক এবং এই বিশ্বের শান্তির জন্যই।"
  },
