  CollectionHall_57614_Desc = {
    Text = "<Title:পরিচিতি>\nসে জন্মেছিল কবিতা ও গোলাপের দেশে, সে কবিতার পরী।\nপরী শব্দে বোনা স্বপ্নে বিচরণ করে, প্রতিটি সূর্যরশ্মির প্রস্ফুটনে আনন্দিত হয়, প্রতিটি ফুলের ঝরে পড়ায় অশ্রু ফেলে।\nসে গুনগুন করে, সে বিষণ্ণ হয়, সে আরেকটি আত্মার সঙ্গ কামনা করে।\n\nপরে, ফুলে ভরা উঠোনে, তরুণ মালী একটি গোলাপ তার সামনে রেখেছিল।\nতখন সে লজ্জায় হেসে উঠল, আলতো করে ফুলটি গ্রহণ করল।\n「অবশেষে আর একা নই।」\nসেই সময় সে এটাই দৃঢ়ভাবে বিশ্বাস করেছিল।"
  },
  CollectionHall_57614_LockTip = {
