  CollectionHall_57615_Desc = {
    Text = "<Title:পরিচিতি>\nসুদূর প্রাচীনকাল থেকে আগত, আরান গোষ্ঠীর একমাত্র রানি।\nশৈশবে তাকে বৃক্ষের দূত হিসেবে সম্মানিত করা হয়েছিল, রাজার আদেশ বহন করার জন্য। প্রথম বিদ্রোহের পর তাকে বলির উপহার হিসেবে আরান গোষ্ঠীর পবিত্র নদীতে নিক্ষেপ করা হয়, কিন্তু সেখানেই তার মধ্যে বৃক্ষের ইচ্ছা জাগ্রত হয়।\nতার রক্ত-মাংসে মিশে গেছে বৃক্ষের রস, আর বৃক্ষের শিকড়ে প্রবাহিত হয় তার রক্তধারা। তিনিই প্রাচুর্যের মাতৃবৃক্ষ, আর প্রাচুর্যের মাতৃবৃক্ষই তিনি।\nতবে ক্ষয়কারী শক্তি আরান গোষ্ঠীর রক্তধারাকে কলুষিত করেছিল, এবং তিনি স্বেচ্ছায় নিজের দেহ দিয়ে মাতৃবৃক্ষের পরিবর্তে সেই কলুষ বহন করেন, আরান গোষ্ঠীর বেঁচে থাকার শেষ আশা রক্ষার জন্য।\nআজ, যখন আরান গোষ্ঠী ইতিহাসের দীর্ঘ স্রোতে বিলীন হয়ে গেছে, কেবলমাত্র মাটি ভেদ করে উত্থিত হয়ে আবার প্রচণ্ড শব্দে ধসে পড়া প্রাচুর্যের মাতৃবৃক্ষই তার সাথে জড়িত কাহিনীর সাক্ষী হয়ে রয়েছে।"
  },
