  CollectionHall_57617_Desc = {
    Text = "<Title:পরিচিতি>\nমিসাগে বিশ্ববিদ্যালয়ের মনোবিদ্যার শিক্ষিকা, তদন্তকারীদের মানসিক পরামর্শদানের দায়িত্বে নিয়োজিত।\nকোমল ও দয়ালু স্বভাবের, ক্যাম্পাসের শিক্ষক-শিক্ষার্থী সকলের কাছে অত্যন্ত প্রিয়, তবে মিসাগের কিছু সদস্য তাকে ভীষণ ভয় পায়।\nসেই রহস্যময় উপাদানের লাল চা-এর কথা বাদই দিন—কেউ কখনো তাকে হাসিবিহীন দেখেনি, শুধু এই একটি বিষয়ই শিউরে ওঠার জন্য যথেষ্ট।"
  },
