  CollectionHall_57621_Desc = {
    Text = "<Title:পরিচিতি>\nমিসাগার একজন অভিজ্ঞ তদন্তকারী, গোপনীয়তা রক্ষাকারীদের কাছে সম্মানের সাথে 「সিনিয়র」 হিসেবে পরিচিত।\nএকসময় কিছু অবর্ণনীয় কারণে বাইরে যেতে ভয় পেতেন, স্কুলে পড়াশোনার পাশাপাশি গোয়েন্দা দলের সদস্য হিসেবে কাজ করতেন।\nপ্রিয় বন্ধুর মৃত্যুর পর, পূর্বের ধারা বদলে সম্মুখ সারিতে যোগ দেন, 「সে যা করত তাই করা」-র মাধ্যমে তাঁর হারিয়ে যাওয়া বন্ধুকে স্মরণ করেন।\nসর্বদা একটি ভাঙা রূপালি চাবি সাথে রাখেন, ক্রমশ মুছে যাওয়া সেই স্মৃতিগুলোকে কষ্টে ধরে রাখার চেষ্টা করেন।"
  },
  CollectionHall_57621_LockTip = {
    Text = "প্রস্তাবনা সম্পন্ন করো"
  },
  CollectionHall_57621_Title = {
    Text = "উইলিয়াম সিনিয়র"
