  CollectionHall_57622_Desc = {
    Text = "<Title:পরিচিতি>\nসিতের মালী, অরলার শৈশবের অন্তরঙ্গ বন্ধু।\nঅরলা যখন সবচেয়ে অসহায় ছিল, কোলেট একটি বাগান দিয়ে তাকে সবচেয়ে অবিস্মরণীয় সুখের সময় উপহার দিয়েছিল।\nঅরলার প্রতিভা যখন শিকড় গেড়ে অঙ্কুরিত হচ্ছিল, কোলেট একটি অগ্নিকাণ্ডে তার সম্পদ, খ্যাতি এবং জীবন কেড়ে নিয়েছিল।\nসে হার্বার্টের সাথে মিলে অরলার কবিতা সংকলন থেকে কবিতার জগৎ সৃষ্টি করেছিল। হয়তো স্মরণের জন্য, হয়তো নিয়ন্ত্রণের জন্য। কেউ জানে না।\nকোলেট সবসময় দাবি করত, সেই সুন্দর কবিতাগুলোতে সে কেবল একটাই জিনিস বুঝতে পেরেছিল—বাসনা।\nসে এর জন্য যন্ত্রণা ভোগ করেছিল। সে এটাকে গর্বের বিষয় মনে করত।"
  },
