  CollectionHall_57623_Desc = {
    Text = "<Title:পরিচিতি>\nমিরিয়াম দুইজন ডেবোরার সাথে দেখা হয়েছিল: একজন লেমুরিয়ার পুরোহিত, অন্যজন অর্ন পরিবারের পরিচারিকা। একজন তার প্রিয় বন্ধু ছিল, অন্যজনও তার প্রিয় বন্ধু ছিল।\nদশ হাজার বছরের ব্যবধানে দুটি যুগ, দুটি ভিন্ন মানুষ, একই নাম, একই চেহারা, একই সদয়তা। এটি একটি বিরল কাকতালীয় ঘটনা, আর মিরিয়ামের কাছে এটি ছিল এক পবিত্র পূর্বলক্ষণ।\nমিরিয়াম দুই ডেবোরার পরিণতি প্রত্যক্ষ করেছিল: একজন লেমুরিয়ার সাথে সমুদ্রের তলদেশে তলিয়ে গেল, অন্যজনকে সে নিজ হাতে বেদিতে তুলে দিল, উদর বিদীর্ণ করে মৃত্যু হলো।\nদেবরাজ্যের এই মহান আখ্যানে, ডেবোরার গল্প কেবল দুটি সংক্ষিপ্ত রক্তলাল পাদটীকা মাত্র।"
