  CollectionHall_57624_Desc = {
    Text = "<Title:পরিচিতি>\nমিসাগার্ড বিশ্ববিদ্যালয়ের প্রথম সারির তথ্য দালাল, ক্যাম্পাস রিজনিং অ্যাসোসিয়েশনের সদস্য।\nতুলনাহীন তথ্য সংগ্রহ ও অনুসন্ধান ক্ষমতার অধিকারী, সমগ্র লন্ডিনিয়ামে বেশ সুপরিচিত।\nমূলত ইয়াগ্রো প্রজাতন্ত্রের নাগরিক, পারিবারিক দুর্ঘটনার কারণে লন্ডিনিয়ামে এসেছেন এবং মিসাগার্ডের গোপন তথ্য হাতে রেখে সফলভাবে ভর্তি হয়েছেন।\nতার প্রাণবন্ত হাসিতে কখনো প্রতারিত হবেন না — মিসাগার্ড সম্পর্কে তার জ্ঞান সাধারণ মানুষের ধারণার চেয়ে অনেক গভীর।"
