  CollectionHall_57625_Desc = {
    Text = "<Title:পরিচিতি>\nগ্রিন ফাউন্ডেশনের প্রাক্তন গবেষক, লাই স্যানাটোরিয়ামের পরিচালক।\nস্বামী ও মেয়ের মৃত্যুর পর, তিনি মেয়েকে পুনরুজ্জীবিত করার উপায় খুঁজে বেড়াচ্ছিলেন।\nদীর্ঘ অনুসন্ধানের পথে, তিনি মেয়ের মুখ ভুলে গেছেন, ভুলে গেছেন সেই ভালোবাসা ও উষ্ণতা যা একসময় তাঁকে এগিয়ে যেতে শক্তি জুগিয়েছিল।\nতিনি শুধু যন্ত্রণাটুকুই মনে রেখেছেন।"
