  CollectionHall_57626_Desc = {
    Text = "<Title:পরিচিতি>\nসোনানিয়েল জাহাজের ক্যাপ্টেন।\nতার জন্মভূমি ক্ষয়ের কারণে মানুষের স্মৃতি থেকে মুছে গেছে, কেবল সে-ই সবকিছু মনে রাখে। তাই মানুষ তাকে পাগল বলে ডাকে।\nসমুদ্রতীরের ছোট্ট শহর, আপনজন, ভাইবোন... এসবই সেই পাগলের প্রাণপণে ফিরে পেতে চাওয়া অতীত।\nসে মিরিয়ামের সাথে একটি চুক্তি করেছে — তার প্রয়োজনীয় মালামাল পরিবহন করবে, আর বিনিময়ে মিরিয়াম তাকে এক সুদীর্ঘকাল ঘুমিয়ে থাকা স্মৃতি জাগিয়ে তুলতে সাহায্য করবে।\nআর তখনই, সে দেখতে পেল সেই তরুণীকে — যাকে ঘিরে আছে মৃদু বাতাস আর শুভ্র পাখিরা।\n\n「আমার নাম সেলেস্ট, যতদিন তোমার আমাকে প্রয়োজন, আমি এখানে থাকব।」\nসে ছিল তার মাতৃভূমির একসময়ের অস্তিত্বের চিহ্ন, শৈশবে বৃদ্ধদের মুখে শোনা রূপকথা।\n\nদেখা গেল, সেই মনকে তাড়া করা অতীত সত্যিই বাস্তব ছিল।"
  },
