  CollectionHall_57627_Desc = {
    Text = "<Title:পরিচিতি>\nপিতৃদেবতা জিশি মহামন্দিরের কর্মকর্তা, বিশপ ও অন্যান্য ধর্মযাজকদের সহায়তা করে মন্দিরের দৈনন্দিন কার্যক্রম পরিচালনায় দায়িত্বপ্রাপ্ত।\nপিতার মৃত্যুর পর, তার দক্ষ বড় বোন পরিবারের দায়িত্ব কাঁধে তুলে নেয় এবং একজন বিখ্যাত ব্যবসায়ী হয়ে ওঠে। সবকিছু যেন এত সুন্দর ও সুষ্ঠুভাবে চলছিল——সেই সুপরিকল্পিত প্রতারণার আগ পর্যন্ত।\nএকরাতের মধ্যে, মা ও দুই মেয়ে সর্বস্বান্ত হয়ে গেল। কিন্তু কিছু যায় আসে না, লুন্দিনিয়েনের বিশপ তার প্রতি সাহায্যের হাত বাড়িয়ে দিলেন। যতক্ষণ পরিবার পাশে আছে, সে কোনো কষ্টকে ভয় পায় না।\nতারপর তার বোন মারা গেল।\nতার মা অসহ্য শোকে ভেঙে পড়লেন এবং বিষণ্ণতায় প্রাণ হারালেন।\nএদিকে, তাদের পৈতৃক বাড়ি দখলকারী সেই নির্লজ্জ ব্যক্তি শিল্প সভার আয়োজন করে আনন্দ-ফুর্তিতে মেতে উঠেছিল।\nবিভ্রান্তি, ক্রোধ, অবোধগম্যতা……অসংখ্য আবেগ তার বুকে জমে গিয়ে এমন এক ঘৃণায় রূপ নিল যা তাকে ছাই করে দিতে চাইছিল। কিন্তু তার এমন হওয়া উচিত নয়, বিশপ বলেছিলেন, অতীতে আটকে থাকলে কখনো এগিয়ে যাওয়া যায় না, একমাত্র ক্ষমাই মুক্তি দিতে পারে।\nসে পারল না।\n'নিজেকে সহ্য করতে বাধ্য করো না,' সেই আত্মঘোষিত প্রদীপবাহিনী মহিলা তার কানে মিষ্টি সুরে প্ররোচিত করল, 'ক্ষমা মানেই প্রশ্রয়। সৎ মানুষই ন্যায়পরায়ণ বলে গণ্য হওয়া উচিত, আর দুষ্ট——দুষ্টদের যথাযোগ্য শাস্তি পাওয়া উচিত।'\nতারপর সে তার হাত থেকে আয়নাটি গ্রহণ করল এবং বিচারের আচার শুরু করল।"
  },
