  CollectionHall_57628_Desc = {
    Text = "<Title:পরিচিতি>\nঅজানা উৎসের এক দাস, যে গলিয়াতের পর গোত্রের প্রধান হয়েছিল।\nমাত্র ৮ বছর বয়সে নিজের মালিককে হত্যা করে একটি কাঠের পিপায় লুকিয়ে ফিলিস্তিনদের দ্বীপে ভেসে এসেছিল।\nতার শিরায় বইত নীচ রক্তধারা—দুর্বল, হীন ও উচ্চাকাঙ্ক্ষী।\nপ্রধান হওয়ার এক মাসের মধ্যেই তার শিরশ্ছেদ করা হয়, শাসনকালের দিক থেকে অন্যান্য প্রধানদের মধ্যে তার স্থান ১৩তম।\nফিলিস্তিনদের প্রধানের পদ এমন কিছু নয় যেখানে নিশ্চিন্তে অবসর নেওয়া যায়।"
