  CollectionHall_57629_Desc = {
    Text = "<Title:পরিচিতি>\n\n\nসে একদা ছিল চিরন্তন রাজ্যের রিলে স্টেশন, রাজ্য ও বাইরের জগতের প্রবেশ-প্রস্থান পথের দায়িত্বে নিয়োজিত, পথহারা প্রজাদের স্বদেশে ফিরিয়ে আনার পথ দেখাত।\nযখন রাজ্য গভীর নিদ্রায় নিমজ্জিত হয়ে সমুদ্র ঘূর্ণির গভীরে তলিয়ে যেতে লাগল, ফারোস তার জন্মভূমির সাথে সংযোগ হারিয়ে ফেলল।\nসে রাজধানীর সাথে যোগাযোগ করতে পারেনি, বিশাল সমুদ্রেও কোনো চিহ্ন খুঁজে পায়নি।\n\nসমুদ্রের বাতিঘর হয়েও স্বদেশে ফেরার পথ আলোকিত করতে না পারা — এ কী চরম পরিহাস!\n\nদীর্ঘ ও নিঃসঙ্গ সময়ে ধীরে ধীরে উন্মাদ ও অক্ষম হয়ে পড়ে, ইতিহাসে একাধিক সামুদ্রিক বিপর্যয়ের কারণ হয়ে দাঁড়ায়, যতক্ষণ না শক্তি নিঃশেষ হলে কোনো এক প্রাচীন বীর তাকে পরাজিত করে।\n\nপরবর্তীকালের গবেষণায়, কিছু পণ্ডিত এমনকি মনে করেন যে ফারোসের উন্মাদনাই ওশেনিয়ার নিমজ্জনের কারণ।\nসবই কেবল অনুমান। আজ পর্যন্ত, এই উন্মত্ত ভক্তের অতীত এক রহস্যই রয়ে গেছে।"
