  CollectionHall_57630_Desc = {
    Text = "<Title:পরিচিতি>\nএকটি ডাচির ক্ষুদ্র অভিজাত পরিবারের পুত্র। সম্ভ্রান্ত বংশে জন্ম হলেও তার পিতার কোনো উল্লেখযোগ্য কৃতিত্ব ছিল না, তাই তার ভবিষ্যৎ জীবন ছিল দৃশ্যত সাদামাটা।\nযতক্ষণ না একবার বড়দিনের ভোজসভায় তার পিতা তাকে গ্র্যান্ড ডিউকের সাথে সাক্ষাৎ করাতে নিয়ে যান। ভোজসভায় অসুস্থ সমবয়সী রাজকুমারীর প্রতি তার যত্ন ও স্নেহ গ্র্যান্ড ডিউকের দৃষ্টি আকর্ষণ করে। গ্র্যান্ড ডিউকের একটি রসিকতার মধ্য দিয়ে সে ডাচির নাইট রিজার্ভ হয়ে ওঠে এবং আনুষ্ঠানিকভাবে নাইট অর্ডারের প্রশিক্ষণে অংশ নিতে শুরু করে।\nযতদিন না যুদ্ধের আগুন এসে পৌঁছায়। ডাচির দুর্বল সেনাবাহিনী অশ্বারোহী বাহিনীর আক্রমণ ঠেকাতে অক্ষম হয়। মৃত্যু ও আহতদের মাঝে, অজিয়ের ছিলেন রাজকুমারীকে রক্ষাকারী শেষ \"নাইট\"।\nতিনি তার জন্য এখনও অতিরিক্ত লম্বা বর্শাটি হাতে ধরে, চিরকালের জন্য রাজকুমারীর দরজার সামনে দাঁড়িয়ে রইলেন।"
