  CollectionHall_57631_Desc = {
    Text = "<Title:পরিচিতি>\nআগুনের শিখায় নৃত্যরত প্রতিভাবান নর্তকী।\nশত শত বছর ধরে, তার পরিবার রাজদরবারের নর্তকী হিসেবে বিদ্যমান ছিল। তাই রাজ্য পরিবর্তন হলেও, স্কুল বন্ধ হয়ে গেলেও, সে কখনো তার মার্জিত ও সুন্দর নৃত্যের আত্মা হারায়নি।\nআঠারো বছর বয়সে, সে স্থানীয় ব্যালে দলে যোগ দেয় এবং দ্রুতই নিঃসন্দেহে প্রধান নর্তকী হয়ে ওঠে।\n\nকিন্তু প্রথম অভিনয় সফল হওয়ার পর, নৃত্যদলের ম্যানেজার 「পরিচয়」 করিয়ে দেওয়ার নামে লিজকে ধনী ব্যবসায়ীর কক্ষে পাঠিয়ে দেয়।\nদেখা গেল, ব্যালে আর বিশুদ্ধ ছিল না, মার্জিত ঐতিহ্য মেয়েদের দাম বাড়ানোর পুঁজিতে পরিণত হয়েছিল।\nতাই সে পালিয়ে যায়, ধরা পড়ে, তারপর আবার পালায়... অবশেষে, তার 「অহংকার」 ক্ষমতাশালী বড় মানুষদের ক্রোধ জাগিয়ে তোলে।\nতারা শরীরে ও মনে লিজকে নির্যাতন করে, তাকে অবিরাম ঘুরতে হবে, অবিরাম নাচতে হবে, পায়ের আঙুল ফেটে গেলেও, কালো দূষিত রক্ত মেঝেতে ঝরে পড়লেও থামা যাবে না।\n\nঅবশেষে, একটি সাধারণ অনুষ্ঠানে, যখন নৃত্য সর্বোচ্চ শিখরে পৌঁছায়, তখন তার পায়ের তলা থেকে আগুন বিস্তার লাভ করে জ্বলে ওঠে।\nসে সমস্ত অন্যায় ও পাপ পুড়িয়ে ছাই করে দেবে।"
