  CollectionHall_57632_Desc = {
    Text = "<Title:পরিচিতি>\nদাসত্ব, দত্তক গ্রহণ, পরিত্যাগ... এখানে পর্যন্ত গল্পটি অন্য টাইমলাইনের শিলোর থেকে আলাদা কিছু নয়, কিন্তু একই রক্ত অবশেষে ভিন্ন এক ভগ্ন শাখার জন্ম দিল।\nকারাগারে পতিত হওয়ার পরই প্রকৃত নরক শুরু হলো। সে আতঙ্কিত হয়ে আবিষ্কার করল, যে গোষ্ঠীর লোকদের তার সাথে মিলে দাস-মালিকদের ঘৃণা করার কথা ছিল, তারাও তাকে ঘৃণা করছে — বরং তাদের বিদ্বেষ আরও তীব্র।\nপ্রতিদিন, প্রতিটি দিন, সে অন্তহীন যন্ত্রণা ও কষ্টের মধ্যে নিমজ্জিত হলো। ভাগ্যের উপহার সুদে-আসলে তার মানসিক শক্তিকে ধ্বংস করে দিল।\nদাস-মালিকদের প্রতি তার যে ঘৃণা থাকার কথা ছিল, তা রূপান্তরিত হলো সকলের প্রতি ঘৃণায়। একইভাবে সেও সকলের দ্বারা ঘৃণিত হলো, নিজের অস্তিত্বের জায়গাটুকুও হারিয়ে ফেলল।\nযখন ফিউশন ইরোশনের শক্তি ব্যবহার করে কারাগার থেকে পালাল, তখন তার হৃদয়ে কেবল উন্মাদনাই অবশিষ্ট ছিল। হঠাৎ পাওয়া এই শক্তি হাতে নিয়ে, সে অধীর আগ্রহে তার অন্তহীন ক্রোধ মুক্ত করতে লাগল।\nসেই রাতে, পুরো নগরীতে রক্তবর্ণ বৃষ্টি ঝরল। সে লাল নদীর মাঝে দাঁড়িয়ে, মাথা তুলে তৃপ্তিতে উচ্চস্বরে হেসে উঠল।"
  },
