  CollectionHall_57633_Desc = {
    Text = "<Title:পরিচিতি>\nভাস্কর সমিতির প্রতিষ্ঠাতা ও সভাপতি।\nশৈশবে মেরুদণ্ডের প্রদাহে আক্রান্ত হয়ে বাড়িতেই স্ব-শিক্ষায় পড়াশোনা করতে বাধ্য হন, সেই সময় থেকেই মানবদেহের সীমাবদ্ধতা সম্পর্কে সচেতন হয়ে ওঠেন।\nবড় হয়ে মিসাগে প্রবেশ করেন এবং পরামর্শদাতার সহায়তায় গবেষণার দিকনির্দেশনা খুঁজে পান, পাশাপাশি নিজের রোগও নিরাময় করেন।\nসর্বদা মুখে কোমল হাসি থাকে, কিন্তু বাস্তবে মানবিক আবেগের প্রতি সম্পূর্ণ উদাসীন।\nবাহ্যিক পরিচ্ছন্নতায় অমনোযোগী, চুল তাঁর অফিসের ডেস্কের মতোই এলোমেলো।\nডেস্কের ড্রয়ারে একটি ফাইল ফোল্ডার রাখা আছে, যেখানে ক্রাউলির বছরের পর বছর প্রকাশিত গবেষণাপত্রগুলো সুশৃঙ্খলভাবে সংগ্রহ করা আছে — এটাই হার্বার্টের করা সবচেয়ে সুসংগঠিত কাজ।"
  },
