  CollectionHall_57634_Desc = {
    Text = "<Title:পরিচিতি>\nফিলিস্তিনিদের দৃষ্টিতে, ইতিহাসের সবচেয়ে সাহসী নেতা।\nদীর্ঘদেহী, বলশালী — ক্ষমতায় আসার মাত্র কয়েক বছরের মধ্যেই তিনি ফিলিস্তিনিদের নেতৃত্ব দিয়ে আশেপাশের সমস্ত গোত্রকে পরাজিত করেছেন, আজ পর্যন্ত কোনো পরাজয়ের মুখ দেখেননি।\nপ্রশংসা ও ফুলের বর্ষণের মাঝে তাঁর খ্যাতি দূর-দূরান্তে ছড়িয়ে পড়ে, কিন্তু স্বজাতির সতর্কবাণী উপেক্ষা করে তিনি শত্রুকে অবমূল্যায়নের মহাপাপ করে বসেন।\nসামান্য ভুলের কারণে ফিলিস্তিনি বাহিনী সম্পূর্ণ বিপর্যস্ত হয়ে পড়ে। তাই তিনি স্বেচ্ছায় শাস্তি মেনে নিয়ে একমাত্র অনুসারীকে সঙ্গে নিয়ে সমুদ্রে নির্বাসনে যান।\nক্রোধ, অপমান… এই লজ্জাজনক মুহূর্ত চিরকাল স্মরণে থাকবে। তিনি বরং নিজের দুর্বল ঘাড় 「ডাইনি」-র কাছে সমর্পণ করতে রাজি, শুধু নিজের সবকিছু ফিরে পেতে।\nতিনি ইতিমধ্যেই রক্তাক্ত প্রতিশোধের পথে পা বাড়িয়েছেন।"
  },
