  CollectionHall_57635_Desc = {
    Text = "<Title:পরিচিতি>\nসে ছিল একজন নীচু দাসী, ছোটবেলা থেকেই তার বুদ্ধিমত্তা ও সৌন্দর্য যেন তার করুণ ভাগ্যকে পূর্বনির্ধারিত করে রেখেছিল।\nতবে আকস্মিক সৌভাগ্য তাকে শাসনকর্তা দম্পতির মৃত কন্যার স্থলাভিষিক্ত করে তাদের বাধ্য পালিত কন্যা বানিয়ে দিল, আর কেউ তার দিকে দাসীর দৃষ্টিতে তাকাল না।\nসে খুব ছোটবেলাতেই নিজের পরিবার ছেড়েছিল, বছরের পর বছর একসাথে থাকতে থাকতে সে সেই স্নেহময়ী মহিলাকে নিজের প্রকৃত মা মনে করতে লাগল, যতক্ষণ না সে ঘটনাক্রমে তার পূর্বতন গোষ্ঠীর লোকদের সাহায্যের হাত বাড়িয়ে দিল — দাসদের সাথে জোটবদ্ধতাকে চরম ঘৃণা করা শাসনকর্তা দম্পতি তৎক্ষণাৎ তাকে পরিত্যাগ করল।\nভাগ্য নিষ্ঠুরভাবে তার অপরিবর্তিত আসল রূপ প্রকাশ করল, রাতারাতি সে বন্দী হয়ে গেল, খাঁচার মধ্যে ঘৃণা পুষে পুরো যৌবনকাল কাটিয়ে দিল।\nযখন কারাগারে ক্ষয়রস বিস্ফোরিত হলো, সে আবিষ্কার করল এই কালো তরল শিকল ক্ষয় করতে পারে, অবশেষে প্রতিশোধের দেবী কারাগার থেকে মুক্ত হলো, এবং পুনরায় আবির্ভূত হওয়ার সময় সে শাসনকর্তার মস্তক দিয়ে তিরো জাতির সম্পূর্ণ মুক্তি অর্জন করল।\nতার বাকি জীবন সে সেই সব প্রাক্তন দাস-মালিকদের শিকার করে কাটিয়ে দিল, যতক্ষণ না সে একটি নামহীন, স্তুতিগাথা খোদাই করা সমাধিতে পরিণত হলো।"
