  CollectionHall_57636_Title = {
    Text = "অন্ধকারের বাসিন্দা"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:পরিচিতি>\nসেই যুগে বেশিরভাগ নারী যুদ্ধক্ষেত্রে সেবিকা হিসেবে উপস্থিত হলেও, তিনি জীবদ্দশায় ছিলেন একজন সাহসী যোদ্ধা এবং এ নিয়ে তিনি গর্বিত ছিলেন।\nতিনি দৃঢ়ভাবে বিশ্বাস করতেন যে তাঁর মাতৃভূমি পবিত্র, এবং অন্যান্য ভূখণ্ডের উপর মাতৃভূমির বিজয় বিশ্বে এক উজ্জ্বল ভবিষ্যৎ বয়ে আনবে।\nএক তীব্র যুদ্ধে একজন নবীন সৈনিককে বাঁচাতে গিয়ে তিনি গুরুতরভাবে আহত হন। পরে কোনোমতে বেঁচে গেলেও, তাঁর পায়ে স্থায়ী পঙ্গুত্বের পরিণতি রয়ে যায়। মাতৃভূমির সেবা চালিয়ে যেতে তিনি সেনাবাহিনী ত্যাগ করেননি, বরং সম্মুখ বাহিনী থেকে সরে এসে নবীন সৈনিকদের প্রশিক্ষক হিসেবে দায়িত্ব নেন।\n\nসময়ের সাথে সাথে, সেই অহংকারী নবীনরা তাদের প্রশিক্ষক একজন \"পঙ্গু\" — এই বিষয়ে অসন্তুষ্ট হয়ে ওঠে, এবং সেনাবাহিনীতে তাঁকে নিয়ে ফিসফিসানি ছড়িয়ে পড়ে।\nএটা বুঝতে পেরে তিনি সেই নবীন সৈনিকের কাছে — যাকে তিনি একদা বাঁচিয়েছিলেন — মতামত জানাতে চেষ্টা করেন — সে এখন একজন মেজর পদে উন্নীত হয়েছে। কিন্তু সেই সৈনিকও অন্যদের মতোই তাঁর আহত পা নিয়ে বিদ্রূপ করে।\nএমন অপমানে ক্রোধে ফেটে পড়ে তিনি সেনাবাহিনী ত্যাগ করেন।\nসেনাবাহিনী ও যুদ্ধক্ষেত্রের বাইরে এসে, তিনি অবশেষে বিশ্বের পূর্ণ চিত্র দেখতে পান: \"যুদ্ধের বীর\" স্বদেশবাসীর দ্বারা পরিত্যক্ত, এবং যে \"মুক্তি\" নিয়ে তিনি একদা গর্বিত ছিলেন তা স্থানীয় অধিবাসীদের জন্য কেবল ঔপনিবেশিক শাসন ও দুর্ভোগই বয়ে এনেছে।\nতাঁর অন্তর্জগৎ আমূল বদলে যায়। এরপর তিনি সর্বান্তকরণে প্রকৃত মুক্তির কাজে নিজেকে নিয়োজিত করেন, তীব্র ন্যায়বোধ ও অপরাধবোধ তাঁকে সত্যিকারের \"সঠিক\" কাজ করতে পথ দেখায়।\nদুর্ভাগ্যবশত, আহত পায়ের ক্ষত কখনো সারেনি, এবং প্রায়শ্চিত্ত সম্পন্ন হওয়ার আগেই তিনি যন্ত্রণায় মৃত্যুবরণ করেন।\nপুনরায় জাগ্রত হওয়ার পর তাইসির প্রতি কৃতজ্ঞতায় আবদ্ধ হয়ে, তিনি সর্বদা আরান গোত্রের ধারাবাহিকতা রক্ষায় সর্বাত্মক সহায়তা করে চলেছেন।"
  },
