  CollectionHall_57638_Desc = {
    Text = "<Title:পরিচিতি>\nএককালে প্রাচীন রোমের গোলেম, তারকা গ্ল্যাডিয়েটর এবং শেষ একমাত্র যোদ্ধা ছিল।\nসম্রাট ক্যালিগুলার উন্মাদ ইচ্ছা পূরণের জন্য সৃষ্ট, তার সকল রাজনৈতিক প্রতিদ্বন্দ্বীকে নির্মূল করেছিল: চাচা, ভাই, বোন...\nকিশোর সম্রাট আত্মীয়দের লাশের স্তূপের সামনে হাঁটু গেড়ে বসে, দুই হাত উঁচু করে, একই সাথে কাঁদছিল আর হাসছিল।\nইউউহাশি বিভ্রান্ত হয়েছিল: গোলেম কাঁদতে পারে, হাসতে পারে, কিন্তু একই সাথে অট্টহাসি হাসতে হাসতে অশ্রুধারা বর্ষণ করতে পারে না।\nপরে, অত্যাচারী সম্রাটকে মৃত্যুদণ্ড দেওয়া হয়। মৃত্যুদণ্ডের আগে, সে ইউউহাশিকে জড়িয়ে ধরেছিল।\nকিন্তু সে কিছুই বলেনি।\nমালিকহারা এই অস্ত্র তারপর থেকে অবিরাম ভবঘুরে হয়ে ঘুরে বেড়াচ্ছে, যতক্ষণ না পরবর্তী মালিকের দেখা পায়।\nসে এখনও মানুষদের নিয়ে বিভ্রান্ত।"
  },
