  CollectionHall_57639_Desc = {
    Text = "<Title:পরিচিতি>\n「লুন্ডিনিয়ামের সবচেয়ে উজ্জ্বল মুক্তা」 হিসেবে প্রশংসিত, তার প্রতিটি কথা ও কাজ সকলের দৃষ্টি আকর্ষণ করে।\nএকসময় সবচেয়ে দুষ্ট দেবতার সাথে চুক্তি করেছিলেন, আবার নিজের 「মৃত্যু」র মাধ্যমে নতুন জীবন লাভ করেছেন।\nতার পরিচয় নিয়ে মানুষের মধ্যে নানা মতভেদ রয়েছে।\nসমাজের বিশিষ্ট নারী, উপপত্নী, ব্যবসায়ী, রাজনীতিবিদ, ফ্যাশনের রানি...\nতার প্রকৃত রূপ অনেক আগেই অস্পষ্ট হয়ে গেছে।\nঅথবা, এই পরিবর্তনশীলতাই তার আসল পরিচয়?"
