  CollectionHall_57640_Desc = {
    Text = "<Title:পরিচিতি>\nএককালে প্রাচীন রোমের এক অভিজাত পরিবারের কন্যা ছিলেন, তাঁর পিতা একটি গ্ল্যাডিয়েটর প্রশিক্ষণ শিবির পরিচালনা করতেন।\nচারপাশে শক্তিশালী গ্ল্যাডিয়েটর দাসদের নিয়ে কাপুয়ায় দাপটের সাথে রাজত্ব করতেন, কেউ তাঁর পথে দাঁড়াতে সাহস করত না।\nপরিহাসের বিষয় হলো, শেষ পর্যন্ত তাঁকে সবচেয়ে ঘৃণিত দাসের কাছে নিজেকে হত্যা করার জন্য অনুনয় করতে হয়েছিল।\nআরও পরিহাসের বিষয়, জাগ্রত সত্তা হওয়ার পর, দুর্ভাগ্যক্রমে সেই 「দাস」-এর সাথে আবার ক্যাম্পাসে দেখা হয়ে গেল।\nসহজেই অনুমান করা যায়, তাদের এই পুনর্মিলন মোটেও কোনো আবেগঘন মধুর দৃশ্য ছিল না।"
  },
