  CollectionHall_57641_Desc = {
    Text = "<Title:পরিচিতি>\nনাবিকদের অজ্ঞ প্রথার অধীনে গড়ে তোলা জাহাজের পবিত্র কন্যা, প্রকৃতপক্ষে সে ছিল এক দরিদ্র পরিবারের বিক্রি করা মেয়ে, যাকে সমুদ্রযাত্রার সুরক্ষার জন্য প্রতিদিন মাস্তুলে বেঁধে রাখা হতো।\nস্বাধীনতা ও পছন্দবিহীন জীবন তাকে সুখ-দুঃখহীন করে তুলেছিল, প্রায় আত্মপরিচয়শূন্য, শুধু জাহাজটিই ছিল তার একমাত্র পরিচিত আশ্রয়।\nঅসহায় জীবনে তার উপর সুন্দর প্রার্থনার আশা চাপিয়ে দেওয়া হয়েছিল, নাবিকদের সাথে কথা বলা নিষিদ্ধ থাকায় সে শূন্য দৃষ্টিতে তাকিয়ে থাকতে অভ্যস্ত হয়ে গিয়েছিল, শুধু তীব্রতম ইচ্ছা আর মাস্তুলের পাশে উড়ে বেড়ানো সামুদ্রিক পাখিরাই তার দৃষ্টি আকর্ষণ করতে পারত।\nশেষ পর্যন্ত তার রক্ষিত জাহাজ ক্ষয়জনিত বিপর্যয়ে ভয়াবহ ক্ষয়ক্ষতির শিকার হলে, ক্রোধে উন্মত্ত মানুষেরা তাকে জলে ডুবিয়ে মৃত্যুদণ্ড দিয়েছিল।"
