  CollectionHall_57642_Desc = {
    Text = "<Title:পরিচিতি>\nপশ্চিম দ্বীপের একজন ভাস্কর্য শিল্পী।\nশোনা যায় সম্ভ্রান্ত পরিবারে জন্মগ্রহণ করেছিলেন, কিন্তু শিল্পের সাধনায় পরিবারের সাথে সম্পর্ক ছিন্ন করে একাই পশ্চিম দ্বীপে পাড়ি জমান এবং বিখ্যাত ভাস্কর্য মাস্টার অগাস্তের শিষ্যত্ব গ্রহণ করেন।\nহতাশাজনক রকমের প্রতিভার অধিকারী হওয়া সত্ত্বেও, শিল্প ইতিহাসে তাঁর নাম কোথাও লেখা হয়নি।\nজাগ্রত সত্তায় পরিণত হওয়ার পর, ভাস্কর্য ও খোদাই সম্পর্কে নতুন উপলব্ধি লাভ করেন এবং সকলের পরিচিত সেই 「উন্মাদ শিল্পী」 শ্রেণির একজন হয়ে ওঠেন।\nগোপনরক্ষককে নতুন অনুপ্রেরণার উৎস হিসেবে দেখেন, গোপনরক্ষকের দিকে তাকানোর দৃষ্টিতে সবসময় এক আভাস অদ্ভুত কোমলতা ফুটে ওঠে।\nওহ, সেটা হলো একবিন্দু খাদ না মেশানো, প্রিয় উপকরণকে খুঁটিয়ে দেখার দৃষ্টি।"
