  CollectionHall_57643_Desc = {
    Text = "<Title:পরিচিতি>\nএককালে প্রাচীন আকিমেনিড রাজবংশের সেবিকা ছিল।\nশতবর্ষীয় ভোজসভায় অতিথি সেবার জন্য নির্বাচিত না হওয়ায়, হ্রদে তার সঙ্গীকে ডুবিয়ে মেরে তার স্থান দখল করেছিল।\nশেষ পর্যন্ত ভোজসভায় কুৎসিত সবুজ দানবে পরিণত হয়েছিল।\nচটপটে বুদ্ধি ও ক্ষিপ্র দেহের অধিকারী, একসাথে দশটি থালা নিয়ে জনতার মাঝে ছুটে বেড়াতে পারে।\nসুস্বাদু খাবারের সংজ্ঞা সমকালীন খাদ্য সংস্কৃতির সাথে মারাত্মকভাবে সামঞ্জস্যহীন।\nমাঝে মাঝে সন্দেহ করে যে হত্যার শাস্তি হিসেবেই তাকে দানবে পরিণত করা হয়েছে।\nকিন্তু কখনোই শিক্ষা নেবে না, দ্রুতই কিছুই ঘটেনি এমন ভান করবে।\nসর্বোপরি, ইতিহাস থেকে এরিভানবাসীরা যে একমাত্র শিক্ষা নিতে পারে তা হলো:\nএরিভানবাসীরা কখনোই শিক্ষা নেয় না।"
