  CollectionHall_57644_Desc = {
    Text = "<Title:পরিচিতি>\n@2-এ অবস্থিত কারাগারের প্রহরী, বন্দীদের নির্যাতন করাই তার আনন্দ।\nঊর্ধ্বতন কর্তৃপক্ষ তাকে প্রতিশ্রুতি দিয়েছিল যে তিন বছর পর তাকে লন্ডিনিয়ামে ফিরিয়ে আনা হবে, কিন্তু ক্ষয়ীভবনের অবনতি এবং ভূশিরার পরিবর্তনের ফলে, সে এই সুদূর ভূমিতে বিস্মৃত হয়ে রইল।\nতরুণীটি হতাশ হয়নি। সে ধ্বংসস্তূপে অবিচল থেকে সেই দিনের অপেক্ষায় রইল যেদিন তাকে ফিরিয়ে আনা হবে।\nশেষ বন্দীটি মারা যাওয়ার পর, সে দ্বীপের একমাত্র জীবিত প্রাণী হয়ে রইল।\nবন্দীহীন প্রহরী আর বন্দীর মধ্যে পার্থক্যই বা কী?\nতরুণীটি ভাবতে অস্বীকার করল। সে এখনও সেই দিনের অপেক্ষায় রইল যেদিন তাকে ফিরিয়ে আনা হবে।"
