  CollectionHall_57646_Desc = {
    Text = "<Title:পরিচিতি>\nফ্রান্সিসের পোষা 「পোষ্য」।\nমূলত 「লিসা」 নামের একজন প্রাণবন্ত তরুণী ছিল, ভাস্কর সংঘের রূপান্তরের মাধ্যমে মানব ও পশুর সেলাই করা এক বিকৃত রূপে পরিণত হয়েছে। পরে লিলি তাকে দত্তক নেয় এবং সে সাময়িকভাবে পাগলাগারদে বসবাস করছে।\nমানুষের বাহ্যিক রূপ ও কণ্ঠস্বর হারালেও, কুম এখনও লিসার আংশিক মানসিক চেতনা ধরে রেখেছে এবং সাধারণ অঙ্গভঙ্গির মাধ্যমে নিজের অভিপ্রায় প্রকাশ করতে পারে।\nসে নিজের পছন্দ নিজেই করেছে।"
