  CollectionHall_57647_Desc = {
    Text = "<Title:পরিচিতি>\nঅজানা উৎসের একজন ঔষধ প্রস্তুতকারক, বর্তমানে ভাস্কর সমিতির বৈজ্ঞানিক উপদেষ্টা।\nশোনা যায় তাঁর মা ছিলেন একজন গ্রাম্য কৃষক নারী, যিনি মহান সর্প দেবতার সন্তান ধারণের জন্য নির্বাচিত হয়েছিলেন।\nমায়ের কাছ থেকে অ্যালবিনিজম এবং সদয় স্বভাব উত্তরাধিকারসূত্রে পেয়েছেন, হার্বার্টের একমাত্র বিশ্বস্ত বন্ধু।\nশারীরবিদ্যা, অ্যারোমেটিক হাইড্রোকার্বন এবং বেলাডোনা পোড়ানোর সুগন্ধের প্রতি অত্যন্ত আগ্রহী।\nবিপুল রচনার অধিকারী, তাঁর প্রতিনিধিত্বমূলক কাজ হলো বিষবিদ্যার বাইবেল হিসেবে খ্যাত 《ঔষধ সংকলন》।\nদীর্ঘদিন ধরে বিভিন্ন বিষাক্ত পদার্থে নিমজ্জিত থাকায়, এমনকি তাঁর নিঃশ্বাসেও তীব্র বিষ রয়েছে। তাঁর থেকে দূরে থাকুন——এটাই লেখকের একমাত্র পরামর্শ।"
  },
