  CollectionHall_57648_Desc = {
    Text = "<Title:পরিচিতি>\nওয়ার্ড ফিলিপসের ছাত্র, মিসাগের প্রথম গোপনরক্ষক।\nবছরের পর বছর ভূগর্ভের গোপন এলাকায় অবস্থান করেন, অত্যন্ত অল্পসংখ্যক মানুষই তার অস্তিত্ব সম্পর্কে জানে।\nঅসাধারণ মানসিক শক্তির অধিকারী, বহু বছর ধরে বিশেষ গুপ্তবিদ্যার মাধ্যমে জীবন ধারণ করে আসছেন, যাতে মিসাগের নিরাপত্তা নিশ্চিত থাকে।\nভবিষ্যতের পরিবর্তনে গোপনরক্ষকের গুরুত্বপূর্ণ ভূমিকার পূর্বাভাস পেয়ে, ব্যতিক্রমীভাবে গোপনরক্ষককে যেকোনো সময় তার সাথে যোগাযোগের অনুমতি দিয়েছেন।\nএটি যেমন প্রশিক্ষণ, তেমনই পর্যবেক্ষণও।"
  },
  CollectionHall_57648_LockTip = {
    Text = "অধ্যায় 2: 「মোমের প্রতিকৃতির নামে」 সম্পন্ন করো"
