  CollectionHall_57649_Desc = {
    Text = "<Title:পরিচিতি>\nদাও-হাই গোত্রের ক্ষীণ রক্তধারা বহনকারী একজন মানুষ, প্রাচীন ওর্ন পরিবারে জন্মগ্রহণ করেছিল। এই পরিবারে এক সময় এক বিপর্যয় ঘটেছিল — কিছু সদস্য প্রাপ্তবয়স্ক হওয়ার পর ধীরে ধীরে বিকৃত চেহারার দানবে রূপান্তরিত হতো এবং শেষ পর্যন্ত যন্ত্রণাদায়ক মৃত্যুবরণ করত। তার পিতাও এই রোগের পরিবর্তন সহ্য করতে না পেরে তার জন্মের পর আত্মহত্যা করেছিলেন।\nশৈশব থেকেই মায়ের ঘৃণা ও সমবয়সীদের অপমানের মধ্যে বেড়ে ওঠায় তার স্বভাব অন্ধকার ও নিঃসঙ্গ হয়ে গিয়েছিল।\nষোলো বছর বয়সে, চাচার রেখে যাওয়া পাণ্ডুলিপিতে পরিবারের মহান রক্তধারার ইঙ্গিত দেখে সে মানসিক বিজয় লাভ করেছিল। সারাদিন কল্পনা করত যে একদিন সে অলৌকিক শক্তি পাবে, চারপাশের মানুষদের নির্যাতনকে নিয়তি-নির্বাচিত সন্তানের অবশ্যম্ভাবী পরীক্ষা বলে মনে করত, এবং অপেক্ষা করত সেই দিনের জন্য যখন তারা তার কাছে করুণা ভিক্ষা করবে।\nপ্রাপ্তবয়স্ক হওয়ার সময় সে রূপান্তরকে স্বাগত জানাতে একটি গুহায় লুকিয়েছিল, কিন্তু অর্ধ-মানব অর্ধ-মৎস্য অবস্থায় আটকে গিয়েছিল। মা চিৎকার করে তাকে তাড়িয়ে দিয়েছিল এবং সে আর ঘরে ফিরতে পারেনি।\nশেষ পর্যন্ত সে নিজের গোষ্ঠী খুঁজে পাওয়ার আশায় সমুদ্রে ঝাঁপ দিয়েছিল, কিন্তু অপূর্ণ বিকশিত ফুলকার কারণে ডুবে মারা গিয়েছিল।"
  },
