  CollectionHall_57650_Desc = {
    Text = "<Title:পরিচিতি>\nরাজ্যের সবচেয়ে প্রাচীন ক্যাভেন্ডিশ পরিবার থেকে আগত, একসময় বাবা-মায়ের আদরের ধন ছিল, কিন্তু দুর্ভাগ্যবশত ফিউশন ইরোশনে আক্রান্ত হয়।\nতিন বছর ধরে ভূগর্ভে তালাবদ্ধ অবস্থায়, রক্তের প্রতি তার তৃষ্ণা দিন দিন তীব্রতর হতে থাকে।\nতার ভাই তখন পূর্ব অঞ্চলের একাকী ভবঘুরে ও পতিতাদের খুঁজে আনার নির্দেশ দেয়, যাতে সেগুলো বোনের প্রতিদিনের 'খাদ্য' হিসেবে ব্যবহার করা যায়।\nএতে শহরে আতঙ্ক ছড়িয়ে পড়ে, পুলিশ বিভাগ সর্বশক্তি নিয়ে মাঠে নামে এবং অবশেষে ভাই-বোন দুজনকেই গ্রেপ্তার করে।\nএভাবেই লন্ডিনিয়াম শহরকে কাঁপিয়ে দেওয়া 'ভ্যাম্পায়ার ঘটনা' অবশেষে সমাপ্তি লাভ করে।"
  },
  CollectionHall_57650_LockTip = {
    Text = "「লে」 জাগিয়ে তোলো"
