  CollectionHall_57650_Title = {Text = "লি"},
  CollectionHall_57651_Desc = {
    Text = "<Title:পরিচিতি>\nলন্ডিনিয়ামের পূর্বাঞ্চলের একজন বস্ত্র কারখানার শ্রমিক।\nওরিপ্যাথি সংক্রমণের কারণে ভাস্কর সমিতি তাকে অপহরণ করে মোমের মূর্তিতে পরিণত করে।\n「24」 একদিকে যেমন পরীক্ষার ক্রমিক নম্বর, তেমনি এটি তার প্রথমবার নির্ণিত ব্যক্তিত্বের সংখ্যাও।\nলেখক যখন এই নথি লিপিবদ্ধ করছেন, তার ব্যক্তিত্বের সংখ্যা ক্রমাগত বৃদ্ধি পাচ্ছে।\nসময়ের সাথে সাথে, 「24」-দের নিয়ে গঠিত রাজ্য নিশ্চিতভাবে জনসমৃদ্ধ ও জাঁকজমকপূর্ণ হয়ে উঠবে।"
  },
  CollectionHall_57651_LockTip = {
    Text = "স্পেশাল অপস সম্পন্ন করো: 「প্রশান্ত বিভাজন」"
