  CollectionHall_57651_Title = {Text = "\"২৪\""},
  CollectionHall_57652_Desc = {
    Text = "<Title:পরিচিতি>\nজীবিত থাকাকালীন বাবার সাথে ফিউশন ইরোশনে আক্রান্ত হয়েছিল, পরিবারের কষ্টের মধ্যেও সবসময় বাধ্য হয়ে চিকিৎসা সহ্য করে গেছে।\nএকই সাথে স্বামী ও মেয়েকে হারিয়ে মায়ের স্বভাব সম্পূর্ণ বদলে যায়। এলওয়ার্থের অনুসন্ধানের সময় ভুলবশত ল্যান্টার্ন চার্চের আচার-অনুষ্ঠানে প্রবেশ করে, যা ঘটনাক্রমে লিলিকে জাগিয়ে তোলে। অস্বাভাবিক জাগরণের কারণে লিলি একটি নির্জীব পুতুলে পরিণত হয়, শুধুমাত্র আদেশ শুনলেই নড়াচড়া করে।\nফিউশন ইরোশনের কারণে মা লিলির চেহারা ভুলে গিয়েছিল, জাগ্রত লিলিকে দানব মনে করে ক্রমাগত তার উপর পরীক্ষা-নিরীক্ষা চালাত, আসল মেয়ের পুনরুত্থানের আশায়।\nশেষ পর্যন্ত গোপনরক্ষকের সাথে মিসাগে যাত্রা করে, গোপনরক্ষককে মা বলে ডাকে এবং তার উপর অত্যন্ত নির্ভরশীল।"
