  CollectionHall_57653_Desc = {
    Text = "<Title:পরিচিতি>\nরজার্সের মোমের পুতুল।\n\nট্রেনের কামরায় জোরে চিৎকার করা সেই বাচ্চাগুলোর মতোই, এটি একটি আদুরে বিগড়ে যাওয়া প্রাণী।\nযার উপর নির্ভর করে, তা হলো সেই ধূসর-সবুজ চোখ দুটো——এগুলোই 「মোমের মূর্তি মহাশয়」 রজার্সের জন্য রেখে যাওয়া একমাত্র জিনিস।\n「24」-এর কৃত্রিম গোপনক্ষেত্রে এক অপ্রতিরোধ্য শক্তির মুখোমুখি হয়ে চ্যাপ্টা জর্জে পরিণত হয়েছিল, এবং সফলভাবে রজার্সের ক্রোধ জাগিয়ে তুলেছিল।"
  },
  CollectionHall_57653_LockTip = {
    Text = "অধ্যায় 2: 「মোমের প্রতিকৃতির নামে」 সম্পন্ন করো"
