  CollectionHall_57653_Title = {
    Text = "জর্জ"
  },
  CollectionHall_57654_Desc = {
    Text = "<Title:পরিচিতি>\nলিলিয়ান দরিদ্রাশ্রমের এতিম, এবং জেনকিনের সবচেয়ে প্রিয় বন্ধু।\nভাস্করদের সমিতি দ্বারা রূপান্তরিত হয়েছিল, এবং নিজের চোখে অন্য এতিমদের মর্মান্তিক মৃত্যু প্রত্যক্ষ করেছিল, নিজের বেঁচে থাকা ও নীরবতার জন্য অপরাধবোধে ভুগত।\nশেষ পর্যন্ত ঘণ্টা টাওয়ার থেকে লাফ দিয়ে সম্পূর্ণ মুক্তি পেয়েছিল।\nসবসময় একটি পুতুল ভালুক বুকে জড়িয়ে রাখত, সে এর নাম দিয়েছিল 「পপি」।\nউপহার, ছোট স্কার্ট এবং সোনালি ক্যান্ডি পছন্দ করত।\nঅন্ধকারকে একটু ভয় পেত, সবসময় 「পপি」 জড়িয়ে ধরেই ঘুমাতে পারত। তুমি যদি তার জন্য একটি দোলনা সংগীত গাইতে পারো, মেয়েটি চিরকাল তোমাকে কৃতজ্ঞ থাকবে, ভালোবাসবে।\nঠিক যেমন জেনকিন একসময় তার জন্য করেছিল।"
  },
