  CollectionHall_57716_Desc = {
    Text = "<Title:পরিচিতি>\nমূলত একজন গবেষক যিনি স্বয়ংক্রিয় পুতুল তৈরিতে আচ্ছন্ন ছিলেন, তিনি ড্যাফোডিলের কাছ থেকে সিলভার কোরকে কেন্দ্র করে একটি শক্তি উপাদান পেয়েছিলেন।\nশক্তি উপাদানের প্রতি তাঁর গবেষক বন্ধুর লোভের কারণে দুজনের মধ্যে বারবার ঝগড়া হয়, এবং শেষ পর্যন্ত চূড়ান্ত বিচ্ছেদের মতো ক্রোধান্বিত ছিনতাইয়ে পরীক্ষাগারে বিস্ফোরণ ঘটে। কেন জানি না, পুতুলের দেহে জেগে ওঠা তিনি আতঙ্কিত হয়ে উপলব্ধি করলেন: প্রাণহীন হওয়া উচিত এই স্বয়ংক্রিয় পুতুলের মধ্যে, তাঁর ছাড়াও আরেকটি চেতনা রয়েছে।\nকোন বিশ্বাস নিয়ে তিনি তাঁর বন্ধুকে জ্বলন্ত ধ্বংসস্তূপ থেকে উদ্ধার করেছিলেন, আর কোন বিশ্বাস নিয়ে তিনি শহরতলিতে পৌঁছেছিলেন, তা আর কেউ জানে না। এই অজানা যান্ত্রিক প্রতিভা এভাবেই পৃথিবী থেকে হারিয়ে গেলেন, পেছনে রেখে গেলেন শুধু বিস্ফোরণের একটি সংবাদ, মাটিতে ছড়িয়ে থাকা যন্ত্রাংশ, আর একটি অবশিষ্ট সিলভার কোর।\nএর থেকে যা জাগ্রত হলো, সেটি আসলে কেমন অস্তিত্ব?"
  },
  CollectionHall_57716_LockTip = {
