  CollectionHall_57717_Desc = {
    Text = "<Title:পরিচিতি>\n@2-এর দূত ও প্রতিনিধি, প্রায়ই মানবরূপ ধারণ করে পৃথিবীতে বিচরণ করেন।\nএক খাঁটি দানব—ভবিষ্যৎ নেই, বিশ্বাস নেই, আদর্শ নেই।\nলোভকে টোপ হিসেবে ব্যবহার করেন, বিশৃঙ্খলা তাঁর খাদ্য, মানুষকে প্রতারণা ও প্রলোভিত করতে মত্ত।\nনিয়মকানুন নিয়ে কারসাজিতে পারদর্শী, তাঁর সাথে চুক্তি করা প্রতিটি মানুষ শেষ পর্যন্ত সর্বস্বান্ত হয়েছে।\nসবচেয়ে চতুর আইনজীবীও তাঁর কাছ থেকে সামান্যতম সুবিধা আদায় করতে পারেনি।\nমাঝে মাঝে শিশুর রূপ ধারণ করেন, তবে এতে কেউ তাঁর প্রতি সতর্কতা শিথিল করে না।\nসর্বোপরি, তাঁর ভয়াবহতা কখনোই বাহ্যিক রূপে সীমাবদ্ধ নয়।"
  },
