  CollectionHall_57718_Desc = {
    Text = "<Title:পরিচিতি>\nমনোরোগ বিশেষজ্ঞ, মৃগীরোগ, হিস্টিরিয়া এবং উদ্বেগজনিত অনিদ্রা প্রভৃতি রোগের চিকিৎসায় বিশেষজ্ঞ।\nসম্মোহন পদ্ধতিতে রোগীদের মনের কথা বের করে আনতে তিনি অত্যন্ত দক্ষ।\nশোনা যায়, তাঁর রোগীরা সকলেই বিভিন্ন ধরনের 「শৈল্পিক」 আত্মহত্যার মাধ্যমে জীবনাবসান করেছে, কিন্তু পুলিশ আসার আগেই তিনি সর্বদা পরিচয় বদলে নতুন করে কার্যক্রম শুরু করতে সক্ষম হন।\nঅনেক বিশিষ্ট ব্যক্তি তাঁর সুনামে আকৃষ্ট হয়ে তাঁর ক্লিনিকে গিয়েছেন, তাঁকে বর্ণনা করা হয় 「অর্ধেক লন্ডিনিয়াম শহরের গোপন রহস্যের অধিকারিণী」 হিসেবে।\nরজার্স তাঁর দীর্ঘদিনের ক্লায়েন্ট ছিলেন — সম্ভবত, তাঁর সেই অস্বাভাবিক শৈল্পিক আবেগও এই চিকিৎসকের সাথে সম্পর্কিত?"
