  CollectionHall_57719_Desc = {
    Text = "<Title:পরিচিতি>\nশ্রেষ্ঠত্বের সাধনায় নিবেদিত একজন মোমের মূর্তি শিল্পী, রজার্স মোমের জাদুঘরের বর্তমান কিউরেটর।\nশৈশবে তোতলামির কারণে সবার কাছে উপেক্ষিত হতেন, তাঁকে নিয়ে ঠাট্টা করা হতো যে 'টাকা ছাড়া তার আর কিছুই নেই'।\nউচ্চপদস্থ পিতা, মানসিকভাবে বিপর্যস্ত মাতা, আর সেই সাথে সারা দেশ কাঁপানো অপহরণ কাণ্ড……\nএইসব মর্মান্তিক ঘটনার প্রভাবে, রজার্স সকলের প্রত্যাশা অনুযায়ী তাঁর মাতাকে ছাড়িয়ে গিয়ে স্কারবরোর সবচেয়ে বিখ্যাত পাগলে পরিণত হলেন।\nভাস্কর সমিতির মহিলাদের মধ্যে সবচেয়ে জনপ্রিয় সদস্য, একজন অত্যন্ত স্থিতিশীল মেজাজের ভদ্রলোক — যতক্ষণ না শিল্প নিয়ে কথা ওঠে।"
  },
  CollectionHall_57719_LockTip = {
