  CollectionHall_57720_Desc = {
    Text = "<Title:পরিচিতি>\nমা ছিলেন একজন অসাধারণ মেকানিক, দক্ষতা বেশি আর খরচ কম হওয়ায় সবার কাছে জনপ্রিয় ছিলেন।\nআট বছর বয়সে বাবা সমুদ্রে গিয়ে আর কখনো ফেরেননি, তারপর থেকে মায়ের সাথে মেরামতের দোকান চালিয়ে একে অপরের উপর নির্ভর করে বেঁচে ছিলেন। দুজনে জমানো যন্ত্রাংশ দিয়ে একচাকার মোটরসাইকেল তৈরির চেষ্টা করতেন, একদিন একসাথে সেটায় চড়ে অভিযানে বের হওয়ার স্বপ্ন দেখতেন — মায়ের তারুণ্যের স্বপ্ন পূরণ করতে।\nতেরো বছর বয়সে মা অসুস্থতায় মারা যান। মোটরসাইকেল সম্পূর্ণ করার জন্য আরও যন্ত্রাংশ জোগাড় করতে উচ্চ পারিশ্রমিকের জাহাজের কাজ গ্রহণ করেন।\nফেরার পথে ঝড়ের কারণে জাহাজ দুর্ঘটনাক্রমে মহাঘূর্ণির স্রোতে আটকে যায়। জাহাজের একমাত্র ডাইভিং স্যুটটি প্রিয় বন্ধুকে দিয়ে দেন, তারপর মায়ের রেখে যাওয়া নটিলাস পেন্ড্যান্ট আঁকড়ে ধরে ক্ষয়কারী স্রোতের মধ্যে মৃত্যুবরণ করেন। শুধু ধ্বংসাবশেষ আর সিলভার কোর সমুদ্রস্রোতে ভেসে ভেসে যাত্রা করতে থাকে।"
  },
  CollectionHall_57720_LockTip = {
