  CollectionHall_58148_Desc = {
    Text = "<Title:পরিচিতি>\nসমুদ্রযাত্রার প্রধান পুরোহিতের লালিত ছোট্ট রাজকুমারী, যাকে 'পবিত্র কন্যা'ও বলা হয়।\nশৈশব থেকেই আদরে-যত্নে বড় হওয়া, সত্যিকারের এক অভিজাত নারী। তার হাতের ছোট্ট ছাতাটি কেবল তার কোমল ত্বককেই রক্ষা করে না, সকল অপবিত্র ও অশুভ বস্তুকেও দূরে রাখে।\nসে ভালো করেই জানে যে, সে নিজেও এক ধরনের 'অশুভ'-এর ফসল — তার জন্ম প্রকৃতির নিয়মে হয়নি, বরং 'মাতা' হওয়ার জন্য, ভবিষ্যদ্বাণীর সন্তানকে জন্ম দেওয়ার জন্যই তাকে সৃষ্টি করা হয়েছে।\nঅফুরন্ত মিষ্টান্ন, সর্বাধুনিক পোশাক, অসংখ্য পরিচারক তাকে ঘিরে... সে এই বিলাসবহুল জাগতিক জগতে বিচরণ করে, অন্তরের উদ্বেগ ও অস্থিরতাকে শক্ত করে আটকে রাখে।\nএই প্রচেষ্টা শেষ পর্যন্ত ব্যর্থ হয়, কারণ মুক্ত হৃদয় কোনো আপস মেনে নেয় না।"
  },
