  CollectionHall_59455_Desc = {
    Text = "<Title:পরিচিতি>\nযে পুরুষকে 「পরম সৌভাগ্যের অধিকারী」 বলে প্রশংসা করা হয়।\nএমন প্রতিভা নিয়ে জন্মালে জুয়াড়ি হওয়াটাই তো স্বাভাবিক।\nতবে সে একই সাথে বেশ দক্ষ একজন গোয়েন্দাও বটে।\nশুধু তাই নয়, সে একজন নিঃস্ব কপর্দকশূন্য মানুষ, কারণ জেতা টাকা সে সবচেয়ে দ্রুত গতিতে উড়িয়ে দিতে পারে।\nস্ববিরোধী, জটিল। এই পুরুষ সম্পর্কে আমাদের মূল্যায়ন এটুকুই।\nভাগ্যদেবী তাকে পছন্দ করেন, সেই রহস্যময় 「N」 তাকে পছন্দ করে, এমনকি সবচেয়ে কৃপণ সরাইখানার মালিকও তাকে কিছুটা ছাড় দিতে রাজি।\nসবাই তাকে পছন্দ করে, কিন্তু সে কখনো এতে থেমে যায়নি, বরং নতুন এক দুঃসাহসিক খেলা শুরু করে।\nসে শুধু অজানাকেই পছন্দ করে।"
  },
  CollectionHall_59455_LockTip = {
    Text = "বিশেষ অপস: 「শুভ শিকার!」 সম্পন্ন করো"
  },
  CollectionHall_59455_Title = {
    Text = "রাইকার"
  },
  CollectionHall_59456_Desc = {
    Text = "<Title:পরিচিতি>\nএক পতনোন্মুখ অভিজাত পরিবারে জন্মগ্রহণ করেন। জন্মগতভাবে গুরুতর হাঁপানিতে আক্রান্ত হলেও বাবা-মায়ের কাছ থেকে সবসময় অকুণ্ঠ ভালোবাসা পেয়েছেন।\nরোগযন্ত্রণায় ঘরবন্দি থাকতে থাকতে তাঁর মনে প্রায়ই আত্মহননের চিন্তা উঁকি দিত। তাঁর মন ভালো করতে বাবা-মা তাঁকে নিয়ে একবার দূরে বেড়াতে গিয়েছিলেন, কিন্তু দুর্ভাগ্যক্রমে সেই যাত্রায় তিনি ক্ষয়রোগে আক্রান্ত হন।\nবাড়ি ফেরার পর, অপরাধবোধে ভারাক্রান্ত বাবা-মা তাঁকে একটি পুনর্বাসন কেন্দ্রে ভর্তি করেন, এবং একদিকে চিকিৎসার খরচ জোগাতে সমুদ্রপথে ব্যবসায় বেরিয়ে পড়েন, অন্যদিকে বিশ্বজুড়ে ঘুরে চিকিৎসার উপায় খুঁজতে থাকেন।\nক্ষয়রোগের আক্রমণ বাড়ার সাথে সাথে তাঁর মৃত্যুকামনাও তীব্রতর হতে থাকে, কিন্তু বাবা-মায়ের বোঝা হয়ে দাঁড়ানোর অপরাধবোধ বুকে নিয়ে, তাঁদের আরও কষ্ট না দেওয়ার জন্য তিনি মৃত্যু ও মুক্তির আকাঙ্ক্ষা চেপে রাখতেন।\nবাবা-মা তাঁকে দেখতে আসার পথে জাহাজডুবিতে নিহত হওয়ার সংবাদ পাওয়ার পর, পৃথিবীতে আর কোনো বন্ধন না থাকায় তিনি রাতের আঁধারে নীরবে পুনর্বাসন কেন্দ্র ছেড়ে বেরিয়ে পড়েন, এক পা এক পা করে সমুদ্রের গভীরে এগিয়ে যান।\nসমুদ্রের জল মাথার উপর দিয়ে বয়ে যাওয়ার সেই মুহূর্তে, ত্রিকোণ ক্ষয়চিহ্ন থেকে ঝরে পড়া কালো তরল স্রোতে ভেসে যায়, দীর্ঘদিনের রোগক্লিষ্ট দেহ এক অবর্ণনীয় মুক্তি অনুভব করে — এটাই ছিল প্রথমবার, এবং একমাত্রবার, যখন তিনি অবাধে শ্বাস নিতে পেরেছিলেন।"
  },
