  CollectionHall_62184_Desc = {
    Text = "<Title:পরিচিতি>\nবিশ্বখ্যাত কন্ডাক্টর ও সংগীতশিল্পী। দেখতে তরুণ মনে হলেও, তাঁর পরিচালিত সিম্ফনি কনসার্ট অনেক আগেই বিশ্বজুড়ে সফর করেছে, এবং প্রতিটি পরিবেশনায় দর্শকদের ঢল নামে।\nধ্রুপদী সংগীত জগতের সবচেয়ে প্রসিদ্ধ প্রতিভা হিসেবে, হ্যামলিনের কোনো ব্যক্তিগত তথ্যই কারো জানা নেই, যা পরিদর্শন পরিষদের দৃষ্টি আকর্ষণ করেছিল। দীর্ঘ তদন্তে তারা আবিষ্কার করে যে, হ্যামলিনের পরিবেশনার স্থানগুলো ল্যান্টার্ন চার্চের কার্যক্রমের গতিপথের সাথে অত্যন্ত মিলে যায়।\nতারা সত্য খুঁজে পাওয়ার আগেই, সত্য নিজেই তাদের কাছে এসেছিল — মিসাগে ল্যান্টার্ন চার্চের অনুপ্রবেশের ঘটনায় হ্যামলিন অত্যন্ত গুরুত্বপূর্ণ ভূমিকা পালন করেছিলেন।\nতখনই মানুষ বুঝতে পেরেছিল যে, এই প্রতিভাবান কন্ডাক্টরের প্রকৃত মঞ্চ সবসময়ই ছিল থিয়েটারের বাইরে।"
  },
