  CollectionHall_65509_Desc = {
    Text = "<Title:পরিচিতি>\nপূর্ব অঞ্চলের একজন বখাটে, এবং「24」-এর ছোট বোন।\nতার তিনটি অনন্য দক্ষতা রয়েছে: চুরি-চামারি, ঝগড়া করা এবং বিপদ দেখলেই পালিয়ে যাওয়া।\nকেউই তার কাছ থেকে সামান্যতম সুবিধা আদায় করতে পারে না।\nওহ, হ্যাঁ। তার কাছে「ব্রাউন」নামের একটি ছোট ইঁদুরও আছে যে সবসময় তার সঙ্গে থাকে।\nব্রাউন পরিণত ও স্থিরচিত্ত, জেনকিনের স্বভাবের সাথে চমৎকার পরিপূরক।\nতাই, লন্ডিনিয়ামের পূর্ব অঞ্চলে ক্ষুধার্ত ও শীতার্ত মানুষেরা প্রায়ই ইঁদুর রান্না করার মর্মান্তিক ঘটনা ঘটালেও, জেনকিন কখনো এমন চিন্তা করেনি।"
