  CollectionHall_70839_Desc = {
    Text = "<Title:পরিচিতি>\nতোষামোদ, ধূর্ততা, ভণ্ডামি। লিলিয়ান দরিদ্রাশ্রমের প্রধান যেন একজন আনাড়ি অভিনেতা, লন্ডিনিয়ামের খ্যাতি ও প্রতিপত্তির মঞ্চে এক নগণ্য ভিক্ষুকের ভূমিকায় অভিনয় করে চলেছেন।\nতিনি সর্বত্র ছুটে বেড়ান, বোকার মতো তোষামোদ করে বিশিষ্ট ব্যক্তিদের আঙুলের ফাঁক দিয়ে পড়া সামান্য কিছু অর্থ সংগ্রহ করেন, যা দিয়ে দরিদ্রাশ্রমের কষ্টকর পরিচালনা কোনোমতে চালিয়ে যান। উপহাস আর গালিগালাজ তিনি একাই গিলে নেন, আর কোমল কণ্ঠের গানে দরিদ্রাশ্রমের শিশুদের ঘুম পাড়ান।\nলন্ডিনিয়াম তাদের পরিত্যাগ করেছে, কিন্তু লিলিয়ান দরিদ্রাশ্রম করেনি। সারা প্রস্তুত ছিলেন, তাঁর সাধ্যমতো এই শিশুদের রক্ষা করতে, লন্ডিনিয়ামের কুয়াশা ও হিমশীতল বাতাসের মধ্যে তাদের বাঁচিয়ে রাখতে।\nকিন্তু তাঁর নগণ্য স্বপ্ন ব্যর্থ হলো, তিনি এবং শিশুরা ভাস্কর সমিতির ষড়যন্ত্রে প্রাণ হারালেন। ভাস্কর সমিতির কাছে, তিনি এবং তাঁর লালিত শিশুরা ছিল সেই সুবিশাল প্রাসাদের তুচ্ছ বালুকণা — মূল্যহীন, সৌন্দর্যবর্জিত। তাদের বেঁচে থাকা ছিল গুরুত্বহীন, তাদের মৃত্যু ছিল উল্লেখেরও অযোগ্য।\nতিনি নিজের সবকিছু পুড়িয়ে দিলেন। সেই আলো দ্রুত নিভে গেল, শুধু লন্ডিনিয়ামের বাতাস আগের মতোই হাড়-কাঁপানো শীতল রয়ে গেল।"
  },
