  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.???>\nবিশ্বব্যাপী বিপর্যয় বিশাল ভূখণ্ডকে ধ্বংস করে দিয়েছিল। ভূমিকম্প, বন্যা, চৌম্বক ক্ষেত্রের বিশৃঙ্খলা, জলবায়ু বিপর্যয়— একের পর এক আঘাত এসেছিল। শহর ও জনবসতি জলের নিচে তলিয়ে গেল, আর সমুদ্রের গভীরে চাপা পড়া শিলাখণ্ড নতুন পর্বতশৃঙ্গ হয়ে জেগে উঠল। মানব সভ্যতা চরম ক্ষতির সম্মুখীন হলো।\n\n<Title:A.F.0>\nপুরনো ভূমি সমুদ্রের জলে ডুবে গেল, নতুন ভূমি জলের উপরে জেগে উঠল।\nএই সম্পূর্ণ পরিবর্তিত বিশ্বে, মানুষ পুরনো পঞ্জিকা পরিত্যাগ করল এবং সভ্যতার ধ্বংসাবশেষ সাথে নিয়ে কষ্টকর পুনর্গঠনের পথে এগিয়ে চলল, এক সম্পূর্ণ নতুন যুগে পদার্পণ করল: প্লাবন যুগ।"
  },
