  CollectionHall_70891_Desc = {
    Text = "এক বছরের প্রাক-প্রশিক্ষণ ও অধ্যয়ন শেষে, @3 আনুষ্ঠানিকভাবে গোপনরক্ষকের পদে অধিষ্ঠিত হন এবং জাগ্রত সত্তা ও বিদ্যালয়ের অন্যান্য শক্তিকে নেতৃত্ব দিয়ে ক্ষয়-সম্পর্কিত ঘটনার তদন্ত শুরু করেন।\nসেই বছরই, প্রদীপ চার্চ মিসাগার্ডের অভ্যন্তরীণ গুপ্তচরদের সাথে হাত মিলিয়ে পুনরায় মিসাগার্ডে আক্রমণ চালায়, কৃষ্ণ পুকুরে অস্থিরতা সৃষ্টি করে, চরম দ্বার উন্মোচন করে এবং পরম ইচ্ছার দৃষ্টি আকর্ষণ করে।\nকাদাথ যখন ক্ষয়ে গ্রাস হতে চলেছিল, @3 ত্রিগুণ সত্তার কর্তৃত্ব শোষণ করে দ্বারের অভ্যন্তরে পরম ইচ্ছার দৃষ্টির বিরুদ্ধে মুখোমুখি হন।\nঅবশেষে, পরম ইচ্ছা পুনরায় নিদ্রায় যান এবং কাদাথ রক্ষা পায়।\n@3 আত্মত্যাগ করেন।\nতাঁর সমস্ত সংশ্লিষ্ট নথি ক্ষয়ে বিলীন হওয়ায় সংরক্ষণ অসম্ভব হওয়ায়, মিসাগার্ড ব্যতিক্রমী সিদ্ধান্ত নিয়ে তাঁর জীবদ্দশায় ব্যবহৃত রৌপ্য চাবি সিলমোহর করে বিদ্যালয় ইতিহাস স্মৃতি জাদুঘরে সংরক্ষণ করে, তাঁর কৃতিত্বের স্মরণে।\n%hisorher%-এর নাম কেউ জানে না, কিন্তু K-0617 এই সংখ্যা চিরকাল অমর থাকবে।"
