  CollectionHall_89383_Desc = {
    Text = "নিজেকে কী মিথ্যে বলতে হয়, বিশ্বাস করতে যে নিভে যাওয়া অঙ্গারের তলায় এখনো জীবন জ্বলে?\nসে ঘুমিয়ে আছে কালো গুটিরূপ আর আঠালো লাল তরলের ভেতর, স্বপ্নলোকের ফাঁক দিয়ে দূর নক্ষত্রমালার দিকে চেয়ে।\n\"খুব ঠান্ডা,\" সে বিড়বিড় করে, \"কিন্তু আমার উষ্ণতা গেল কোথায়?\""
