  CollectionHall_89706_Desc = {
    Text = "<Title:পরিচিতি>\nএতিম, উৎস অজানা। স্মৃতির শুরু থেকেই নাবিকদের দ্বারা লালিত-পালিত হয়ে জাহাজেই বেড়ে উঠেছে।\nএই অভিজ্ঞতার কারণে, কপারস্যান্ট ছোটবেলা থেকেই সমুদ্রের প্রতি গভীর আকাঙ্ক্ষা ও কৌতূহল পোষণ করত।\nবড় হয়ে সে স্বাভাবিকভাবেই সমুদ্র ও জাহাজ সম্পর্কিত পেশা বেছে নিয়েছে—নেভিগেটর।\nতারপর থেকে, সমুদ্রপ্রেমী এই তরুণী চিরকাল সাগরে ভেসে বেড়ায়, তারাদের সাথে মিলে জাহাজকে পথ দেখায়।\nসে সমুদ্রে, জাহাজে 「জন্মেছে」।\nসে সমুদ্রে, জাহাজে 「মৃত্যু」কেও ভয় পায় না।\nএটাই তার জীবন।"
  },
  CollectionHall_89706_LockTip = {
