  CollectionHall_89970_Desc = {
    Text = "সে জন্মেছিল ঘৃণা, রক্তপাত আর অবিরাম সংঘর্ষের নিয়তিতে। যখন সে সব কোমল মায়াস্বপ্ন ত্যাগ করে ছুরি আর বন্দুক তুলে নেওয়ার সিদ্ধান্ত নিল, তখনই নিয়তির বিজয়গাথা তার জন্য বাজতে শুরু করেছে। তার নিয়তি ছিল যোদ্ধা হওয়া—শত্রুর রক্তে নিজের ঘৃণা ধুয়ে ফেলা, তারপর এমন এক জীবন যাপন করা, যা হয়তো গৌরবময় নয়, কিন্তু নির্ভীক, অনুতাপহীন।"
