  CollectionHall_89973_Desc = {
    Text = "ওটা ছিল তার নিয়তির যুদ্ধ, সেই যুদ্ধক্ষেত্র যেখানে তাকে পৌঁছাতেই হবে।\nসে ঝেড়ে ফেলেছে অতীতের সব দুর্বলতা, দ্বিধা আর ভয়।\nতার কোনো আক্ষেপ নেই, কারণ সে বুঝে গেছে এই জীবনে লড়াইয়ের প্রকৃত অর্থ।\nসে একা নয়; তার হাতে ধরা ব্লেডে প্রতিফলিত হয়, আরেক সত্তার বুনো মুখ।"
