  CollectionHall_89974_Desc = {
    Text = "হেই হো, হেই হো, অ্যাঙ্কর তোলো, পাল তোলো, খুলে দাও শেষ দড়িটা।\nআমাদের নাবিক উঠে গেছে মাস্তুলের চূড়ায়, রঙিন পতাকা উড়ছে উঁচুতে।\nপাল তোলো, পাল তোলো, যে দিকে সে আঙুল তোলে, সে দিকেই আমরা পাল তোলো!"
