  CollectionHall_89976_Desc = {
    Text = "মরুভূমিতে বাতাস আর বালু হলো নির্দয় অতিথি; ঘূর্ণায়মান ধুলোর ঝড় জীবিতদের মুখ আর নাক ভরিয়ে দেয়, আর নামহীন মৃতদের ঢেকে পুঁতে ফেলে।\nশুধু সেই বন্যপশুরাই, যারা মাংসের জন্য ক্ষুধার্ত, বাতাসের ভেতর সূক্ষ্মভাবে খুঁজে ফেরে মিষ্টি মহাভোজের গন্ধ।"
