  CollectionHall_89978_Desc = {
    Text = "অন্তহীন তুষার ঝরে পড়ছে, বাতাসে নেচে নেচে, যোদ্ধাদের চুলে বরফের আস্তরণ চাপিয়ে দিচ্ছে।\nএই মুহূর্তে, তার জীবনের স্মৃতিচারণ স্রোতের মতো বয়ে যায়; সে মানুষের হৃদয়ের সূক্ষ্ম গভীরতা থেকে হেঁটে আসে, পা বাড়ায় আকাশছোঁয়া পর্বতমালার দিকে।\nবিশ্বাসঘাতকতা, পরিত্যাগ আর সুরক্ষা—সব যন্ত্রণা আর ক্রোধ কেবলই একের পর এক যুদ্ধ। মানুষের সঙ্গে, পর্বতমালার সঙ্গে, আর নিজের সঙ্গেও।\nসে তাকায় তার নেতার দিকে, আর সেই অচেনা অথচ পরিচিত নতুন সঙ্গীদের দিকে, মুখে টেনে আনে এক অপ্রস্তুত হাসি।\nএকদিন হয়তো সে বিজয়ী হবে, অথবা চিরতরে লুটিয়ে পড়বে যুদ্ধক্ষেত্রে; কিন্তু স্বর্গে আরোহণের কিংবা নরকে পতনের মুহূর্তেও সে হাতের ধারালো অস্ত্রটি ছাড়বে না।\nআবার সবকিছু হারানোর আগেই, এবার সে প্রতিশোধের আগে রক্ষার তরবারি তুলতে বেছে নিয়েছে, একাই পা বাড়িয়েছে তার নিজস্ব যুদ্ধক্ষেত্রের দিকে।"
