  CollectionHall_90416_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রদীপবাহক চার্চ তাদের দেবতা আহ্বান অনুষ্ঠানের জন্য তৈরি করা একাধিক পরীক্ষামূলক সৃষ্টির মধ্যে একটি। যমজ হিসেবে জন্মগ্রহণ করার সৌভাগ্যের কারণে আবর্জনার স্তূপে ফেলে দেওয়ার ভাগ্য থেকে রক্ষা পেয়েছিল।\nছোটবেলা থেকেই ভাই পলিডিউসিসের সাথে পবিত্র সন্তান হিসেবে সম্মানিত হয়ে কঠোর শৃঙ্খলার মধ্যে বেড়ে উঠেছে, সারাদিন প্রদীপবাহকের ধর্মতত্ত্ব শেখানো হতো। বাইরের জগৎ সম্পর্কে একমাত্র যে তথ্য পেয়েছিল তা ছিল একজন ভক্তের উৎসর্গ করা একটি সুন্দর ও ভারী হাতে লেখা পাণ্ডুলিপি।\nকিশোর বয়সে চার্চ যখন ভাইয়ের উপর নিষ্ঠুর রূপান্তর অনুষ্ঠান সম্পন্ন করে, তখন দুজনে মুক্তির সন্ধানে একসাথে পালানোর সিদ্ধান্ত নেয়, কিন্তু শীঘ্রই ধরা পড়ে যায়।\nতাকে 'পাপের গহ্বর' নামক ক্ষয়কারী জলাশয়ে ডুবিয়ে রাখা হয়েছিল, 'পাপের চিকিৎসা' দিয়ে ক্ষত সারানো হয়েছিল, এবং দীর্ঘ যন্ত্রণা সহ্য করতে হয়েছিল।\nশেষ পর্যন্ত এর ফলে জুলিয়েট ছাড়া সবাই তাকে ভুলে গিয়েছিল, পলিডিউসিস সহ, এবং ভাইয়ের সাথে সম্পর্কও শীতল হয়ে গিয়েছিল।\nতারপর থেকে নিজেকে লুকিয়ে রেখে, বাহ্যিকভাবে চার্চের প্রতি বাধ্য সেজে থাকলেও, অন্তরে ভাইকে নিয়ে আবার পালানোর আবেশ কখনো ত্যাগ করেনি, সর্বদা স্বাধীনতা ফিরে পাওয়ার সুযোগের অপেক্ষায় ছিল।"
  },
