  CollectionHall_94553_Desc = {
    Text = "<Title:পরিচিতি>\nপ্রদীপবাহক চার্চ দেবতা আহ্বান অনুষ্ঠানের জন্য তৈরি করা কৃত্রিম যমজ পরীক্ষামূলক নমুনা। পরীক্ষা ব্যর্থ বলে চিহ্নিত হয়ে নির্মমভাবে পরিত্যক্ত হওয়ার ঠিক আগে, সে তার দাদার রক্ত-মাংস থেকে বিভক্ত হয়ে জন্ম নেয়।\nবেঁচে থাকার সেই আকুল আকাঙ্ক্ষা সৌভাগ্য ছিল না, বরং এটি দুজনের ভাগ্যকে একটি সংক্ষিপ্ত বিয়োগান্তক থেকে আরও দীর্ঘতর এক বিয়োগান্তকে পরিবর্তিত করেছিল।\nসম্ভবত যমজ হওয়ার রহস্যের কারণেই, তার ত্বকের রং ও স্বভাব দাদার সম্পূর্ণ বিপরীত। যমজদের মধ্যে বেশি চঞ্চল ও চতুর হিসেবে, সে সবসময় নিয়মশৃঙ্খলার বিরুদ্ধে দুষ্টুমি করত, ঠিক যেন একটি সাধারণ পরিবারের দুরন্ত কিশোর — যতক্ষণ না তাকে দেবত্বের পাত্র হিসেবে লালন-পালনের জন্য নির্বাচিত করা হয় এবং নিয়মিত যন্ত্রণাদায়ক ও রক্তাক্ত 「পবিত্র রূপান্তর」 অনুষ্ঠান শুরু হয়।\nযন্ত্রণাময় ও আশাহীন ভাগ্য সহ্য করতে না পেরে, তার আকুতি ও পরিকল্পনায় দুই ভাই গোপন সংকেতে বছরের পর বছর ধরে পরিকল্পনা করে, অবশেষে অসংখ্য বাধা ভেদ করে সফলভাবে পালিয়ে যায়।\nতবে তারা বেশিক্ষণ আনন্দ করতে পারেনি, কারণ চার্চের অনুসরণকারীরা তাদের ধরে ফিরিয়ে আনে। লিয়েতের আদেশে তার স্বাধীনতার ডানা ছিঁড়ে ফেলা হয় এবং তার উপর চরম মগজধোলাই চালানো হয়, যার ফলে সে সম্পূর্ণরূপে দাদার কথা ভুলে যায় এবং সন্ত পুত্র হিসেবে মানুষের পূজা-অর্চনা উপভোগ করতে শুরু করে।\nযতক্ষণ না দ্বিতীয় পলায়নের পর দাদার মৃত্যু এবং দেবতা আহ্বান অনুষ্ঠানের প্রভাবে তার স্মৃতি ফিরে আসে, ঘৃণা ও ক্রোধ তার সেই 「পবিত্র হৃদয়」কে প্রজ্বলিত করে, এবং প্রদীপবাহক চার্চের বিরুদ্ধে লড়াই তার জীবনের নতুন লক্ষ্যে পরিণত হয়।"
