  CollectionHall_95440_Desc = {
    Text = "লন্ডিনিয়ামের শীত তুষারে ছিল কৃপণ, তাই যখনই তা ঝরত, বালকেরা মিটেন-ঢাকা হাতে উচ্ছ্বসিত ঘূর্ণিঝড়ে পরিণত হতো।\nতুমি শতবর্ষব্যাপী এক স্বপ্ন থেকে জেগে উঠে জানালার ফাঁক দিয়ে হাত বাড়ালে, আর ধরলে একটিমাত্র তুষারকণা। তৃপ্ত মনে, তা গলে গেল তোমার ত্বকের উষ্ণতায়।\nতুষার ভেসে ভেসে নেমে গেল মাটির দিকে, ফিরে গেল গোপন নদীগুলোর কাছে, সেই নীরব অন্ধকারে যেখানে সব জল মনে করে তারা আসলে এক।\nআর সেই বছরের প্রথম সত্যিকারের ঝড়ে, 「তার」 আরেকজন ফিরে এলো ঘরে।\nশুভরাত্রি, তুষারকণা। শুভরাত্রি, 「24।」"
