  CollectionHall_95443_Desc = {
    Text = "সে কি খুনি? সে দেখতে ঠিক সেই প্রেমিকার মতো, যাকে তুমি অন্য এক জীবনে চিনতে।\nবৃষ্টির জল, মৃত পাতা, আর রাতফোটা ফুলের মাদক গন্ধ। তুমি গভীর শ্বাস টেনে ভেজা বাতাসে খুঁজতে থাকো তার অপরাধের তামাটে গন্ধের প্রমাণ। কিছুই পাও না।\nসে কোনো ব্যাখ্যা দেয় না। কুয়াশা ঘন হতে থাকে, আর তুমি ডুবে যাও তার ছাইরঙা স্বপ্নের ভেতর।"
