  CollectionHall_95444_Desc = {
    Text = "এখন তুমি জানো, একসময় সে যে ক্ষুধা সহ্য করেছিল তার স্বাদ।\nঅবাধ্য। একাকী। অজ্ঞাতসারে ঘুরে বেড়ানো।\nসে ভাগ্যবতী: তার দীর্ঘ ভ্রমণ শেষ হয়েছে। সে উষ্ণ স্মৃতিচারণকে হাড়ের মতো আঁকড়ে ধরে, যা সে অনন্তকাল ধরে চিবিয়ে যাবে।\nএখন সে তার পরিজনের হাত ধরে, এই কাঁপতে থাকা পথহারা আত্মাটিকে স্বপ্নের নীরব অন্ধকারের দিকে পথ দেখিয়ে নিয়ে যায়।"
