  CollectionHall_98636_Desc = {
    Text = "অপবিত্রকারীরা এক মহাবিপর্যয়কর তরঙ্গ মুক্ত করো, কিন্তু একাকী রাজা একাই মুখোমুখি হয় সেই গর্জনরত জোয়ারের।\nতার চুল বাতাসে উড়ে, তার অস্থি আর রক্তই হয়ে ওঠে তার গম্ভীর ঘোষণা। অবজ্ঞামিশ্রিত এক হাসি নিয়ে, সে নিজেকে সমর্পণ করে মৃত্যু আর চাঁদের কাছে।\nসেই মুহূর্তেই সাগর হিমায়িত হয়ে যায়, পূর্ণিমার নিচে উল্টো ঝুলে থাকা এক হিমবাহ। সবকিছু স্তব্ধ হয়ে পড়ে, আর তার রাজ্যে ফিরে আসে নীরব শান্তি।"
  },
