  CollectionHall_98637_Desc = {
    Text = "মৃতদেহ রান্না করা এক গম্ভীর শিল্প।\nডাইনিং নাইফ আর স্প্যাটুলা হাতে সে খোঁজ নেয় অপূর্ণ অন্তিম অনুরোধের; জল আর আগুন দিয়ে সে পূর্ণ করে শেষ ইচ্ছাগুলো।\nপ্রতিটি স্মৃতিচারণ—বিব্রতকর, বেদনাদায়ক, তিক্ত—রূপ নেবে দীপ্তিময়, সুগন্ধি এক পদে, যা মানুষ আস্বাদন করবে, সযত্নে মনে রাখবে।"
  },
  CollectionHall_98637_LockTip = {
