  CollectionHall_98638_Desc = {
    Text = "শিশু চিৎকার করে, দাবি জানায়, উন্মত্ত হয়ে ওঠে।\nসে-ই মহাবিশ্বের কেন্দ্র। সে-ই সব হওয়ার বিধান।\nতার দৃষ্টিসীমার ভেতর যা আছে, সবকিছুকেই সেবা করতে হবে, মান্য করতে হবে, নইলে গ্রাস হতে হবে।"
