  CollectionHall_98639_Desc = {
    Text = "যখন সে প্রতিটি মৃত্যুকে সংগ্রহ করে, সে তার কাস্তে নির্মমভাবে দোলায় না。\nতার হাত একসময় ছিল উষ্ণ, তার হৃদয় ছিল কোমল, করুণায় পূর্ণ。\nযখন সে কোনো আত্মার শোক পান করে, সে তার সঙ্গে কাঁদে。\nযখন সে গহীন প্রোথিত ঘৃণার ওজন মাপে, সে তার পক্ষ থেকে বিচার কার্যকর করে。\nসে নেক্রোভিয়ার প্রভুর নামে এক গম্ভীর শপথ নিয়েছে: যারা মৃত্যু অপবিত্র করবে, তারা সবাই বিলীন হবে বরফশীতল, ঘন কুয়াশার ভেতর।"
  },
  CollectionHall_98639_LockTip = {
