  CollectionHall_98640_Desc = {
    Text = "মাংসের মিষ্টি স্বাদ, ছিঁড়ে যাওয়া টেন্ডনের গঠন—এগুলোই তার সবচেয়ে পরিচিত, সবচেয়ে ভোলার নয় এমন স্মৃতিচারণ।\nসে বহু আগেই বুঝে গেছে, নেক্রোভিয়া নগরী টিকে আছে তার মৃতদের উৎসর্গে, জীবিতদের শক্তিতে নয়।\nআরেক ঢোঁক রক্তিম তরল নেমে যায় তার গলায়। সে চোখ বন্ধ করে, প্রতিটি স্বতন্ত্র সুগন্ধ সাবধানে উপভোগ করে, প্রতিটি আত্মার স্বাদকে স্মৃতিতে গভীর ছাপ ফেলে রাখে। এইভাবে, তার প্রিয়জনেরা এবং তার জনগণ তার দেহের ভেতরেই অর্জন করে অনন্ত জীবন।\nতাদের প্রতিশ্রুতি দেওয়া হয়েছে—তারা থাকবে একসাথে, চিরকাল।"
  },
