  CollectionHall_98644_Desc = {
    Text = "তার নিজের জাতিই তার বিরুদ্ধে দাঁড়িয়েছিল, পতিত এক যুদ্ধপ্রধানকে ছুড়ে ফেলা হয়েছিল নির্বাসনে। কিন্তু ফিলিস্তিন ইতিহাসের সবচেয়ে শক্তিশালী শাসক, অভেদ্য ইচ্ছাশক্তির এক দৈত্য, তাদের জবাব দিয়েছিল কেবল হত্যাযজ্ঞ দিয়ে।\nঅন্তহীন আর্তনাদের মাঝখানে, তার তরবারি তৃষ্ণার্তের মতো পান করল রক্ত, ভাঙা লাশের গায়ে খোদাই করল তার যুদ্ধ-নীতির বাণী: স্বৈরাচারী, নির্মম, বর্বর, নিষ্ঠুর।\nএখানে দয়ার কোনো স্থান ছিল না।\nতারা ছিল কেবল তার ক্ষমতায় প্রত্যাবর্তনের পথে অপরিহার্য পাথেয়, পায়ের নিচের সিঁড়ির ধাপ।"
  },
