  CollectionHall_98645_Desc = {
    Text = "এলটন যখন পিঠ ফিরিয়ে চলে যায়, এক মুহূর্তের জন্য সে আবার সেই ছেলেটি হয়ে যায়, যে দিগন্তের দিকে তাকিয়ে থাকে, যেখানে আকাশ মিশেছে বিস্তৃত নীল সমুদ্রে—এক পৃথিবী, যেখানে প্রতিটি স্বপ্ন পূরণের মতো জায়গা আছে।\nকিন্তু এখন সে জানে পূর্ণ হওয়া স্বপ্নের আসল রূপ। এখন তার হাতে মানচিত্র, যা তাকে ফিরিয়ে নিয়ে যাবে শ্বেত পাখির দেশে।"
