  CollectionHall_99653_Desc = {
    Text = "「সেই মুহূর্তের」 অপেক্ষায়, মেয়েটি ঘুমিয়ে পড়েছিল হিমবাহের তলদেশে।\n\nএলওয়ার্থের গভীর বরফ তার দেহকে জমিয়ে ফেলেছিল, কিন্তু তার চেতনা পর্যন্ত পৌঁছাতে পারেনি।\n\nওই ক্ষীণ চেতনা ছিল এক বালকের—আর এক মায়ের।\n\nতাঁর কন্যার অন্ধকার গর্ভে, দেবতা স্বপ্ন দেখছিলেন এক অন্তহীন স্বপ্ন।\n\nএই পঁচিশ বছরে, সে কি কখনও কিছু ভেবেছে, আকুল হয়েছে, বা কোনো কিছুর আশায় বুক বেঁধেছে?\n\nএ প্রশ্নগুলোর উত্তর এখন আর কেউ দিতে পারবে না।\n\nআর মেয়েটি নিজে... সে কি তার চারপাশের মানুষের প্রতি হৃদয় উন্মুক্ত করবে?\n\nশুধু সময় আর ভবিষ্যৎই তার জবাব দিতে পারবে।"
  },
  CollectionHall_99653_Title = {
    Text = "হিমবাহের নিচে গভীর নিদ্রা"
  },
  CollectionHall_99654_Desc = {
    Text = "শুধু নীরবে মৃত্যুর দিকে গড়িয়ে পড়া জীবই আস্বাদনের যোগ্য।\nজীবিতরা লড়াই করে, আর লড়াই স্বাদকে তিক্ত করে তোলে।\n\nযখন থালাটি আসে, তার কেন্দ্রে থাকা হৃদয়টি তখনও সামান্য উষ্ণ, তার পৃষ্ঠ সামান্য ওঠানামা করছে, যেন মাঝ-ধাপের স্পন্দন।\nএক জোড়া চোখ তাকিয়ে আছে পাশে থেকে, তাদের মণি সেদ্ধ হয়ে অনুগত—দুধসাদা, তবু ধরে রেখেছে বিস্ময়ের শেষ ক্ষণটুকু।\n\nসে ছুরি তোলে, তারপর থেমে যায়।\n\nভেতরের আত্মা এখনো চিৎকার করছে।\nএক কবিতার মানুষের হৃদয়, অসুস্থতা আর মুক্তির মিশ্রণে ভেজা, তবু জড়িয়ে আছে এক শেষ অনুতাপে।\nসে ব্লেডটি নামিয়ে রাখে।\nদু’হাত জোড় করে।\nশোনে।\n\nএই পদকে সত্যিকারের সম্মান জানাতে হলে, তাকে অপেক্ষা করতে হবে।\n\nঅপেক্ষা করতে হবে, যতক্ষণ না মাংসের ভেতরের আবেশ খুলে যায়।\nঅপেক্ষা করতে হবে, যতক্ষণ না কবিতার মানুষের শেষ স্মৃতিচারণ গলে গিয়ে সুবাস হয়ে ওঠে—কালি আর ভেষজ, প্রেমিকের কাঁপা শ্বাস, ভোরের লাজুকতা।\n\nসে গভীর শ্বাস নেয়।\nবাতাস গল্পে গুনগুন করে।\n\nফিসফিসে গাছের নিচে, সে বসে থাকে, কবরের মতো ধৈর্য নিয়ে।\nফল পাকে, তারপরই ঝরে পড়ে।"
  },
  CollectionHall_99654_Title = {
    Text = "বীভৎস উপাদেয় খাদ্য"
  },
  CollectionHall_99655_Desc = {
    Text = "একটি পুষ্পগুচ্ছ, যা দীর্ঘদিন ফেলে রাখার ফলে শুকিয়ে ঝরে গেছে।\nএর মালিকের প্রত্যাবর্তন আর কোনোদিনই এটি দেখবে না।"
  },
  CollectionHall_99655_Title = {
    Text = "না-পাঠানো ফুল"
  },
  CollectionHall_99656_Desc = {
    Text = "জন্মের পর থেকেই, যমজদের কখনোই তাদের ডানা মেলে স্বাধীনভাবে উড়তে দেওয়া হয়নি।\n\nতাদের পিঠে গজিয়ে ওঠা দ্বিতীয় জোড়া বাহু যেন দুইটি আচার-পাত্র, পুত্রের মহিমা প্রদর্শন করে, যাদের সবসময় নির্দিষ্ট এক ভঙ্গিতে স্থির থাকতে আদেশ দেওয়া হয়েছে।\n\nশৈশবে, দুজনের মধ্যে পলুক্সই ছিল সেই ডানাগুলোর প্রতি সবচেয়ে সুরক্ষাময়; প্রতিদিন সেগুলো আঁচড়ে দিত, সুগন্ধি তেল মেখে রাখত, যাতে পালকগুলো সাটিনের মতো ঝলমল করে।\n\nএকাকিত্বের ক্ষণিক সুযোগ পেলেই সে গোপনে সেই সদ্য বিকশিত ডানাগুলো ঝাপটাত, দুলতে দুলতে মাটি ছেড়ে উঠত, ক্যাস্টরের বিস্মিত চোখের সামনে, হাত বাড়িয়ে উপরের অলংকৃত গম্বুজ ছুঁতে চাইত।\n\nপলুক্স যেমন তার ডানাগুলোকে নানা চটপটে ভঙ্গিতে নাচাতে পারত, তার তুলনায় ক্যাস্টরের প্রায়ই মনে হতো তার নিজের ডানাগুলো যেন দুইখানা কাঠের তক্তা, ভারী আর কদর্য।\n\nপ্রতিদিন শুতে যাওয়ার পর তাদের গোপন সময়ে, ক্যাস্টর চুপচাপ অন্ধকারে পলুক্সকে লাফাতে আর ঘুরতে দেখত, ছোট্ট সেই ঘেরাটোপের ভেতরেই উড়ানের অনুকরণ করতে।\n\n「ভাইয়ের ডানাগুলো কত সুন্দর, আর আমি হয়তো কোনোদিনই উড়তে শিখব না, 」 ভাবত ক্যাস্টর।\n\nতাই তাদের পলায়নের সেই রাতেই প্রথমবার ক্যাস্টর অনুভব করল সন্ধ্যার বাতাসের শীতলতা আর হালকাতা, যা তার ডানাগুলোকে তুলে নিচ্ছে।\n\nআরও দক্ষ পলুক্স শক্ত করে জড়িয়ে ধরেছিল তার কদর্যভাবে উড়তে থাকা ভাইকে, আকাশে হেসে উঠেছিল উল্লাসে, ডুব আর ঘূর্ণির বাঁক এঁকে, যেন সত্যিকারের আকাশের পাখি।\n\nক্যাস্টর মাথা ঘুরিয়ে দেখল, চাঁদের আলো পলুক্সের দীর্ঘ ও শক্তিশালী ডানায় সোনালি প্রলেপ দিচ্ছে, পালকের ফাঁকে প্রতিফলিত হচ্ছে এক ঝলমলে নীলচে-সবুজ আভা।\n\n「ওটাই নিশ্চয়ই পৃথিবীর সবচেয়ে সুন্দর জিনিস; যা-ই হোক না কেন, আমি পলুক্সকে রক্ষা করব, সেই ডানাগুলোকে সুরক্ষিত রাখব।」\n\nঅল্পদিনের মধ্যেই, কঠোর প্রান্তরের জীবন পলুক্সের ডানায় জন্তুর আঘাতের ক্ষত রেখে গেল।\n\nক্যাস্টর ভেঙে পড়া হৃদয়ে পলুক্সের ঝরে পড়া পালকগুলো কুড়িয়ে বুকে গুঁজে রাখল, নীরবে শপথ করল, এমনটা আর কখনো হতে দেবে না।\n\nকিন্তু সে জানত না, এই একাকী পালকটিই পরে হয়ে উঠবে তার সবচেয়ে গোপন সম্পদ, সেই ডানাগুলোর বিষয়ে তার হাতে থাকা শেষ স্মৃতিচিহ্ন।"
  },
  CollectionHall_99656_Title = {
    Text = "একাকী পালক"
  },
  CollectionHall_99657_Desc = {
    Text = "টুট—টুট—\n\nশিঙার শব্দ প্রতিধ্বনিত হতে হতে, করপোস্যান্টের দিকনির্দেশনায় ক্রুজ জাহাজটি নিরাপদে ঘাটে ভিড়ল।\n\nযাত্রীরা গ্যাংওয়ে বেয়ে নামতে নামতে হেসে উঠল, টুপি কাত করে তাকে ধন্যবাদ জানাল, আর নাবিকেরা ছুটে এসে তার প্রতি প্রশংসা জানাতে লাগল।\n\n「দারুণ কাজ, করপোস্যান্ট। তোমার আগাম সতর্কবার্তা না থাকলে, আমরা ঝড়ের মধ্যে গ্রাসিত হতাম।」\n\n「হ্যাঁ, তোমার সংশোধিত দিকনির্দেশনার জন্যই আমরা সমুদ্রে পথ হারাইনি!」\n\nনাবিকেরা হেসে তার কাঁধে চাপড় মারল, তাকে থাম্বস-আপ দেখাল।\n\nবাস্তবে, করপোস্যান্ট কখনোই এমন ঘনিষ্ঠ সামাজিক মেলামেশায় অভ্যস্ত হতে পারেনি; তার কঠোর ও যুক্তিনিষ্ঠ মস্তিষ্কে 「কাজ」 আর 「দায়িত্ব」 ছাড়া অন্য কোনো ভাবনা জাগে না।\n\nতাই, সে কেবল এটাকেই 「কাজ」 আর 「দায়িত্ব」-এরই একটি অংশ বলে ধরে নিল।\n\n「আমি শুধু আমার কাজটাই করেছি। একজন হালধর হিসেবে, তোমাদের নিরাপদে ঘরে পৌঁছে দেওয়াই আমার দায়িত্ব।」\n\nভদ্র অথচ নিরস উত্তর—তবু যারা তাকে ভালো চেনে, সেই নাবিকেরা হো হো করে হেসে বিদায় নিল, সমুদ্রগীতি গাইতে গাইতে, কাঁধে কাঁধ রেখে বন্দর ছেড়ে চলে গেল।\n\n「দ্য নটিলাস অবশেষে পাল তোলোতে পারবে। যাত্রা শুরু করো, নটিলাস।」\n\nগানের সুর ধীরে ধীরে মিলিয়ে গেল, আর করপোস্যান্ট তীরে দাঁড়িয়ে রইল, ভবিষ্যৎ যাত্রার প্রস্তুতিতে নিমগ্ন।\n\nসমুদ্র অনিশ্চিত; কোনো হালধরই প্রতিবার জয়ের নিশ্চয়তা দিতে পারে না; সেও পারে না। কিন্তু সামান্যতম সাফল্যের সম্ভাবনাও বাড়ানোর জন্য সে অসংখ্য সময় ব্যয় করতে প্রস্তুত।\n\nপরীক্ষা, টহল, শেখা, যাচাই—মনে হয় 「কাজ」ই তার জীবনে বাকি থাকা একমাত্র বিষয়।\n\nতবু সে তাতে রাজি, কারণ এই সবকিছুই সেই এক মুহূর্তের জন্য—সফল হালধরা, যখন সে সকলে‑কে নিরাপদে ঘরে ফিরিয়ে আনতে পারবে।"
  },
  CollectionHall_99657_Title = {
    Text = "সাগরের পথপ্রদর্শক"
  },
  CollectionHall_99658_Desc = {
    Text = "অন্তহীন অতল গহ্বরে নীলিমা সিংহাসন প্রহরীর মতো দাঁড়িয়ে,\nআকাশ নুয়ে পড়েছে, নক্ষত্র কাঁপে, সমগ্র সৃষ্টিই স্তব্ধ।\n\nপ্রাচীন ও রহস্যময় সত্তাগুলি সম্পূর্ণ বিলুপ্ত হয়েছে,\nতবু যুগের পর যুগ, নশ্বরেরা স্বপ্নে তাদের স্তোত্র গেয়ে যায়।\nঅতল জলের ঢেউ আর ধুলোর নিচে সিলমোহর করা গোপন কথা,\nতোমার হুইসপার জোয়ারের মতো উঠে, আত্মার গিরিখাত ডুবিয়ে দেয়।\n\nসেই সীমানাহীন স্বপ্নদৃশ্যে, নবী ও উন্মাদ পাশাপাশি হেঁটে চলে,\nঅদৃশ্য আত্মার খোঁজে, ভয় আর ভক্তি একসূত্রে গাঁথা।\nঅন্ধকার শ্যাওলায় জড়িয়ে থাকা সলতের পথ, যেন বোনা হচ্ছে কোনো নিয়তি,\nধীরে ধীরে পথহারা হৃদয়গুলোকে টেনে নিচ্ছে সেই নীলিমা সিংহাসনের দিকে।\nআহ, মহাবিশ্বের অযৌক্তিকতা আর তার সত্য,\nযেখানে স্বপ্ন আর বাস্তবের সংযোগস্থলে চিরন্তন এক দীপ্তি টিমটিম করে।"
  },
  CollectionHall_99658_Title = {
    Text = "নীলপাথরের সিংহাসন"
  },
  CollectionHall_99660_Desc = {
    Text = "সকলে ভাগ্যকে অমান্য করতে চায়, আবার তাকে ভয়ও পায়।\nসাহসীরা যুদ্ধের জন্য গর্জে ওঠে, ভীরুরা আত্মসমর্পণে হুইসপার করে, তবু একমাত্র সেও ভাগ্যকে জয় করার গোপন রহস্য উন্মোচন করেছিল।\nসে বারবার ভাগ্যকে জুয়ার নিমন্ত্রণ জানায়, তাকে আরেক দফা কার্ড বিলাতে তাগাদা দেয়।\nসে কখনো ভাগ্যকে ভয় পায়নি, বিশ্বাস করত সে কখনো হারবে না।\nসে কখনো জিজ্ঞাসা করেনি, কী বাজি রাখা হয়েছে; সবকিছু, এমনকি নিজের জীবনও টেবিলে তুলে ধরেছিল।\nএকটি রুলেট বন্দুক হাতে, সে অগণিত প্রতিদ্বন্দ্বীকে ভয় দেখিয়েছে এবং হয়ে উঠেছে লন্ডিনিয়ামের কুখ্যাত জুয়াখোর উন্মাদ।\nযোগ্য প্রতিপক্ষ না থাকলে, সে কত নিঃসঙ্গ।\nযতক্ষণ না সে সেই মানুষটির সঙ্গে দেখা পেল।\nসে অসংখ্য নশ্বরকে পরাজিত করে অবশেষে ভাগ্যের টেবিলে গিয়ে বসে।\nসে দ্রুত সবকিছু হারায়, তারপর সুদসহ সবই ফিরে পায়।\nপশু রূপে পুনর্জন্ম লাভ করে, সে খুঁজে পায় সেই বন্দুক, যা তার শেষ গুলি ছুড়েছিল।\nসে আবার তা ভরে, নিজের দিকে তাক করেই ট্রিগার টানে।\nনীরবতার মধ্যে, সে দাঁত বের করে হাসে।\nসে এখনো হারেনি, বিশ্বাস করে যে একদিন শেষ পর্যন্ত সে-ই জিতবে।\nযদিও তার মানে হয় সবকিছু বাজি রাখা।"
  },
  CollectionHall_99660_Title = {
    Text = "ভাগ্য রুলেট"
