  CollectionHall_99670_Desc = {
    Text = "কালো রক্ত থেকে পুনর্জন্ম নেওয়া মেয়েটি, মরুভূমির সহস্র বছরের বালুঝড়ের মাঝে তুলে ধরল প্রাচুর্যের মাতৃবৃক্ষের পবিত্র রক্তবীজ।\n\n「যতদিন এই বীজ পৃথিবীতে টিকে থাকবে, বৃক্ষের রক্তধারা কখনও শেষ হবে না।」\n\nতারপর কেটে গেল এক হাজার বছর।\n\nএই বীজ ভ্রমণ করল বৃক্ষের বংশধরদের সঙ্গে, দেখল গৌরব আর পতন, স্থানচ্যুতি আর হারিয়ে যাওয়া, মৃত্যু আর পুনরুত্থান।\n\nঅবশেষে, যখন প্রমত্ত নদী ঘন কালো রক্তে রূপ নিল, তখন সে সম্পন্ন করল তার চূড়ান্ত ধর্মদ্রোহীর রক্তের উত্তরাধিকার।\n\nওটা ছিল অগ্নিময়, জট পাকানো এক চুম্বন, অপূর্ণ কামনা আর না-বলা বিদায়বেদনা ভরা, উষ্ণ হৃদস্পন্দনের সঙ্গে নতুন উত্তরাধিকারিণীকে জড়িয়ে ধরেছিল।\n\nওই আগাত পাথরের মতো রঙ, ওই জেড পাথরের মতো দীপ্তি, কালো সমাপ্তিকেও অতিক্রম করে টিকে থাকবে, জীবনের স্পন্দনে কাঁপতে থাকবে।\n\nতারপর, তার আশীর্বাদে নতুন বিশ্বের প্রথম বীজ মাটির বুক থেকে উঠে আসবে, আকাশ ঢেকে দেওয়া এক মহাবৃক্ষে পরিণত হবে।"
  },
