  CollectionHall_99671_Desc = {
    Text = "পুনর্জন্ম নেওয়া ক্লেমেন্টাইন যেন এক সরল, অজ্ঞ লার্ভা—মানবজগতের ভেতর দিয়ে ভেসে বেড়াচ্ছে, এমন এক জাঁকজমকপূর্ণ জগতে ঘুরে বেড়াচ্ছে যা তার জাতির নয়, আর অনুভব করছে বিভ্রান্তি আর হতবুদ্ধি হওয়া।\nযতক্ষণ না সেই আত্মজাগরণময় কণ্ঠস্বরটি বেজে ওঠে—\n「মাফ করবেন, আপনি কি চিকিৎসক শার্লট? আমি চিকিৎসক শার্লটের কাছে মানসিক পরামর্শ নিতে এসেছি...」\nক্লেমেন্টাইন অবশেষে হুঁশে ফিরে আসে। শার্লট কে, তা নিয়ে তার বিন্দুমাত্র আগ্রহ নেই; সে কেবল কৌতূহলী হয়ে ওঠে আগন্তুকের মুখে উচ্চারিত নতুন শব্দটির প্রতি—「মানসিক পরামর্শ」।\nকিন্তু সে এক পরিপক্ব শিকারি, নিজের অজ্ঞতা কখনোই প্রকাশ করবে না; তাই সে হাসল, যেন সে-ই সেই শার্লট, আগন্তুকের মুখে উচ্চারিত ত্রাণকর্ত্রী।\nঅশ্রু, যন্ত্রণা, অসহায়তা—কোনো প্ররোচনার প্রয়োজন ছিল না; আগন্তুক নিজেই তার আত্মার গভীর থেকে ব্যথা নিংড়ে বের করে এনেছে।\nবিদায়ের আগে, আগন্তুক স্বস্তিময় অভিব্যক্তি নিয়ে ক্লেমেন্টাইনের দিকে তাকাল এবং দীর্ঘশ্বাস ফেলে বলল, 「শুনতে রাজি হওয়ার জন্য ধন্যবাদ। এখন নিজেকে অনেক হালকা লাগছে।」\nতারপর শোনা গেল দরজা বন্ধ হওয়ার শব্দ, আর তার সঙ্গে মিশে গেল ক্লেমেন্টাইনের হাসি—প্রথমবারের মতো মিষ্টতার স্বাদ পেয়ে ওঠা সেই হাসি।\nএই হাসি শুরু হয়েছিল খুব নিচু স্বরে, লার্ভার গুঞ্জনের মতো, তারপর ক্রমে উচ্চকিত হয়ে উঠল, যেন পূর্ণবয়স্ক কীটের কর্কশ চিৎকার।\nআর সেই হাসির ভেতরেই, ক্লেমেন্টাইন নামের ওই কীটজাতি দ্রুত পরিণত হয়ে উঠল।\nএরপর যা ঘটেছে, সব যেন স্বয়ংক্রিয়ভাবে জায়গামতো বসে গেছে। সে হয়ে উঠল এক মনোবিজ্ঞানী—ঠোঁটে হাসি, হাতে দোলক, প্রতিটি রোগীর হৃদয়ের গভীরে ডুব দেয় সে।\nসে এখনো মানুষের জগতে হেঁটে বেড়ায়, এখনও এই জাঁকজমকপূর্ণ জগতের অংশ নয়, কিন্তু আর বিভ্রান্ত বা হতবুদ্ধি নয়।\nকারণ সমগ্র মানবজগতই এখন তার সম্মোহনী শিকারের ক্ষেত্র।"
  },
  CollectionHall_99671_Title = {
    Text = "সম্মোহনী দোলক"
  },
  CollectionHall_99672_Desc = {
    Text = "সূর্য প্রতি সেকেন্ডে 300 সেক্সটিলিয়নেরও বেশি জুল শক্তি বিকিরণ করে, যার ক্ষুদ্র এক অংশ আলো ও তাপের রূপে 14.7 বিলিয়ন মিটার শূন্যতা পেরিয়ে পৃথিবীর দিকে ধেয়ে আসে।\n\nএই শক্তিই পৃথিবীর সব জীবনের ধারক, তার জটিল, বিস্তৃত, বিশৃঙ্খল তিন ডোমেইনের সব প্রজাতিকে বংশবিস্তার ও বিবর্তনের সুযোগ দেয়।\n\n\n\n「এটাই বিশ্বের সত্য, কোনো পরিস্থিতিতেই যা বদলায় না।」\n\nনিজের মানসিক স্থিতি বজায় রাখতে সে বারবার নিজেকে এ কথা স্মরণ করিয়ে দিত।\n\n「কিন্তু কেন... এত গরম, এত উজ্জ্বল?」\n\nকারণ যে বস্তুটি 14.7 বিলিয়ন মিটার দূরে থাকার কথা, তা ধীরে ধীরে তার মণি ভরিয়ে তুলছিল।\n\nআলো আর তাপ তার চোখ থেকে বিকিরিত হচ্ছিল, তার মহিমান্বিত দেহের প্রতিটি ইঞ্চি দগ্ধ করে দিচ্ছিল।\n\n「আমি এখন বুঝতে পারছি, এখন বুঝতে পারছি, বুঝতে পারছি কেন আলোকে পৃথিবীতে পৌঁছাতে 8 মিনিট 20 সেকেন্ড লাগে।」\n\n「কারণ আমরা সরাসরি আলোর মুখোমুখি হওয়ার মূল্য বহন করতে পারি না।」\n\nসবকিছু মেনে নিয়ে, সে উচ্চস্বরে হেসে উঠল।\n\n「তাহলে সত্যি বলতে, আমি সূর্যের এতটাই কাছে ছিলাম, যতটা ইকারাস কোনোদিনও ছিল না।」"
  },
  CollectionHall_99672_Title = {
    Text = "আসন্ন সূর্য"
  },
  CollectionHall_99673_Desc = {
    Text = "\"যথেষ্ট নিখুঁত হয়নি, আজ রাতে আরও দশবার অনুশীলন করবে। তোমার প্রতিভা মাঝারি মানের; অর্কেস্ট্রায় ঢুকতে চাইলে আরও বেশি পরিশ্রম করতে হবে, বুঝেছ?\"\n\"জি, বাবা।\"\nকেমন পারফরম্যান্সকে নিখুঁত বলা যায়?\nতার হাত থেমে না থেকে উড়ে বেড়াত, কোনো ভুলের সুযোগ না রেখে。\nসে নিজের ছুটে বেড়ানো চিন্তাগুলোকে ধমকাত, নিজের মাঝারি মানকে ঘৃণা করত。\nঅগণিত সুর তাকে ঘিরে থাকত; দিন গড়াত দিন, তার জীবনের সবকিছু ঘুরত শুধু সঙ্গীতকে কেন্দ্র করে。\nসৌভাগ্যবশত, প্রতিদিন সে নিখুঁত পরিবেশনার একটু করে কাছে পৌঁছাচ্ছিল, স্বপ্নে পথের শেষে থাকা আলোয় দৃষ্টি স্থির রেখে, তবু অনুভব করত যেন কোনোদিনই তার নাগাল পাবে না。\nনিখুঁততার প্রতি এই লালসা তার আত্মায় খোদাই হয়ে গেছে, অথচ সবাই এমন অনুভূতি নিয়ে বাঁচতে রাজি নয়。\n\"পবিত্র প্রভু আর সমগ্র বিশ্বের জন্য সবচেয়ে নিখুঁত সঙ্গীত পরিবেশন করা—এটাই কি অর্কেস্ট্রার দায়িত্ব নয়?\"\nসে সেই সব মুখের দিকে তাকাল, যেগুলো অসন্তোষ গোপন করে রেখেছে, যেন তারা তার আগের সত্তাকে তাচ্ছিল্য করছে。\nবাবা, রাজদরবারের অর্কেস্ট্রা এর বেশি কিছু নয়。\nসে একসময় পূজিত সেই লক্ষ্যকে ছুড়ে ফেলে দিল, আর একগুঁয়ে হয়ে নিখুঁততার সলতের পথে হাঁটা জারি রাখল。\nসে তাদের দিকে হাত বাড়াতে গিয়েও হাত থামাতে পারল না, যেমন সে তার অতীতের নিজের হাতও থামাতে পারেনি。\nপ্রতিদিন, সে অবিরাম বাজিয়ে যাচ্ছিল。\nসঙ্গীতই তার জীবন。\nসঙ্গীত ছাড়া, তার আর কিছুই নেই।"
  },
  CollectionHall_99673_Title = {
    Text = "অবিরাম পরিবেশনা"
  },
  CollectionHall_99674_Desc = {
    Text = "সে দাঁড়িয়ে ছিল শিখরের চূড়ায়, হাতে তোলা কালো শলাকা।\n\nপ্রচণ্ড তুষারঝড়ের মধ্যে, সে মুখোমুখি দাঁড়াল উন্মাদনার পর্বতের—আর সেই ভাগ্যের, যে তাকে ত্যাগ করেছে, বিশ্বাসঘাতকতা করেছে, চূর্ণবিচূর্ণ করেছে।\n\nশেষ পর্যন্ত সে-ই জিতবে;\nবরফ গলবে, আর সে ফিরে আসবে এক নতুন রূপে।\n\nএটাই সে বলেছিল।\n\nএলওয়ার্থ এক চরম শীতের দেশ, যেখানে বরফ কখনও গলে না।\n\nএটা সবার জানা কথা।\n\nযেমন কোনো যোদ্ধা, যতই শক্তিশালী হোক, অতিক্রম-সীমার সত্তার সঙ্গে পাল্লা দিতে পারে না, যেমন কেউ নিজের ভাগ্যকে অতিক্রম করতে পারে না।\n\nতবু, সেই পর্বতের বরফ তো গলেই গেল। তাই না?"
  },
  CollectionHall_99674_Title = {
    Text = "তুষার পর্বত গলনের কাল"
  },
  CollectionHall_99676_Desc = {
    Text = "প্রথম রানীর সঙ্গী এসেছিল ইসারাউ থেকে。\nতার ছিল এক জোড়া অনন্য ইসারাউ-বাসীর চোখ, ম্লান সোনালি আভা, যা পিচকালো রাতের আকাশে ক্ষীণ আলোয় ঝিলমিল করত。\nকিন্তু ইসারাউ পতনের সঙ্গে সঙ্গে সেই আলোও নিভে গেল, আর ওয়ান্ডা অন্ধকার কাদামাটি থেকে শেষ পাত্রটি তুলে আনল, সযত্নে তাকে আপন ধনরূপে আগলে রাখল。\nদ্বিতীয় ও তৃতীয় রানীর সঙ্গীর সঙ্গে তার দেখা হয়েছিল ফ্রান উচ্চভূমিতে。\nতারা ছিল লোভী যমজ প্রভু, আর ওয়ান্ডা আশা করেছিল তাদের শক্তি ব্যবহার করে হ্রদের মধ্যে নগরী, সেই হারানো শহরটি পুনর্গঠন করবে。\nসে প্রতারিত হয়েছিল, আর সেই কারণেই মেরুদণ্ড সূচ তাদের অস্থিমজ্জায় গভীরভাবে গেঁথে দেওয়া হয়। অবশ হয়ে পড়া দেহ থেকে ওয়ান্ডা টেনে নিয়েছিল সেই দুই জোড়া ঘৃণ্য ও অভদ্র চোখ, রেখে গিয়েছিল নিজের উপস্থিতির দাগ হিসেবে。\nচতুর্থ রানীর সঙ্গী—ওয়ান্ডা তাকে মনে রেখেছে 「জন」 নামে。\nসে ছিল এক বোকা বোবা, তবু সেবায় ত্রুটি রাখেনি। যা তাকে আরও তৃপ্ত করত, তা হলো 「জন」-এরও ছিল এক জোড়া ম্লান সোনালি চোখ, প্রায় তার নিজের চোখের প্রতিচ্ছবি। \n\n「চলো, রানীর সঙ্গীর চোখ দুটো উপড়ে ফেলি।」\n「আপনার ইচ্ছা… তবে কি রানীর সঙ্গী কোনো অপরাধ করেছে?」\nওয়ান্ডা কাপের ঘোলা জল ঘুরিয়ে ঘুরিয়ে দেখছিল, জিভে টের পাচ্ছিল বিষের স্থায়ী আস্তর। কী নির্বোধ, বিষ প্রয়োগের কাজটাও এমন কদর্যভাবে করেছে。\nডিজলিউশন-দগ্ধ ক্ষতে আচ্ছন্ন 「জন」-এর দিকে তাকিয়ে, তার মনে পড়ল সেই নিথর চোখগুলোর কথা, যারা তাকে বিদায় জানিয়েছিল তার জন্মভূমি থেকে, যখন সে তখনও ছিল নক্ষত্রদের মাঝে বহুদূরে。\nসেই চোখগুলো ঠিক এই মুহূর্তের 「জন」-এর চোখের মতোই ছিল。\n「…ধরো, তার রসবোধের অভাব আছে।」"
  },
