  CollectionHall_99679_Desc = {
    Text = "ডাইনী আর চওড়া-ধার টুপির সম্পর্ক কখনো কখনো মুরগি আর ডিমের সম্পর্কের মতো; বোঝা কঠিন, টুপিই কি ডাইনীকে সৃষ্টি করেছে, নাকি ডাইনীই টুপিকে।\nযাই হোক, ড্যাফোডিলের কাছে এমনই এক সুশ্রী চওড়া-ধার টুপি আছে।\nএই টুপিটি মূলত আগের দোকানদারের ছিল, সেই সময়ে যখন 「ড্যাফোডিল「 নামটি এখনো তার নিজের হয়ে ওঠেনি। তখন সে ছিল কেবল এক বিভ্রান্ত আত্মা—বশীভূত আর হতচকিত, অজ্ঞ পশুর মতো।\nযে নারী সবসময় হাসিমুখে থাকত, সে-ই তাকে নিজের কাছে নিয়ে গেল, ধৈর্য ধরে, শিশুকে শেখানোর মতো করে, অল্প অল্প করে শেখাতে লাগল কীভাবে 「মানুষ「 হতে হয়, আর অন্যদের সঙ্গে মিশে থাকার গোপন নিয়মগুলো।\nকোলাহলময় বন্দরনগরীটি তখন মানবসভ্যতার সবচেয়ে সমৃদ্ধ স্ফটিকভাগগুলোকে একত্র করেছিল। যে রাস্তায় বিনিময় কেন্দ্রের দোকানটি ছিল, সেখানে সারি সারি দোকান, অসংখ্য পণ্যের সমাহার, আর দোকানদার যেন সব দোকানির সঙ্গেই পুরাতন বন্ধুর মতো আড্ডা দিত।\n「তিনি সত্যিই অসাধারণ,「 তখন ভাবত ড্যাফোডিল, 「কিন্তু এতে আশ্চর্য কিছু নেই; তাকে অপছন্দ করার মতো কেউ নেই।「\nদোকানদার কেনাকাটা করতে ভালোবাসতেন, তাই সহস্রাব্দের মধ্যে প্রথমবারের মতো, ড্যাফোডিল—যে এতদিন ধরে কেবল নিজের কেটে নেওয়া মানুষের মাথা নিয়ে মানুষ সেজে ঘুরে বেড়াত—তাকে মতামত জানাতে বলা হলো।\n「তোমার কী মনে হয়, কোনটা দেখতে ভালো? এই ছোট টপ হ্যাটটা, নাকি এই চওড়া-ধার টুপিটা?「\nনারীটি আয়নার সামনে একের পর এক ঝলমলে টুপি পরে দেখছিলেন। ড্যাফোডিলের কাছে সেগুলো কেবলই ছিল প্রপ—দেহ জড়িয়ে নিজেকে আরও মানবীয় দেখানোর মোড়ক।\nকিন্তু সেদিন, যখন সে দেখছিল দোকানদারকে, মাথায় চওড়া-ধার টুপিটা যেন এক বিশাল ফুলের মতো ফুটে আছে, হঠাৎ তার মনে ভেসে উঠল এক দৃশ্য—এই নারী এমন টুপি পরে আছে, আর তারা দু」জন পাশাপাশি সমুদ্রতটে হাঁটছে।\n「এইটা,「 সে হঠাৎ বলে উঠল, 「এই একটাই।「\nদোকানদার অবাক হয়ে ফিরে তাকালেন, যেন তিনি আশা করেননি ড্যাফোডিল এত স্পষ্টভাবে নিজের পছন্দ প্রকাশ করবে।\n「ঠিক আছে, সত্যিই খুব সুন্দর টুপি। যেহেতু তুমি আমার জন্য বেছেছ, আমি একে খুব যত্ন করে রাখব।「\nড্যাফোডিলকে উৎসাহ দেওয়ার জন্যই হোক বা না হোক, দোকানদার যেমন প্রতিশ্রুতি দিয়েছিলেন, টুপিটি সত্যিই তার মাথায় এক স্থায়ী অলংকার হয়ে রইল—শেষ মুহূর্ত পর্যন্ত, যখন তিনি নিজের হাসিমাখা মাথাসহ টুপিটি ড্যাফোডিলের হাতে তুলে দিলেন।\n「কি সুন্দর টুপি, আমি অবশ্যই একে খুব যত্ন করে রাখব।「\nঅবশেষে নতুন মালিকের মাথায় ফুটে উঠল সেই অপূর্ব বেগুনি-কালো ফুল।"
