  CollectionHall_99683_Desc = {
    Text = "সিংহাসনে তাঁর স্বপ্নের মধ্যে, রাজা শুনলেন দিব্য প্রত্যাদেশ:\n\nলেমুরিয়ার ঝড় থেমে যাবে।\nলেমুরিয়ার অতল গহ্বর বিলীন হবে।\n\nস্বপ্ন হবে তাঁর প্রাসাদ, নক্ষত্র হবে তাঁর প্রদীপ,\nরাজা তাঁর স্নেহময় প্রজাদের রক্ষা করবেন, আর আনবেন দিব্য রাজ্য।\n\nহে আমাদের প্রভুর অনুসারী, তোমার হৃদয় উন্মুক্ত করো আমাদের প্রভুর প্রতি।\n\nদূর, সূর্যহীন অতল গহ্বরে, মহান প্রাচীন আত্মা তন্দ্রায়, দেবতাদের হুইসপার শোনে।\n\nতাঁর ইচ্ছা বোনা থাকে নক্ষত্রের জালের মতো;\nঅনন্ত শূন্যতায়, তিনি অপেক্ষা করেন তুমি যেন প্রবেশ করো তাঁর স্বপ্নে।\n\nঝড় নতজানু, জলের ঢেউ স্তব্ধ;\nভূমিকম্প থেমে যায়, ভূমি পায় বিশ্রাম।\n\nতাঁর শান্ত স্বপ্নের ভেতর বিপর্যয় দ্রবীভূত হয়ে শূন্যতায় মিশে যায়,\nআর তাঁর প্রজারা থাকে নিরাপদ, তাঁর সুরক্ষার ছায়াতলে।\n\nআমাদের গান যেন পাড়ি দেয় গভীর সাগর,\nতিনি যেন আমাদের দান করেন বিপর্যয়হীন বিশ্বের ওরাকল,\nতিনি যেন আমাদের পথ দেখান অন্তহীন শান্তি ও পরমানন্দের দিকে।\n\nতারকা ক্ষয়ে যাওয়া পর্যন্ত, সময়ের অবসান হওয়া পর্যন্ত, আমাদের বিশ্বাস তাঁর সঙ্গেই থাকবে।"
  },
