  CollectionHall_99691_Desc = {
    Text = "ফ্রান্সিস একবার লিলিকে বলেছিল, গল্পের মধ্যেই লুকিয়ে থাকে জাদু।\n\nসেই সময়, ফ্রান্সিস জানালার ধারে বসত গল্পের বই নিয়ে, তার ল্যাব কোটে গ্রীষ্মের শুরুর রোদ পড়ে উষ্ণ হয়ে উঠত, ছড়িয়ে দিত নরম, সান্ত্বনাদায়ক গন্ধ।\n\nফ্রান্সিসের কণ্ঠ ছিল কোমল, ধীরস্থির; কিন্তু দীর্ঘ রাতের অস্ত্রোপচার তাকে নিঃশেষ করে দিয়েছিল। গল্প শেষ হওয়ার আগেই, সে তন্দ্রায় তলিয়ে যেত।\n\nলিলি কখনও তার মায়ের ওপর ক্ষুব্ধ হয়নি।\n\nজানালার ধারে হেলান দিয়ে তার মাকে ঘুমাতে দেখলে, ক্লান্ত অথচ শান্ত মুখটা দেখে, লিলির মনে এক অদ্ভুত নিশ্চিন্ততা নেমে আসত।\n\n\nএখন, বইয়ের জায়গায় গল্প আর জাদু বহন করে নিয়ে যায় ফিল্ম; যেমন নতুন রিল এসে জায়গা নেয় বালকদের হাতে নষ্ট হয়ে যাওয়া পুরোনো রিলের, আর নতুন বন্ধুদের হাসি এসে বসে যায় সেই নীরব বিকেলগুলোর জায়গায়—উষ্ণ, অথচ হালকা ব্যথায় রঙিন।\n\nতবু, মাটিচাপা পড়ে থাকা সেই স্মৃতিচারণ এখনও মৃদু আলো ছড়ায়, যেন কোনো ভুলে যাওয়া ড্রয়ারে লুকিয়ে থাকা উন্মুক্ত ফিল্ম—চোখের আড়ালে, কিন্তু কখনও নিভে যায় না।"
